package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerStats;
import me.libraryaddict.disguise.DisguiseAPI;
import me.libraryaddict.disguise.disguisetypes.DisguiseType;
import me.libraryaddict.disguise.disguisetypes.MobDisguise;
import org.bukkit.*;
import org.bukkit.attribute.Attribute;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityTargetEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.metadata.FixedMetadataValue;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * BeastManager — 野獸系天賦管理器
 *
 * 負責：
 * 1. 馴服野獸（召喚寵物，擊殺歸屬玩家）
 * 2. 化身野獸（變身系統，屬性加成）
 */
public class BeastManager implements Listener {

    private final CustomRPG plugin;

    // 玩家召喚的野獸 Map<PlayerUUID, List<EntityUUID>>
    private final Map<UUID, List<UUID>> playerBeasts = new ConcurrentHashMap<>();
    // 野獸→主人映射 Map<EntityUUID, PlayerUUID>
    private final Map<UUID, UUID> beastOwners = new ConcurrentHashMap<>();

    // 玩家當前變身狀態 Map<PlayerUUID, BeastFormData>
    private final Map<UUID, BeastFormData> activeForms = new ConcurrentHashMap<>();

    // 每個玩家最多召喚幾隻野獸
    private static final int MAX_BEASTS_PER_PLAYER = 5;

    public BeastManager(CustomRPG plugin) {
        this.plugin = plugin;
        Bukkit.getPluginManager().registerEvents(this, plugin);

        // 定時清理死掉的野獸
        new BukkitRunnable() {
            @Override
            public void run() {
                cleanupDeadBeasts();
            }
        }.runTaskTimer(plugin, 100L, 100L);
    }

    // ═══════════════════════════════════════
    //  馴服野獸 — 召喚系統
    // ═══════════════════════════════════════

    /**
     * 召喚野獸
     * @param player 召喚者
     * @param entityType 野獸類型 (WOLF, POLAR_BEAR, etc.)
     * @param name 顯示名稱
     * @param health 生命值
     * @param damage 攻擊力
     * @param duration 持續時間(秒)，0=永久
     * @param count 召喚數量
     * @return 是否成功
     */
    public boolean summonBeast(Player player, EntityType entityType, String name,
                               double health, double damage, int duration, int count) {
        UUID pid = player.getUniqueId();
        List<UUID> existing = playerBeasts.getOrDefault(pid, new ArrayList<>());

        // 清理已死亡的
        existing.removeIf(uuid -> {
            Entity e = Bukkit.getEntity(uuid);
            return e == null || e.isDead();
        });

        if (existing.size() + count > MAX_BEASTS_PER_PLAYER) {
            player.sendMessage("§c你已經召喚了太多野獸！(上限 " + MAX_BEASTS_PER_PLAYER + " 隻)");
            return false;
        }

        Location spawnLoc = player.getLocation().add(
                player.getLocation().getDirection().setY(0).normalize().multiply(2));

        for (int i = 0; i < count; i++) {
            // 每隻稍微偏移位置
            Location loc = spawnLoc.clone().add(
                    (Math.random() - 0.5) * 3, 0, (Math.random() - 0.5) * 3);

            LivingEntity beast = (LivingEntity) player.getWorld().spawnEntity(loc, entityType);

            // 設定名稱
            setBeastNameWithHealth(beast, player, name);

            // 設定血量
            if (beast.getAttribute(Attribute.MAX_HEALTH) != null) {
                beast.getAttribute(Attribute.MAX_HEALTH).setBaseValue(health);
                beast.setHealth(health);
            }

            // 設定攻擊力
            if (beast.getAttribute(Attribute.ATTACK_DAMAGE) != null) {
                beast.getAttribute(Attribute.ATTACK_DAMAGE).setBaseValue(damage);
            }

            // 標記為玩家的野獸
            beast.setMetadata("beast_owner", new FixedMetadataValue(plugin, pid.toString()));
            beast.setMetadata("beast_damage", new FixedMetadataValue(plugin, damage));
            beast.setMetadata("beast_base_name", new FixedMetadataValue(plugin, name));

            // 如果是可馴服的動物（如狼），設定主人
            if (beast instanceof Tameable tameable) {
                tameable.setTamed(true);
                tameable.setOwner(player);
            }

            // 不會被其他機制清除
            beast.setRemoveWhenFarAway(false);
            beast.setPersistent(true);

            // 記錄
            existing.add(beast.getUniqueId());
            beastOwners.put(beast.getUniqueId(), pid);

            // 生成粒子
            beast.getWorld().spawnParticle(Particle.HEART, beast.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);
        }

        playerBeasts.put(pid, existing);

        // 定時消失
        if (duration > 0) {
            List<UUID> beastIds = new ArrayList<>(existing);
            new BukkitRunnable() {
                @Override
                public void run() {
                    for (UUID beastId : beastIds) {
                        Entity e = Bukkit.getEntity(beastId);
                        if (e != null && !e.isDead()) {
                            e.getWorld().spawnParticle(Particle.SMOKE, e.getLocation().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.02);
                            e.remove();
                        }
                        beastOwners.remove(beastId);
                    }
                    List<UUID> current = playerBeasts.get(pid);
                    if (current != null) {
                        current.removeAll(beastIds);
                    }
                }
            }.runTaskLater(plugin, duration * 20L);
        }

        return true;
    }

    /**
     * 移除玩家的所有野獸
     */
    public void removeAllBeasts(Player player) {
        UUID pid = player.getUniqueId();
        List<UUID> beasts = playerBeasts.remove(pid);
        if (beasts == null) return;
        for (UUID beastId : beasts) {
            Entity e = Bukkit.getEntity(beastId);
            if (e != null && !e.isDead()) {
                e.getWorld().spawnParticle(Particle.SMOKE, e.getLocation().add(0, 0.5, 0), 10, 0.3, 0.5, 0.3, 0.02);
                e.remove();
            }
            beastOwners.remove(beastId);
        }
    }

    /**
     * 獲取玩家當前召喚的野獸數量
     */
    public int getBeastCount(Player player) {
        List<UUID> beasts = playerBeasts.get(player.getUniqueId());
        if (beasts == null) return 0;
        beasts.removeIf(uuid -> {
            Entity e = Bukkit.getEntity(uuid);
            return e == null || e.isDead();
        });
        return beasts.size();
    }

    /**
     * 直接將已生成的野獸實體登錄給玩家（不受上限限制）
     * 用於有特殊邏輯的技能（如蜂巢誓盟）
     */
    public void registerExistingBeast(Player player, LivingEntity beast, double damage) {
        UUID pid = player.getUniqueId();
        beast.setMetadata("beast_owner", new FixedMetadataValue(plugin, pid.toString()));
        beast.setMetadata("beast_damage", new FixedMetadataValue(plugin, damage));
        // 記錄基礎名稱（去掉顏色前綴的純文字，用於健康名稱更新）
        String rawName = beast.getCustomName();
        if (rawName == null) rawName = beast.getType().name();
        beast.setMetadata("beast_base_name", new FixedMetadataValue(plugin, rawName));
        beast.setRemoveWhenFarAway(false);
        beast.setPersistent(true);

        List<UUID> existing = playerBeasts.computeIfAbsent(pid, k -> new ArrayList<>());
        existing.add(beast.getUniqueId());
        beastOwners.put(beast.getUniqueId(), pid);
    }

    // ═══════════════════════════════════════
    //  化身野獸 — 變身系統
    // ═══════════════════════════════════════

    /**
     * 啟動變身
     * @param player 玩家
     * @param formType 變身類型 (wolf, polar_bear, etc.)
     * @param duration 持續時間(秒)
     * @param strengthBonus 力量加成
     * @param healthBonus 生命值加成
     * @param speedLevel 速度等級
     * @param damageBoost 傷害提升等級
     */
    public boolean activateBeastForm(Player player, String formType, int duration,
                                     double strengthBonus, double healthBonus,
                                     int speedLevel, int damageBoost) {
        UUID pid = player.getUniqueId();

        // 如果已經變身，先取消
        if (activeForms.containsKey(pid)) {
            deactivateBeastForm(player);
        }

        BeastFormData data = new BeastFormData();
        data.formType = formType;
        data.originalMaxHealth = player.getAttribute(Attribute.MAX_HEALTH).getBaseValue();
        data.healthBonus = healthBonus;
        data.strengthBonus = strengthBonus;

        activeForms.put(pid, data);

        // 增加最大生命值
        if (healthBonus > 0) {
            double newMax = data.originalMaxHealth + healthBonus;
            player.getAttribute(Attribute.MAX_HEALTH).setBaseValue(newMax);
            player.setHealth(Math.min(player.getHealth() + healthBonus, newMax));
        }

        // 增加力量
        player.setMetadata("beast_form_strength", new FixedMetadataValue(plugin, strengthBonus));

        // 藥水效果
        if (speedLevel > 0) {
            player.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, duration * 20, speedLevel - 1, true, false));
        }
        if (damageBoost > 0) {
            player.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH, duration * 20, damageBoost - 1, true, false));
        }
        player.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE, duration * 20, 0, true, false));

        // 變身視覺提示
        String formName = getFormDisplayName(formType);
        player.sendMessage("§6§l[野獸化身] §a你變身為 §e" + formName + " §a！持續 §f" + duration + " §a秒");
        player.getWorld().spawnParticle(Particle.TOTEM_OF_UNDYING, player.getLocation().add(0, 1, 0), 30, 0.5, 1, 0.5, 0.3);
        player.playSound(player.getLocation(), Sound.ENTITY_WOLF_AMBIENT, 1.5f, 0.8f);

        // ActionBar 提示
        new BukkitRunnable() {
            int remaining = duration;
            @Override
            public void run() {
                if (remaining <= 0 || !activeForms.containsKey(pid)) {
                    if (activeForms.containsKey(pid)) {
                        deactivateBeastForm(player);
                    }
                    cancel();
                    return;
                }
                player.sendActionBar("§6§l[" + formName + "] §e剩餘 " + remaining + " 秒 §7| §c力量+" + (int) strengthBonus + " §a生命+" + (int) healthBonus);
                remaining--;
            }
        }.runTaskTimer(plugin, 0L, 20L);

        return true;
    }

    /**
     * 取消變身
     */
    public void deactivateBeastForm(Player player) {
        UUID pid = player.getUniqueId();
        BeastFormData data = activeForms.remove(pid);
        if (data == null) return;

        // 恢復最大生命值
        player.getAttribute(Attribute.MAX_HEALTH).setBaseValue(data.originalMaxHealth);
        if (player.getHealth() > data.originalMaxHealth) {
            player.setHealth(data.originalMaxHealth);
        }

        player.removeMetadata("beast_form_strength", plugin);

        player.sendMessage("§6§l[野獸化身] §7變身效果已結束");
        player.playSound(player.getLocation(), Sound.ENTITY_WOLF_AMBIENT, 1.0f, 1.2f);
        player.getWorld().spawnParticle(Particle.SMOKE, player.getLocation().add(0, 1, 0), 20, 0.5, 1, 0.5, 0.05);
    }

    /**
     * 玩家是否在變身狀態
     */
    public boolean isInBeastForm(Player player) {
        return activeForms.containsKey(player.getUniqueId());
    }

    /**
     * 獲取變身的力量加成
     */
    public double getBeastFormStrengthBonus(Player player) {
        BeastFormData data = activeForms.get(player.getUniqueId());
        return data != null ? data.strengthBonus : 0;
    }

    // ═══════════════════════════════════════
    //  事件監聽
    // ═══════════════════════════════════════

    /**
     * 野獸擊殺怪物時，歸屬給主人（用於經驗值/掉落）
     * 使用 LOWEST 確保在 MobListener 處理死亡前先設置 metadata
     */
    @EventHandler(priority = EventPriority.LOWEST)
    public void onBeastKill(EntityDeathEvent event) {
        LivingEntity victim = event.getEntity();
        Entity killer = victim.getKiller();

        // 如果已經有玩家擊殺者，跳過
        if (killer instanceof Player) return;

        // 檢查最後傷害來源是否是玩家的野獸
        if (victim.getLastDamageCause() instanceof EntityDamageByEntityEvent dmgEvent) {
            Entity damager = dmgEvent.getDamager();
            if (damager.hasMetadata("beast_owner")) {
                String ownerStr = damager.getMetadata("beast_owner").get(0).asString();
                UUID ownerId = UUID.fromString(ownerStr);
                Player owner = Bukkit.getPlayer(ownerId);
                if (owner != null && owner.isOnline()) {
                    // 模擬玩家擊殺：設定經驗值掉落來源
                    // Bukkit 無法直接 setKiller，但可以透過傷害事件讓 MobListener 處理
                    victim.setMetadata("beast_kill_owner", new FixedMetadataValue(plugin, ownerId.toString()));
                }
            }
        }
    }

    /**
     * 讓野獸攻擊時附帶主人的部分屬性加成
     */
    @EventHandler(priority = EventPriority.NORMAL)
    public void onBeastAttack(EntityDamageByEntityEvent event) {
        Entity damager = event.getDamager();
        if (!damager.hasMetadata("beast_owner")) return;

        // 野獸的基礎傷害已在生成時設定
        // 這裡可以加入額外效果（如毒、緩速等）

        // 讓野獸的目標與玩家一致
        if (event.getEntity() instanceof Player) {
            // 野獸不應該攻擊玩家
            String ownerStr = damager.getMetadata("beast_owner").get(0).asString();
            UUID ownerId = UUID.fromString(ownerStr);
            if (event.getEntity().getUniqueId().equals(ownerId)) {
                event.setCancelled(true);
            }
        }
    }

    /**
     * 防止野獸攻擊自己的主人
     * 蜜蜂額外：玩家打到蜜蜂時重置生氣狀態
     */
    @EventHandler
    public void onBeastTarget(EntityTargetEvent event) {
        Entity entity = event.getEntity();
        Entity target = event.getTarget();
        if (entity.hasMetadata("beast_owner") && target instanceof Player player) {
            String ownerStr = entity.getMetadata("beast_owner").get(0).asString();
            if (player.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
                // 如果是蜜蜂，清除目標（EntityTargetEvent 會阻止後續攻擊）
                if (entity instanceof org.bukkit.entity.Bee bee) {
                    bee.setTarget(null);
                }
            }
        }
    }

    /**
     * 防止攻擊蜂 stinger 傷害主人；守護蜂永不攻擊任何人
     * （EntityDamageByEntityEvent 已在 onBeastAttack 中覆蓋，這裡補充蜜蜂場景）
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onBeeAttackOwner(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof org.bukkit.entity.Bee bee)) return;
        if (!bee.hasMetadata("beast_owner")) return;
        // 守護蜂絕對不攻擊任何人
        if (bee.hasMetadata("bee_companion")) {
            event.setCancelled(true);
            bee.setTarget(null);
            return;
        }
        // 攻擊蜂不攻擊主人
        if (event.getEntity() instanceof Player victim) {
            String ownerStr = bee.getMetadata("beast_owner").get(0).asString();
            if (victim.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
                bee.setTarget(null);
            }
        }
    }

    /**
     * 阻止召喚蜜蜂對主人產生生氣（使用 Paper 的 EntityTargetEvent 就足夠了，
     * 但若伺服器支援 EntityAngerEvent 也攔截）
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBeeAnger(org.bukkit.event.entity.EntityTargetEvent event) {
        // EntityTargetEvent 已在 onBeastTarget 中處理，此為備援
        Entity entity = event.getEntity();
        Entity target = event.getTarget();
        if (!(entity instanceof org.bukkit.entity.Bee bee)) return;
        if (!bee.hasMetadata("beast_owner")) return;
        // 守護蜂永不攻擊任何人
        if (bee.hasMetadata("bee_companion")) {
            event.setCancelled(true);
            return;
        }
        // 攻擊蜂不攻擊主人
        if (target instanceof Player player) {
            String ownerStr = bee.getMetadata("beast_owner").get(0).asString();
            if (player.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
            }
        }
    }

    /**
     * 玩家離線時清除所有野獸和變身
     */
    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        removeAllBeasts(event.getPlayer());
        if (activeForms.containsKey(event.getPlayer().getUniqueId())) {
            deactivateBeastForm(event.getPlayer());
        }
    }

    /**
     * 玩家攻擊怪物時，讓其北極熊與攻擊蜂自動協助攻擊同一目標
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPlayerAttackMob(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof Player player)) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;
        if (target instanceof Player) return; // 不協助攻擊玩家
        // 忽略攻擊到自己的野獸（避免讓野獸互打）
        if (target.hasMetadata("beast_owner")) return;

        UUID pid = player.getUniqueId();
        List<UUID> beasts = playerBeasts.get(pid);
        if (beasts == null) return;
        for (UUID beastId : beasts) {
            Entity e = Bukkit.getEntity(beastId);
            if (e == null || e.isDead()) continue;
            if (e instanceof PolarBear bear) {
                bear.setTarget(target);
            } else if (e instanceof org.bukkit.entity.Bee bee) {
                // 只有攻擊蜂跟隨目標（守護蜂不攻擊）
                if (!e.hasMetadata("bee_companion")) {
                    // 用 metadata 記錄目標 UUID，讓手動控制 loop 讀取
                    bee.setMetadata("bee_attack_target",
                            new FixedMetadataValue(plugin, target.getUniqueId().toString()));
                }
            }
        }
    }

    /**
     * 召喚時名稱加上血量
     */
    private void setBeastNameWithHealth(LivingEntity beast, Player player, String name) {
        int hp = (int) beast.getHealth();
        int maxHp = (int) beast.getAttribute(Attribute.MAX_HEALTH).getBaseValue();
        beast.setCustomName("§a[" + player.getName() + "的] §f" + name + " §c❤" + hp + "/" + maxHp);
        beast.setCustomNameVisible(true);
    }

    // 受傷時自動更新名稱
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBeastHurt(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof LivingEntity beast)) return;
        if (!beast.hasMetadata("beast_owner")) return;
        Player owner = null;
        try {
            owner = Bukkit.getPlayer(UUID.fromString(beast.getMetadata("beast_owner").get(0).asString()));
        } catch (Exception ignored) {}
        if (owner == null) return;
        // 使用 metadata 記錄的基礎名稱，避免重複疊加玩家名前綴
        String baseName = beast.hasMetadata("beast_base_name")
                ? beast.getMetadata("beast_base_name").get(0).asString()
                : beast.getType().name();
        setBeastNameWithHealth(beast, owner, baseName);
    }

    // 寵物攻擊怪物時顯示傷害浮空字
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBeastDealDamage(EntityDamageByEntityEvent event) {
        Entity damager = event.getDamager();
        if (!damager.hasMetadata("beast_owner")) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;
        double damage = event.getFinalDamage();
        // 顯示浮空字
        target.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, target.getLocation().add(0, 1.2, 0), 8, 0.2, 0.2, 0.2, 0.1);
        target.getWorld().spawnParticle(Particle.DUST, target.getLocation().add(0, 1.5, 0), 1, 0, 0, 0, 0,
            new Particle.DustOptions(org.bukkit.Color.RED, 1.5f));
        target.getWorld().spawnParticle(Particle.CRIT, target.getLocation().add(0, 1.1, 0), 2, 0.1, 0.1, 0.1, 0.05);
        // 顯示傷害數字（用自定義名稱閃現）
        String oldName = target.getCustomName();
        target.setCustomName("§c-" + (int)damage);
        target.setCustomNameVisible(true);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            target.setCustomName(oldName);
            if (oldName == null) target.setCustomNameVisible(false);
        }, 16L);
        // 更新寵物名稱血量（僅用 metadata 基礎名稱，不做 regex 剝除）
        if (damager instanceof LivingEntity beast) {
            Player owner = null;
            try {
                owner = Bukkit.getPlayer(UUID.fromString(beast.getMetadata("beast_owner").get(0).asString()));
            } catch (Exception ignored) {}
            if (owner != null) {
                String baseName = beast.hasMetadata("beast_base_name")
                        ? beast.getMetadata("beast_base_name").get(0).asString()
                        : beast.getType().name();
                setBeastNameWithHealth(beast, owner, baseName);
            }
        }
    }

    // ═══════════════════════════════════════
    //  工具方法
    // ═══════════════════════════════════════

    private void cleanupDeadBeasts() {
        for (Map.Entry<UUID, List<UUID>> entry : playerBeasts.entrySet()) {
            entry.getValue().removeIf(uuid -> {
                Entity e = Bukkit.getEntity(uuid);
                if (e == null || e.isDead()) {
                    beastOwners.remove(uuid);
                    return true;
                }
                // 定期重置蜜蜂狀態（守護蜂永遠不攻擊，攻擊蜂持續維持憤怒值）
                if (e instanceof org.bukkit.entity.Bee bee) {
                    if (e.hasMetadata("bee_companion")) {
                        // 守護蜂永遠清除目標與憤怒
                        bee.setTarget(null);
                        bee.setAnger(0);
                    } else {
                        // 攻擊蜂：若有存活目標則刷新憤怒計時，否則清除目標
                        LivingEntity currentTarget = bee.getTarget();
                        if (currentTarget != null && !currentTarget.isDead()) {
                            bee.setAnger(600); // 重置憤怒計時 30秒
                        } else {
                            bee.setTarget(null);
                            bee.setAnger(0);
                        }
                    }
                }
                return false;
            });
        }
    }

    private String getFormDisplayName(String formType) {
        return switch (formType.toLowerCase()) {
            case "wolf" -> "§7狂狼";
            case "polar_bear" -> "§f巨熊";
            case "fox" -> "§6靈狐";
            case "ravager" -> "§4狂暴獸";
            case "apex" -> "§c§l極致掠食者";
            default -> formType;
        };
    }

    // ═══════════════════════════════════════
    //  Lib's Disguises 整合
    // ═══════════════════════════════════════

    /** 是否已載入 Lib's Disguises */
    private boolean isLibsDisguisesLoaded() {
        return Bukkit.getPluginManager().getPlugin("LibsDisguises") != null;
    }

    /**
     * 將 formType 對應到 DisguiseType
     */
    private DisguiseType toDisguiseType(String formType) {
        return switch (formType.toLowerCase()) {
            case "wolf"       -> DisguiseType.WOLF;
            case "polar_bear" -> DisguiseType.POLAR_BEAR;
            case "fox"        -> DisguiseType.FOX;
            case "ravager"    -> DisguiseType.RAVAGER;
            case "apex"       -> DisguiseType.RAVAGER; // 極致掠食者用狂暴獸外觀
            default -> null;
        };
    }

    /**
     * 套用 Lib's Disguises 變裝給玩家
     */
    private void applyDisguise(Player player, String formType) {
        if (!isLibsDisguisesLoaded()) return;
        DisguiseType type = toDisguiseType(formType);
        if (type == null) return;
        try {
            MobDisguise disguise = new MobDisguise(type);
            disguise.setViewSelfDisguise(true);  // 玩家自己也能看見變身
            DisguiseAPI.disguiseToAll(player, disguise);
        } catch (Exception e) {
            plugin.getLogger().warning("[BeastManager] 套用 Lib's Disguises 失敗: " + e.getMessage());
        }
    }

    /**
     * 移除玩家的 Lib's Disguises 變裝
     */
    private void removeDisguise(Player player) {
        if (!isLibsDisguisesLoaded()) return;
        try {
            if (DisguiseAPI.isDisguised(player)) {
                DisguiseAPI.undisguiseToAll(player);
            }
        } catch (Exception e) {
            plugin.getLogger().warning("[BeastManager] 移除 Lib's Disguises 失敗: " + e.getMessage());
        }
    }

    public void shutdown() {
        // 清除所有召喚的野獸
        for (Map.Entry<UUID, List<UUID>> entry : playerBeasts.entrySet()) {
            for (UUID beastId : entry.getValue()) {
                Entity e = Bukkit.getEntity(beastId);
                if (e != null) e.remove();
            }
        }
        playerBeasts.clear();
        beastOwners.clear();
        activeForms.clear();
    }

    // 變身數據
    private static class BeastFormData {
        String formType;
        double originalMaxHealth;
        double healthBonus;
        double strengthBonus;
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import com.customrpg.players.PlayerStats;
import me.libraryaddict.disguise.DisguiseAPI;
import me.libraryaddict.disguise.disguisetypes.DisguiseType;
import me.libraryaddict.disguise.disguisetypes.MobDisguise;
import org.bukkit.*;
import org.bukkit.attribute.Attribute;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityTargetEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.metadata.FixedMetadataValue;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * BeastManager — 野獸系天賦管理器
 *
 * 負責：
 * 1. 馴服野獸（召喚寵物，擊殺歸屬玩家）
 * 2. 化身野獸（變身系統，屬性加成）
 */
public class BeastManager implements Listener {

    private final CustomRPG plugin;

    // 玩家召喚的野獸 Map<PlayerUUID, List<EntityUUID>>
    private final Map<UUID, List<UUID>> playerBeasts = new ConcurrentHashMap<>();
    // 野獸→主人映射 Map<EntityUUID, PlayerUUID>
    private final Map<UUID, UUID> beastOwners = new ConcurrentHashMap<>();

    // 玩家當前變身狀態 Map<PlayerUUID, BeastFormData>
    private final Map<UUID, BeastFormData> activeForms = new ConcurrentHashMap<>();

    // 每個玩家最多召喚幾隻野獸
    private static final int MAX_BEASTS_PER_PLAYER = 5;

    public BeastManager(CustomRPG plugin) {
        this.plugin = plugin;
        Bukkit.getPluginManager().registerEvents(this, plugin);

        // 定時清理死掉的野獸
        new BukkitRunnable() {
            @Override
            public void run() {
                cleanupDeadBeasts();
            }
        }.runTaskTimer(plugin, 100L, 100L);
    }

    // ═══════════════════════════════════════
    //  馴服野獸 — 召喚系統
    // ═══════════════════════════════════════

    /**
     * 召喚野獸
     * @param player 召喚者
     * @param entityType 野獸類型 (WOLF, POLAR_BEAR, etc.)
     * @param name 顯示名稱
     * @param health 生命值
     * @param damage 攻擊力
     * @param duration 持續時間(秒)，0=永久
     * @param count 召喚數量
     * @return 是否成功
     */
    public boolean summonBeast(Player player, EntityType entityType, String name,
                               double health, double damage, int duration, int count) {
        UUID pid = player.getUniqueId();
        List<UUID> existing = playerBeasts.getOrDefault(pid, new ArrayList<>());

        // 清理已死亡的
        existing.removeIf(uuid -> {
            Entity e = Bukkit.getEntity(uuid);
            return e == null || e.isDead();
        });

        if (existing.size() + count > MAX_BEASTS_PER_PLAYER) {
            player.sendMessage("§c你已經召喚了太多野獸！(上限 " + MAX_BEASTS_PER_PLAYER + " 隻)");
            return false;
        }

        Location spawnLoc = player.getLocation().add(
                player.getLocation().getDirection().setY(0).normalize().multiply(2));

        for (int i = 0; i < count; i++) {
            // 每隻稍微偏移位置
            Location loc = spawnLoc.clone().add(
                    (Math.random() - 0.5) * 3, 0, (Math.random() - 0.5) * 3);

            LivingEntity beast = (LivingEntity) player.getWorld().spawnEntity(loc, entityType);

            // 設定名稱
            setBeastNameWithHealth(beast, player, name);

            // 設定血量
            if (beast.getAttribute(Attribute.MAX_HEALTH) != null) {
                beast.getAttribute(Attribute.MAX_HEALTH).setBaseValue(health);
                beast.setHealth(health);
            }

            // 設定攻擊力
            if (beast.getAttribute(Attribute.ATTACK_DAMAGE) != null) {
                beast.getAttribute(Attribute.ATTACK_DAMAGE).setBaseValue(damage);
            }

            // 標記為玩家的野獸
            beast.setMetadata("beast_owner", new FixedMetadataValue(plugin, pid.toString()));
            beast.setMetadata("beast_damage", new FixedMetadataValue(plugin, damage));
            beast.setMetadata("beast_base_name", new FixedMetadataValue(plugin, name));

            // 如果是可馴服的動物（如狼），設定主人
            if (beast instanceof Tameable tameable) {
                tameable.setTamed(true);
                tameable.setOwner(player);
            }

            // 不會被其他機制清除
            beast.setRemoveWhenFarAway(false);
            beast.setPersistent(true);

            // 記錄
            existing.add(beast.getUniqueId());
            beastOwners.put(beast.getUniqueId(), pid);

            // 生成粒子
            beast.getWorld().spawnParticle(Particle.HEART, beast.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);
        }

        playerBeasts.put(pid, existing);

        // 定時消失
        if (duration > 0) {
            List<UUID> beastIds = new ArrayList<>(existing);
            new BukkitRunnable() {
                @Override
                public void run() {
                    for (UUID beastId : beastIds) {
                        Entity e = Bukkit.getEntity(beastId);
                        if (e != null && !e.isDead()) {
                            e.getWorld().spawnParticle(Particle.SMOKE, e.getLocation().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.02);
                            e.remove();
                        }
                        beastOwners.remove(beastId);
                    }
                    List<UUID> current = playerBeasts.get(pid);
                    if (current != null) {
                        current.removeAll(beastIds);
                    }
                }
            }.runTaskLater(plugin, duration * 20L);
        }

        return true;
    }

    /**
     * 移除玩家的所有野獸
     */
    public void removeAllBeasts(Player player) {
        UUID pid = player.getUniqueId();
        List<UUID> beasts = playerBeasts.remove(pid);
        if (beasts == null) return;
        for (UUID beastId : beasts) {
            Entity e = Bukkit.getEntity(beastId);
            if (e != null && !e.isDead()) {
                e.getWorld().spawnParticle(Particle.SMOKE, e.getLocation().add(0, 0.5, 0), 10, 0.3, 0.5, 0.3, 0.02);
                e.remove();
            }
            beastOwners.remove(beastId);
        }
    }

    /**
     * 獲取玩家當前召喚的野獸數量
     */
    public int getBeastCount(Player player) {
        List<UUID> beasts = playerBeasts.get(player.getUniqueId());
        if (beasts == null) return 0;
        beasts.removeIf(uuid -> {
            Entity e = Bukkit.getEntity(uuid);
            return e == null || e.isDead();
        });
        return beasts.size();
    }

    /**
     * 直接將已生成的野獸實體登錄給玩家（不受上限限制）
     * 用於有特殊邏輯的技能（如蜂巢誓盟）
     */
    public void registerExistingBeast(Player player, LivingEntity beast, double damage) {
        UUID pid = player.getUniqueId();
        beast.setMetadata("beast_owner", new FixedMetadataValue(plugin, pid.toString()));
        beast.setMetadata("beast_damage", new FixedMetadataValue(plugin, damage));
        // 記錄基礎名稱（去掉顏色前綴的純文字，用於健康名稱更新）
        String rawName = beast.getCustomName();
        if (rawName == null) rawName = beast.getType().name();
        beast.setMetadata("beast_base_name", new FixedMetadataValue(plugin, rawName));
        beast.setRemoveWhenFarAway(false);
        beast.setPersistent(true);

        List<UUID> existing = playerBeasts.computeIfAbsent(pid, k -> new ArrayList<>());
        existing.add(beast.getUniqueId());
        beastOwners.put(beast.getUniqueId(), pid);
    }

    // ═══════════════════════════════════════
    //  化身野獸 — 變身系統
    // ═══════════════════════════════════════

    /**
     * 啟動變身
     * @param player 玩家
     * @param formType 變身類型 (wolf, polar_bear, etc.)
     * @param duration 持續時間(秒)
     * @param strengthBonus 力量加成
     * @param healthBonus 生命值加成
     * @param speedLevel 速度等級
     * @param damageBoost 傷害提升等級
     */
    public boolean activateBeastForm(Player player, String formType, int duration,
                                     double strengthBonus, double healthBonus,
                                     int speedLevel, int damageBoost) {
        UUID pid = player.getUniqueId();

        // 如果已經變身，先取消
        if (activeForms.containsKey(pid)) {
            deactivateBeastForm(player);
        }

        BeastFormData data = new BeastFormData();
        data.formType = formType;
        data.originalMaxHealth = player.getAttribute(Attribute.MAX_HEALTH).getBaseValue();
        data.healthBonus = healthBonus;
        data.strengthBonus = strengthBonus;

        activeForms.put(pid, data);

        // 增加最大生命值
        if (healthBonus > 0) {
            double newMax = data.originalMaxHealth + healthBonus;
            player.getAttribute(Attribute.MAX_HEALTH).setBaseValue(newMax);
            player.setHealth(Math.min(player.getHealth() + healthBonus, newMax));
        }

        // 增加力量
        player.setMetadata("beast_form_strength", new FixedMetadataValue(plugin, strengthBonus));

        // 藥水效果
        if (speedLevel > 0) {
            player.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, duration * 20, speedLevel - 1, true, false));
        }
        if (damageBoost > 0) {
            player.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH, duration * 20, damageBoost - 1, true, false));
        }
        player.addPotionEffect(new PotionEffect(PotionEffectType.RESISTANCE, duration * 20, 0, true, false));

        // 變身視覺提示
        String formName = getFormDisplayName(formType);
        player.sendMessage("§6§l[野獸化身] §a你變身為 §e" + formName + " §a！持續 §f" + duration + " §a秒");
        player.getWorld().spawnParticle(Particle.TOTEM_OF_UNDYING, player.getLocation().add(0, 1, 0), 30, 0.5, 1, 0.5, 0.3);
        player.playSound(player.getLocation(), Sound.ENTITY_WOLF_AMBIENT, 1.5f, 0.8f);

        // Lib's Disguises 套裝外觀
        applyDisguise(player, formType);

        // ActionBar 提示
        new BukkitRunnable() {
            int remaining = duration;
            @Override
            public void run() {
                if (remaining <= 0 || !activeForms.containsKey(pid)) {
                    if (activeForms.containsKey(pid)) {
                        deactivateBeastForm(player);
                    }
                    cancel();
                    return;
                }
                player.sendActionBar("§6§l[" + formName + "] §e剩餘 " + remaining + " 秒 §7| §c力量+" + (int) strengthBonus + " §a生命+" + (int) healthBonus);
                remaining--;
            }
        }.runTaskTimer(plugin, 0L, 20L);

        return true;
    }

    /**
     * 取消變身
     */
    public void deactivateBeastForm(Player player) {
        UUID pid = player.getUniqueId();
        BeastFormData data = activeForms.remove(pid);
        if (data == null) return;

        // 恢復最大生命值
        player.getAttribute(Attribute.MAX_HEALTH).setBaseValue(data.originalMaxHealth);
        if (player.getHealth() > data.originalMaxHealth) {
            player.setHealth(data.originalMaxHealth);
        }

        player.removeMetadata("beast_form_strength", plugin);

        player.sendMessage("§6§l[野獸化身] §7變身效果已結束");
        player.playSound(player.getLocation(), Sound.ENTITY_WOLF_AMBIENT, 1.0f, 1.2f);
        player.getWorld().spawnParticle(Particle.SMOKE, player.getLocation().add(0, 1, 0), 20, 0.5, 1, 0.5, 0.05);
    }

    /**
     * 玩家是否在變身狀態
     */
    public boolean isInBeastForm(Player player) {
        return activeForms.containsKey(player.getUniqueId());
    }

    /**
     * 獲取變身的力量加成
     */
    public double getBeastFormStrengthBonus(Player player) {
        BeastFormData data = activeForms.get(player.getUniqueId());
        return data != null ? data.strengthBonus : 0;
    }

    // ═══════════════════════════════════════
    //  事件監聽
    // ═══════════════════════════════════════

    /**
     * 野獸擊殺怪物時，歸屬給主人（用於經驗值/掉落）
     * 使用 LOWEST 確保在 MobListener 處理死亡前先設置 metadata
     */
    @EventHandler(priority = EventPriority.LOWEST)
    public void onBeastKill(EntityDeathEvent event) {
        LivingEntity victim = event.getEntity();
        Entity killer = victim.getKiller();

        // 如果已經有玩家擊殺者，跳過
        if (killer instanceof Player) return;

        // 檢查最後傷害來源是否是玩家的野獸
        if (victim.getLastDamageCause() instanceof EntityDamageByEntityEvent dmgEvent) {
            Entity damager = dmgEvent.getDamager();
            if (damager.hasMetadata("beast_owner")) {
                String ownerStr = damager.getMetadata("beast_owner").get(0).asString();
                UUID ownerId = UUID.fromString(ownerStr);
                Player owner = Bukkit.getPlayer(ownerId);
                if (owner != null && owner.isOnline()) {
                    // 模擬玩家擊殺：設定經驗值掉落來源
                    // Bukkit 無法直接 setKiller，但可以透過傷害事件讓 MobListener 處理
                    victim.setMetadata("beast_kill_owner", new FixedMetadataValue(plugin, ownerId.toString()));
                }
            }
        }
    }

    /**
     * 讓野獸攻擊時附帶主人的部分屬性加成
     */
    @EventHandler(priority = EventPriority.NORMAL)
    public void onBeastAttack(EntityDamageByEntityEvent event) {
        Entity damager = event.getDamager();
        if (!damager.hasMetadata("beast_owner")) return;

        // 野獸的基礎傷害已在生成時設定
        // 這裡可以加入額外效果（如毒、緩速等）

        // 讓野獸的目標與玩家一致
        if (event.getEntity() instanceof Player) {
            // 野獸不應該攻擊玩家
            String ownerStr = damager.getMetadata("beast_owner").get(0).asString();
            UUID ownerId = UUID.fromString(ownerStr);
            if (event.getEntity().getUniqueId().equals(ownerId)) {
                event.setCancelled(true);
            }
        }
    }

    /**
     * 防止野獸攻擊自己的主人
     * 蜜蜂額外：玩家打到蜜蜂時重置生氣狀態
     */
    @EventHandler
    public void onBeastTarget(EntityTargetEvent event) {
        Entity entity = event.getEntity();
        Entity target = event.getTarget();
        if (entity.hasMetadata("beast_owner") && target instanceof Player player) {
            String ownerStr = entity.getMetadata("beast_owner").get(0).asString();
            if (player.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
                // 如果是蜜蜂，清除目標（EntityTargetEvent 會阻止後續攻擊）
                if (entity instanceof org.bukkit.entity.Bee bee) {
                    bee.setTarget(null);
                }
            }
        }
    }

    /**
     * 防止攻擊蜂 stinger 傷害主人；守護蜂永不攻擊任何人
     * （EntityDamageByEntityEvent 已在 onBeastAttack 中覆蓋，這裡補充蜜蜂場景）
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onBeeAttackOwner(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof org.bukkit.entity.Bee bee)) return;
        if (!bee.hasMetadata("beast_owner")) return;
        // 守護蜂絕對不攻擊任何人
        if (bee.hasMetadata("bee_companion")) {
            event.setCancelled(true);
            bee.setTarget(null);
            return;
        }
        // 攻擊蜂不攻擊主人
        if (event.getEntity() instanceof Player victim) {
            String ownerStr = bee.getMetadata("beast_owner").get(0).asString();
            if (victim.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
                bee.setTarget(null);
            }
        }
    }

    /**
     * 阻止召喚蜜蜂對主人產生生氣（使用 Paper 的 EntityTargetEvent 就足夠了，
     * 但若伺服器支援 EntityAngerEvent 也攔截）
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onBeeAnger(org.bukkit.event.entity.EntityTargetEvent event) {
        // EntityTargetEvent 已在 onBeastTarget 中處理，此為備援
        Entity entity = event.getEntity();
        Entity target = event.getTarget();
        if (!(entity instanceof org.bukkit.entity.Bee bee)) return;
        if (!bee.hasMetadata("beast_owner")) return;
        // 守護蜂永不攻擊任何人
        if (bee.hasMetadata("bee_companion")) {
            event.setCancelled(true);
            return;
        }
        // 攻擊蜂不攻擊主人
        if (target instanceof Player player) {
            String ownerStr = bee.getMetadata("beast_owner").get(0).asString();
            if (player.getUniqueId().toString().equals(ownerStr)) {
                event.setCancelled(true);
            }
        }
    }

    /**
     * 玩家離線時清除所有野獸和變身
     */
    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        removeAllBeasts(event.getPlayer());
        if (activeForms.containsKey(event.getPlayer().getUniqueId())) {
            deactivateBeastForm(event.getPlayer());
        }
    }

    /**
     * 玩家攻擊怪物時，讓其北極熊與攻擊蜂自動協助攻擊同一目標
     */
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onPlayerAttackMob(EntityDamageByEntityEvent event) {
        if (!(event.getDamager() instanceof Player player)) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;
        if (target instanceof Player) return; // 不協助攻擊玩家
        // 忽略攻擊到自己的野獸（避免讓野獸互打）
        if (target.hasMetadata("beast_owner")) return;

        UUID pid = player.getUniqueId();
        List<UUID> beasts = playerBeasts.get(pid);
        if (beasts == null) return;
        for (UUID beastId : beasts) {
            Entity e = Bukkit.getEntity(beastId);
            if (e == null || e.isDead()) continue;
            if (e instanceof PolarBear bear) {
                bear.setTarget(target);
            } else if (e instanceof org.bukkit.entity.Bee bee) {
                // 只有攻擊蜂跟隨目標（守護蜂不攻擊）
                if (!e.hasMetadata("bee_companion")) {
                    // 用 metadata 記錄目標 UUID，讓手動控制 loop 讀取
                    bee.setMetadata("bee_attack_target",
                            new FixedMetadataValue(plugin, target.getUniqueId().toString()));
                }
            }
        }
    }

    /**
     * 召喚時名稱加上血量
     */
    private void setBeastNameWithHealth(LivingEntity beast, Player player, String name) {
        int hp = (int) beast.getHealth();
        int maxHp = (int) beast.getAttribute(Attribute.MAX_HEALTH).getBaseValue();
        beast.setCustomName("§a[" + player.getName() + "的] §f" + name + " §c❤" + hp + "/" + maxHp);
        beast.setCustomNameVisible(true);
    }

    // 受傷時自動更新名稱
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBeastHurt(EntityDamageByEntityEvent event) {
        if (!(event.getEntity() instanceof LivingEntity beast)) return;
        if (!beast.hasMetadata("beast_owner")) return;
        Player owner = null;
        try {
            owner = Bukkit.getPlayer(UUID.fromString(beast.getMetadata("beast_owner").get(0).asString()));
        } catch (Exception ignored) {}
        if (owner == null) return;
        // 使用 metadata 記錄的基礎名稱，避免重複疊加玩家名前綴
        String baseName = beast.hasMetadata("beast_base_name")
                ? beast.getMetadata("beast_base_name").get(0).asString()
                : beast.getType().name();
        setBeastNameWithHealth(beast, owner, baseName);
    }

    // 寵物攻擊怪物時顯示傷害浮空字
    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onBeastDealDamage(EntityDamageByEntityEvent event) {
        Entity damager = event.getDamager();
        if (!damager.hasMetadata("beast_owner")) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;
        double damage = event.getFinalDamage();
        // 顯示浮空字
        target.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, target.getLocation().add(0, 1.2, 0), 8, 0.2, 0.2, 0.2, 0.1);
        target.getWorld().spawnParticle(Particle.DUST, target.getLocation().add(0, 1.5, 0), 1, 0, 0, 0, 0,
            new Particle.DustOptions(org.bukkit.Color.RED, 1.5f));
        target.getWorld().spawnParticle(Particle.CRIT, target.getLocation().add(0, 1.1, 0), 2, 0.1, 0.1, 0.1, 0.05);
        // 顯示傷害數字（用自定義名稱閃現）
        String oldName = target.getCustomName();
        target.setCustomName("§c-" + (int)damage);
        target.setCustomNameVisible(true);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            target.setCustomName(oldName);
            if (oldName == null) target.setCustomNameVisible(false);
        }, 16L);
        // 更新寵物名稱血量（僅用 metadata 基礎名稱，不做 regex 剝除）
        if (damager instanceof LivingEntity beast) {
            Player owner = null;
            try {
                owner = Bukkit.getPlayer(UUID.fromString(beast.getMetadata("beast_owner").get(0).asString()));
            } catch (Exception ignored) {}
            if (owner != null) {
                String baseName = beast.hasMetadata("beast_base_name")
                        ? beast.getMetadata("beast_base_name").get(0).asString()
                        : beast.getType().name();
                setBeastNameWithHealth(beast, owner, baseName);
            }
        }
    }

    // ═══════════════════════════════════════
    //  工具方法
    // ═══════════════════════════════════════

    private void cleanupDeadBeasts() {
        for (Map.Entry<UUID, List<UUID>> entry : playerBeasts.entrySet()) {
            entry.getValue().removeIf(uuid -> {
                Entity e = Bukkit.getEntity(uuid);
                if (e == null || e.isDead()) {
                    beastOwners.remove(uuid);
                    return true;
                }
                // 定期重置蜜蜂狀態（守護蜂永遠不攻擊，攻擊蜂持續維持憤怒值）
                if (e instanceof org.bukkit.entity.Bee bee) {
                    if (e.hasMetadata("bee_companion")) {
                        // 守護蜂永遠清除目標與憤怒
                        bee.setTarget(null);
                        bee.setAnger(0);
                    } else {
                        // 攻擊蜂：若有存活目標則刷新憤怒計時，否則清除目標
                        LivingEntity currentTarget = bee.getTarget();
                        if (currentTarget != null && !currentTarget.isDead()) {
                            bee.setAnger(600); // 重置憤怒計時 30秒
                        } else {
                            bee.setTarget(null);
                            bee.setAnger(0);
                        }
                    }
                }
                return false;
            });
        }
    }

    private String getFormDisplayName(String formType) {
        return switch (formType.toLowerCase()) {
            case "wolf" -> "§7狂狼";
            case "polar_bear" -> "§f巨熊";
            case "fox" -> "§6靈狐";
            case "ravager" -> "§4狂暴獸";
            case "apex" -> "§c§l極致掠食者";
            default -> formType;
        };
    }

    // ═══════════════════════════════════════
    //  Lib's Disguises 整合
    // ═══════════════════════════════════════

    /** 是否已載入 Lib's Disguises */
    private boolean isLibsDisguisesLoaded() {
        return Bukkit.getPluginManager().getPlugin("LibsDisguises") != null;
    }

    /**
     * 將 formType 對應到 DisguiseType
     */
    private DisguiseType toDisguiseType(String formType) {
        return switch (formType.toLowerCase()) {
            case "wolf"       -> DisguiseType.WOLF;
            case "polar_bear" -> DisguiseType.POLAR_BEAR;
            case "fox"        -> DisguiseType.FOX;
            case "ravager"    -> DisguiseType.RAVAGER;
            case "apex"       -> DisguiseType.RAVAGER; // 極致掠食者用狂暴獸外觀
            default -> null;
        };
    }

    /**
     * 套用 Lib's Disguises 變裝給玩家
     */
    private void applyDisguise(Player player, String formType) {
        if (!isLibsDisguisesLoaded()) return;
        DisguiseType type = toDisguiseType(formType);
        if (type == null) return;
        try {
            MobDisguise disguise = new MobDisguise(type);
            disguise.setViewSelfDisguise(true);  // 玩家自己也能看見變身
            DisguiseAPI.disguiseToAll(player, disguise);
        } catch (Exception e) {
            plugin.getLogger().warning("[BeastManager] 套用 Lib's Disguises 失敗: " + e.getMessage());
        }
    }

    /**
     * 移除玩家的 Lib's Disguises 變裝
     */
    private void removeDisguise(Player player) {
        if (!isLibsDisguisesLoaded()) return;
        try {
            if (DisguiseAPI.isDisguised(player)) {
                DisguiseAPI.undisguiseToAll(player);
            }
        } catch (Exception e) {
            plugin.getLogger().warning("[BeastManager] 移除 Lib's Disguises 失敗: " + e.getMessage());
        }
    }

    public void shutdown() {
        // 清除所有召喚的野獸
        for (Map.Entry<UUID, List<UUID>> entry : playerBeasts.entrySet()) {
            for (UUID beastId : entry.getValue()) {
                Entity e = Bukkit.getEntity(beastId);
                if (e != null) e.remove();
            }
        }
        playerBeasts.clear();
        beastOwners.clear();
        activeForms.clear();
    }

    // 變身數據
    private static class BeastFormData {
        String formType;
        double originalMaxHealth;
        double healthBonus;
        double strengthBonus;
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.ChatColor;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.Particle;
import org.bukkit.Registry;
import org.bukkit.Sound;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

public class DistanceSpawnManager {

    public enum MobTier {
        NORMAL("普通", ChatColor.WHITE),
        ELITE("精英", ChatColor.GOLD),
        BOSS("BOSS", ChatColor.RED);

        private final String displayName;
        private final ChatColor color;

        MobTier(String displayName, ChatColor color) {
            this.displayName = displayName;
            this.color = color;
        }

        public String getDisplayName() {
            return displayName;
        }

        public ChatColor getColor() {
            return color;
        }
    }

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final SafeZoneManager safeZoneManager;
    private final Logger log;
    private final Random random = new Random();
    private final Set<UUID> spawnedMobs = new HashSet<>();

    private BossZoneManager bossZoneManager;
    private BukkitTask spawnTask;

    private boolean enabled;
    private boolean active;
    private boolean debug;
    private int intervalTicks;
    private int spawnsPerCycle;
    private int spawnRadiusMin;
    private int spawnRadiusMax;
    private int maxMobsPerPlayer;
    private Set<String> disabledWorlds = new HashSet<>();

    private String originWorld;
    private double originX;
    private double originY;
    private double originZ;
    private int baseLevel;
    private double blocksPerLevel;

    private int normalLevelOffsetMin;
    private int normalLevelOffsetMax;
    private String normalNamePrefix;

    private double eliteChance;
    private int eliteLevelOffsetMin;
    private int eliteLevelOffsetMax;
    private double eliteStatMultiplier;
    private String eliteNamePrefix;

    private int bossLevelOffsetMin;
    private int bossLevelOffsetMax;
    private double bossStatMultiplier;
    private String bossNamePrefix;
    private String bossSpawnParticle;
    private int bossParticleCount;
    private String bossSpawnSound;
    private float bossSoundVolume;
    private float bossSoundPitch;

    private boolean nightOnly;
    private int maxLightLevel;
    private boolean requireSolidGround;
    private boolean requireAirSpace;

    private int totalSpawnAttempts;
    private int totalSpawnSuccess;
    private int totalLocationFails;
    private String lastSkipReason = "尚未執行 /finishrpg";

    public DistanceSpawnManager(CustomRPG plugin, MobManager mobManager, SafeZoneManager safeZoneManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.safeZoneManager = safeZoneManager;
        this.log = plugin.getLogger();
        loadConfig();
        startSpawnTask();
    }

    public void setBossZoneManager(BossZoneManager bossZoneManager) {
        this.bossZoneManager = bossZoneManager;
    }

    private void loadConfig() {
        File configFile = new File(plugin.getDataFolder(), "config/mob_spawner.yml");
        if (!configFile.exists()) {
            plugin.saveResource("config/mob_spawner.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        enabled = config.getBoolean("enabled", true);
        active = false;
        debug = config.getBoolean("debug", false);
        intervalTicks = config.getInt("interval-ticks", 60);
        spawnsPerCycle = config.getInt("spawns-per-cycle", 3);
        spawnRadiusMin = config.getInt("spawn-radius.min", 10);
        spawnRadiusMax = config.getInt("spawn-radius.max", 35);
        maxMobsPerPlayer = config.getInt("limits.max-mobs-per-player", 10);
        disabledWorlds = new HashSet<>(config.getStringList("disabled-worlds"));

        originWorld = config.getString("difficulty-scaling.origin.world", "world");
        originX = config.getDouble("difficulty-scaling.origin.x", 192.0);
        originY = config.getDouble("difficulty-scaling.origin.y", 73.0);
        originZ = config.getDouble("difficulty-scaling.origin.z", -70.0);
        baseLevel = Math.max(1, config.getInt("difficulty-scaling.base-level", 1));
        blocksPerLevel = Math.max(1.0, config.getDouble("difficulty-scaling.blocks-per-level", 80.0));

        normalLevelOffsetMin = config.getInt("tiers.normal.level-offset-min", 0);
        normalLevelOffsetMax = config.getInt("tiers.normal.level-offset-max", 1);
        normalNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.normal.name-prefix", ""));

        eliteChance = config.getDouble("tiers.elite.chance", 0.20);
        eliteLevelOffsetMin = config.getInt("tiers.elite.level-offset-min", 1);
        eliteLevelOffsetMax = config.getInt("tiers.elite.level-offset-max", 4);
        eliteStatMultiplier = config.getDouble("tiers.elite.stat-multiplier", 1.5);
        eliteNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.elite.name-prefix", "&6⚔ "));

        bossLevelOffsetMin = config.getInt("tiers.boss.level-offset-min", 3);
        bossLevelOffsetMax = config.getInt("tiers.boss.level-offset-max", 8);
        bossStatMultiplier = config.getDouble("tiers.boss.stat-multiplier", 3.0);
        bossNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.boss.name-prefix", "&c✦ BOSS ✦ "));
        bossSpawnParticle = config.getString("tiers.boss.spawn-particle", "FLAME");
        bossParticleCount = config.getInt("tiers.boss.spawn-particle-count", 100);
        bossSpawnSound = config.getString("tiers.boss.spawn-sound", "ENTITY_ENDER_DRAGON_GROWL");
        bossSoundVolume = (float) config.getDouble("tiers.boss.spawn-sound-volume", 2.0);
        bossSoundPitch = (float) config.getDouble("tiers.boss.spawn-sound-pitch", 0.5);

        nightOnly = config.getBoolean("conditions.night-only", false);
        maxLightLevel = config.getInt("conditions.max-light-level", 15);
        requireSolidGround = config.getBoolean("conditions.require-solid-ground", true);
        requireAirSpace = config.getBoolean("conditions.require-air-space", true);
    }

    private void startSpawnTask() {
        if (spawnTask != null) {
            spawnTask.cancel();
        }

        spawnTask = new BukkitRunnable() {
            @Override
            public void run() {
                if (!enabled || !active) {
                    return;
                }

                for (Player player : plugin.getServer().getOnlinePlayers()) {
                    processPlayer(player);
                }
            }
        }.runTaskTimer(plugin, 40L, intervalTicks);
    }

    public boolean activateSystem() {
        if (!enabled) {
            return false;
        }

        active = true;
        lastSkipReason = "系統已啟動";
        if (bossZoneManager != null) {
            bossZoneManager.setActive(true);
        }
        return true;
    }

    public void deactivateSystem() {
        active = false;
        if (bossZoneManager != null) {
            bossZoneManager.setActive(false);
        }
    }

    public boolean isActive() {
        return active;
    }

    public boolean isEnabled() {
        return enabled;
    }

    private void processPlayer(Player player) {
        if (player.getGameMode() == org.bukkit.GameMode.SPECTATOR || player.getGameMode() == org.bukkit.GameMode.CREATIVE) {
            lastSkipReason = "玩家模式不生成";
            return;
        }

        if (disabledWorlds.contains(player.getWorld().getName())) {
            lastSkipReason = "世界禁用: " + player.getWorld().getName();
            return;
        }

        if (safeZoneManager.isInSafeZone(player.getLocation())) {
            lastSkipReason = "玩家位於安全區";
            return;
        }

        if (nightOnly) {
            long time = player.getWorld().getTime();
            if (time < 13000 || time > 23000) {
                lastSkipReason = "白天不生成";
                return;
            }
        }

        ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
        if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea(player.getLocation())) {
            lastSkipReason = "玩家位於保護區域";
            return;
        }

        if (bossZoneManager != null) {
            bossZoneManager.trySpawnBossForPlayer(player);
        }

        int nearbyMobCount = countNearbyCustomMobs(player);
        if (nearbyMobCount >= maxMobsPerPlayer) {
            lastSkipReason = "附近自訂怪已達上限";
            return;
        }

        List<String> availableMobKeys = new ArrayList<>(mobManager.getNormalMobKeys());
        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
            availableMobKeys.removeIf(mobManager::willBeRemovedInPeaceful);
        }

        if (availableMobKeys.isEmpty()) {
            lastSkipReason = player.getWorld().getDifficulty() == Difficulty.PEACEFUL
                    ? "和平模式下沒有可生成的敵對自訂怪"
                    : "沒有可用的普通自訂怪";
            return;
        }

        int toSpawn = Math.min(spawnsPerCycle, maxMobsPerPlayer - nearbyMobCount);
        for (int i = 0; i < toSpawn; i++) {
            attemptSpawn(player, availableMobKeys);
        }
    }

    private boolean attemptSpawn(Player player, List<String> availableMobKeys) {
        totalSpawnAttempts++;

        Location spawnLoc = findSpawnLocation(player);
        if (spawnLoc == null) {
            totalLocationFails++;
            lastSkipReason = "找不到有效生成位置";
            return false;
        }

        if (bossZoneManager != null && bossZoneManager.isInsideBossZone(spawnLoc)) {
            lastSkipReason = "Boss 區域排他範圍內";
            return false;
        }

        MobTier tier = determineNaturalTier();
        int level = calculateLevelForLocation(spawnLoc, tier);
        String mobKey = selectMobTypeForLevel(filterBySpawnTime(availableMobKeys, spawnLoc.getWorld()), level);

        if (mobKey == null) {
            lastSkipReason = "沒有符合當前等級的怪物";
            return false;
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, level, tier);
        if (success) {
            totalSpawnSuccess++;
            lastSkipReason = "成功";
        }
        return success;
    }

    private List<String> filterBySpawnTime(List<String> mobKeys, World world) {
        long worldTime = world.getTime();
        boolean isNight = worldTime >= 13000 && worldTime < 23000;
        List<String> filtered = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            String spawnTime = data.getSpawnTime();
            if ("all".equalsIgnoreCase(spawnTime)
                    || ("night".equalsIgnoreCase(spawnTime) && isNight)
                    || ("day".equalsIgnoreCase(spawnTime) && !isNight)) {
                filtered.add(key);
            }
        }
        return filtered.isEmpty() ? mobKeys : filtered;
    }

    private MobTier determineNaturalTier() {
        return random.nextDouble() < eliteChance ? MobTier.ELITE : MobTier.NORMAL;
    }

    public int calculateBaseLevel(Location location) {
        double distance = calculateDistanceFromOrigin(location);
        return Math.max(1, baseLevel + (int) Math.floor(distance / blocksPerLevel));
    }

    public int calculateLevelForLocation(Location location, MobTier tier) {
        return Math.max(1, calculateBaseLevel(location) + calculateTierLevelOffset(tier));
    }

    public double calculateDistanceFromOrigin(Location location) {
        if (location == null || location.getWorld() == null) {
            return 0.0;
        }
        if (!location.getWorld().getName().equalsIgnoreCase(originWorld)) {
            return 0.0;
        }
        double dx = location.getX() - originX;
        double dy = location.getY() - originY;
        double dz = location.getZ() - originZ;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    private int calculateTierLevelOffset(MobTier tier) {
        return switch (tier) {
            case ELITE -> ThreadLocalRandom.current().nextInt(eliteLevelOffsetMin, eliteLevelOffsetMax + 1);
            case BOSS -> ThreadLocalRandom.current().nextInt(bossLevelOffsetMin, bossLevelOffsetMax + 1);
            default -> ThreadLocalRandom.current().nextInt(normalLevelOffsetMin, normalLevelOffsetMax + 1);
        };
    }

    private Location findSpawnLocation(Player player) {
        Location playerLoc = player.getLocation();
        World world = player.getWorld();

        for (int attempt = 0; attempt < 8; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = spawnRadiusMin + random.nextDouble() * Math.max(1.0, spawnRadiusMax - spawnRadiusMin);
            double x = playerLoc.getX() + Math.cos(angle) * distance;
            double z = playerLoc.getZ() + Math.sin(angle) * distance;

            int chunkX = ((int) Math.floor(x)) >> 4;
            int chunkZ = ((int) Math.floor(z)) >> 4;
            if (!world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }

            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location desired = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location candidate = mobManager.findSafeSpawnLocation(desired);
            if (candidate == null || !isValidSpawnLocation(candidate)) {
                continue;
            }

            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }

            ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
            if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea2D(candidate)) {
                continue;
            }

            if (bossZoneManager != null && bossZoneManager.isInsideBossZone(candidate)) {
                continue;
            }

            if (maxLightLevel < 15 && candidate.getBlock().getLightLevel() > maxLightLevel) {
                continue;
            }

            return candidate;
        }

        return null;
    }

    public Location findSpawnNear(Location center, int horizontalRadius) {
        if (center == null || center.getWorld() == null) {
            return null;
        }

        World world = center.getWorld();
        LinkedHashSet<Location> candidates = new LinkedHashSet<>();
        Location safeCenter = mobManager.findSafeSpawnLocation(center.clone());
        if (safeCenter != null) {
            candidates.add(safeCenter);
        }

        for (int attempt = 0; attempt < 10; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = random.nextDouble() * horizontalRadius;
            double x = center.getX() + Math.cos(angle) * distance;
            double z = center.getZ() + Math.sin(angle) * distance;
            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location test = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location safe = mobManager.findSafeSpawnLocation(test);
            if (safe != null) {
                candidates.add(safe);
            }
        }

        for (Location candidate : candidates) {
            if (!isValidSpawnLocation(candidate)) {
                continue;
            }
            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }
            return candidate;
        }
        return null;
    }

    private boolean isValidSpawnLocation(Location location) {
        Block feetBlock = location.getBlock();
        Block groundBlock = feetBlock.getRelative(BlockFace.DOWN);
        Block headBlock = feetBlock.getRelative(BlockFace.UP);

        if (requireSolidGround && !groundBlock.getType().isSolid()) {
            return false;
        }
        if (requireAirSpace && (!feetBlock.getType().isAir() || !headBlock.getType().isAir())) {
            return false;
        }
        if (groundBlock.isLiquid() || feetBlock.isLiquid()) {
            return false;
        }
        return true;
    }

    private String selectMobTypeForLevel(List<String> mobKeys, int level) {
        if (mobKeys == null || mobKeys.isEmpty()) {
            return null;
        }

        List<String> exactMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() && level <= data.getMaxLevel()) {
                exactMatches.add(key);
            }
        }
        if (!exactMatches.isEmpty()) {
            return exactMatches.get(random.nextInt(exactMatches.size()));
        }

        List<String> nearMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() - 5 && level <= data.getMaxLevel() + 5) {
                nearMatches.add(key);
            }
        }
        if (!nearMatches.isEmpty()) {
            return nearMatches.get(random.nextInt(nearMatches.size()));
        }

        String closest = null;
        int closestDistance = Integer.MAX_VALUE;
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            int distance = Math.min(Math.abs(level - data.getMinLevel()), Math.abs(level - data.getMaxLevel()));
            if (distance < closestDistance) {
                closestDistance = distance;
                closest = key;
            }
        }
        return closest;
    }

    public boolean spawnTieredMob(String mobKey, Location location, int level, MobTier tier) {
        LivingEntity mob = mobManager.spawnCustomMobWithLevel(mobKey, location, level);
        if (mob == null) {
            return false;
        }

        mobManager.setMobTier(mob, tier.name());
        spawnedMobs.add(mob.getUniqueId());

        switch (tier) {
            case ELITE -> applyEliteModifiers(mob);
            case BOSS -> applyBossModifiers(mob, location, level);
            default -> {
                if (!normalNamePrefix.isEmpty() && mob.getCustomName() != null) {
                    mob.setCustomName(normalNamePrefix + mob.getCustomName());
                }
            }
        }
        return true;
    }

    private void applyEliteModifiers(LivingEntity mob) {
        double newMaxHealth = mob.getMaxHealth() * eliteStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(eliteNamePrefix + ChatColor.translateAlternateColorCodes('&', "&e[精英] ") + mob.getCustomName());
        }
        mob.setGlowing(true);
    }

    public void applyBossModifiers(LivingEntity mob, Location location, int level) {
        double newMaxHealth = mob.getMaxHealth() * bossStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(bossNamePrefix + mob.getCustomName());
        }
        mob.setGlowing(true);

        try {
            Particle particle = Particle.valueOf(bossSpawnParticle);
            location.getWorld().spawnParticle(particle, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        } catch (Exception ignored) {
            location.getWorld().spawnParticle(Particle.FLAME, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        }

        Sound sound = resolveConfiguredSound(bossSpawnSound);
        if (sound != null) {
            location.getWorld().playSound(location, sound, bossSoundVolume, bossSoundPitch);
        } else {
            location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
        }

        BossBarManager bossBarManager = plugin.getBossBarManager();
        if (bossBarManager != null) {
            bossBarManager.createBossBossBar(mob, level);
        }
    }

    private Sound resolveConfiguredSound(String configuredValue) {
        if (configuredValue == null || configuredValue.isBlank()) {
            return null;
        }

        String trimmed = configuredValue.trim();
        for (Sound sound : Sound.values()) {
            if (sound.name().equalsIgnoreCase(trimmed)) {
                return sound;
            }
        }

        String normalized = trimmed.toLowerCase();
        NamespacedKey key = normalized.contains(":")
                ? NamespacedKey.fromString(normalized)
                : NamespacedKey.minecraft(normalized);

        return key != null ? Registry.SOUNDS.get(key) : null;
    }

    public String forceSpawn(Player player, String mobKey, MobTier tier) {
        List<String> mobKeys = new ArrayList<>(mobManager.getMobKeys());
        if (mobKeys.isEmpty()) {
            return ChatColor.RED + "沒有已註冊的怪物類型！";
        }

        if (mobKey == null || mobKey.isBlank()) {
            mobKey = mobKeys.get(random.nextInt(mobKeys.size()));
        } else if (mobManager.getMobData(mobKey) == null) {
            return ChatColor.RED + "未知的怪物類型: " + mobKey;
        }

        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL && mobManager.willBeRemovedInPeaceful(mobKey)) {
            EntityType actualType = mobManager.getActualSpawnEntityType(mobKey);
            return ChatColor.RED + "此怪物在 Peaceful 世界中會被 Minecraft 立刻移除：" + mobKey
                    + ChatColor.GRAY + " (" + (actualType != null ? actualType.name() : "unknown") + ")";
        }

        Location desired = player.getLocation().clone().add(player.getLocation().getDirection().multiply(8));
        Location spawnLocation = mobManager.findSafeSpawnLocation(desired);
        if (spawnLocation == null) {
            return ChatColor.RED + "找不到安全生成位置，請前往空曠地區再試一次。";
        }

        int level = calculateLevelForLocation(spawnLocation, tier);
        boolean success = spawnTieredMob(mobKey, spawnLocation, level, tier);
        if (!success) {
            return ChatColor.RED + "生成失敗: " + mobKey;
        }

        return ChatColor.GREEN + "✓ 成功生成 " + tier.getColor() + "[" + tier.getDisplayName() + "] "
                + ChatColor.WHITE + mobKey + " Lv." + level
                + ChatColor.GRAY + " 距離中心 " + String.format("%.1f", calculateDistanceFromOrigin(spawnLocation));
    }

    private int countNearbyCustomMobs(Player player) {
        int count = 0;
        int searchRadius = Math.max(spawnRadiusMax, 64);
        NamespacedKey key = mobManager.getCustomMobNamespacedKey();
        for (Entity entity : player.getNearbyEntities(searchRadius, searchRadius, searchRadius)) {
            if (entity instanceof LivingEntity mob && mob.getPersistentDataContainer().has(key, PersistentDataType.STRING)) {
                count++;
            }
        }
        return count;
    }

    public List<String> getDebugStatus(Player player) {
        List<String> lines = new ArrayList<>();
        lines.add(ChatColor.GOLD + "========= DistanceSpawnManager 診斷 =========");
        lines.add(ChatColor.YELLOW + "配置啟用: " + (enabled ? ChatColor.GREEN + "是" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "RPG 已完成: " + (active ? ChatColor.GREEN + "是 (/finishrpg 已執行)" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "重生點中心: " + ChatColor.WHITE + originWorld + " (" + originX + ", " + originY + ", " + originZ + ")");
        lines.add(ChatColor.YELLOW + "等級公式: " + ChatColor.WHITE + "Lv = " + baseLevel + " + distance / " + String.format("%.1f", blocksPerLevel));
        lines.add(ChatColor.YELLOW + "安全區數量: " + ChatColor.WHITE + safeZoneManager.getZoneCount());
        lines.add(ChatColor.YELLOW + "Boss 區域數量: " + ChatColor.WHITE + (bossZoneManager != null ? bossZoneManager.getZoneCount() : 0));
        lines.add(ChatColor.YELLOW + "已註冊怪物: " + ChatColor.WHITE + mobManager.getMobKeys().size());
        lines.add(ChatColor.YELLOW + "最後狀態: " + ChatColor.WHITE + lastSkipReason);

        if (player != null) {
            lines.add("");
            lines.add(ChatColor.AQUA + "--- 你的位置 ---");
            lines.add(ChatColor.YELLOW + "世界: " + ChatColor.WHITE + player.getWorld().getName());
            lines.add(ChatColor.YELLOW + "難度: " + ChatColor.WHITE + player.getWorld().getDifficulty().name());
            lines.add(ChatColor.YELLOW + "距離中心: " + ChatColor.WHITE + String.format("%.2f", calculateDistanceFromOrigin(player.getLocation())));
            lines.add(ChatColor.YELLOW + "當前基礎怪物等級: " + ChatColor.WHITE + "Lv." + calculateLevelForLocation(player.getLocation(), MobTier.NORMAL));

            SafeZoneManager.SafeZone safeZone = safeZoneManager.getZoneAt(player.getLocation());
            if (safeZone != null) {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.GREEN + safeZone.getName() + ChatColor.GRAY + " (" + safeZone.getType() + ")");
            } else {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.RED + "不在安全區內");
            }

            if (bossZoneManager != null) {
                BossZoneManager.BossZone bossZone = bossZoneManager.getZoneAt(player.getLocation());
                if (bossZone != null) {
                    lines.add(ChatColor.YELLOW + "Boss 區域: " + ChatColor.LIGHT_PURPLE + bossZone.getName());
                    lines.add(ChatColor.YELLOW + "Boss: " + ChatColor.WHITE + bossZone.getBossMobKey());
                    lines.add(ChatColor.YELLOW + "綁定小怪: " + ChatColor.WHITE + String.join(", ", bossZone.getLinkedMinions()));
                }
            }
        }

        lines.add("");
        lines.add(ChatColor.AQUA + "--- 統計 ---");
        lines.add(ChatColor.YELLOW + "總嘗試: " + ChatColor.WHITE + totalSpawnAttempts);
        lines.add(ChatColor.YELLOW + "總成功: " + ChatColor.GREEN + totalSpawnSuccess);
        lines.add(ChatColor.YELLOW + "位置失敗: " + ChatColor.RED + totalLocationFails);
        lines.add(ChatColor.YELLOW + "追蹤中怪物: " + ChatColor.WHITE + getSpawnedMobCount());
        lines.add(ChatColor.GOLD + "===========================================");
        return lines;
    }

    public int clearAllSpawnedMobs() {
        int removed = 0;
        for (UUID uuid : new HashSet<>(spawnedMobs)) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
                removed++;
            }
        }
        spawnedMobs.clear();
        return removed;
    }

    public boolean toggleDebug() {
        debug = !debug;
        return debug;
    }

    public void reload() {
        boolean wasActive = active;
        loadConfig();
        active = wasActive && enabled;
        safeZoneManager.reload();
        if (bossZoneManager != null) {
            bossZoneManager.reload();
            bossZoneManager.setActive(active);
        }
        startSpawnTask();
    }

    public void shutdown() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        clearAllSpawnedMobs();
    }

    public int getSpawnedMobCount() {
        spawnedMobs.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
        return spawnedMobs.size();
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.ChatColor;
import org.bukkit.Difficulty;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.Particle;
import org.bukkit.Registry;
import org.bukkit.Sound;
import org.bukkit.World;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.scheduler.BukkitTask;

import java.io.File;
import java.util.ArrayList;
import java.util.HashSet;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ThreadLocalRandom;
import java.util.logging.Logger;

public class DistanceSpawnManager {

    public enum MobTier {
        NORMAL("普通", ChatColor.WHITE),
        ELITE("精英", ChatColor.GOLD),
        BOSS("BOSS", ChatColor.RED);

        private final String displayName;
        private final ChatColor color;

        MobTier(String displayName, ChatColor color) {
            this.displayName = displayName;
            this.color = color;
        }

        public String getDisplayName() {
            return displayName;
        }

        public ChatColor getColor() {
            return color;
        }
    }

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final SafeZoneManager safeZoneManager;
    private final Logger log;
    private final Random random = new Random();
    private final Set<UUID> spawnedMobs = new HashSet<>();

    private BossZoneManager bossZoneManager;
    private BukkitTask spawnTask;

    private boolean enabled;
    private boolean active;
    private boolean debug;
    private int intervalTicks;
    private int spawnsPerCycle;
    private int spawnRadiusMin;
    private int spawnRadiusMax;
    private int maxMobsPerPlayer;
    private Set<String> disabledWorlds = new HashSet<>();

    private String originWorld;
    private double originX;
    private double originY;
    private double originZ;
    private int baseLevel;
    private double blocksPerLevel;

    private int normalLevelOffsetMin;
    private int normalLevelOffsetMax;
    private String normalNamePrefix;

    private double eliteChance;
    private int eliteLevelOffsetMin;
    private int eliteLevelOffsetMax;
    private double eliteStatMultiplier;
    private String eliteNamePrefix;

    private int bossLevelOffsetMin;
    private int bossLevelOffsetMax;
    private double bossStatMultiplier;
    private String bossNamePrefix;
    private String bossSpawnParticle;
    private int bossParticleCount;
    private String bossSpawnSound;
    private float bossSoundVolume;
    private float bossSoundPitch;

    private boolean nightOnly;
    private int maxLightLevel;
    private boolean requireSolidGround;
    private boolean requireAirSpace;

    private int totalSpawnAttempts;
    private int totalSpawnSuccess;
    private int totalLocationFails;
    private String lastSkipReason = "尚未執行 /finishrpg";

    public DistanceSpawnManager(CustomRPG plugin, MobManager mobManager, SafeZoneManager safeZoneManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.safeZoneManager = safeZoneManager;
        this.log = plugin.getLogger();
        loadConfig();
        startSpawnTask();
    }

    public void setBossZoneManager(BossZoneManager bossZoneManager) {
        this.bossZoneManager = bossZoneManager;
    }

    private void loadConfig() {
        File configFile = new File(plugin.getDataFolder(), "config/mob_spawner.yml");
        if (!configFile.exists()) {
            plugin.saveResource("config/mob_spawner.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        enabled = config.getBoolean("enabled", true);
        active = false;
        debug = config.getBoolean("debug", false);
        intervalTicks = config.getInt("interval-ticks", 60);
        spawnsPerCycle = config.getInt("spawns-per-cycle", 3);
        spawnRadiusMin = config.getInt("spawn-radius.min", 10);
        spawnRadiusMax = config.getInt("spawn-radius.max", 35);
        maxMobsPerPlayer = config.getInt("limits.max-mobs-per-player", 10);
        disabledWorlds = new HashSet<>(config.getStringList("disabled-worlds"));

        originWorld = config.getString("difficulty-scaling.origin.world", "world");
        originX = config.getDouble("difficulty-scaling.origin.x", 192.0);
        originY = config.getDouble("difficulty-scaling.origin.y", 73.0);
        originZ = config.getDouble("difficulty-scaling.origin.z", -70.0);
        baseLevel = Math.max(1, config.getInt("difficulty-scaling.base-level", 1));
        blocksPerLevel = Math.max(1.0, config.getDouble("difficulty-scaling.blocks-per-level", 80.0));

        normalLevelOffsetMin = config.getInt("tiers.normal.level-offset-min", 0);
        normalLevelOffsetMax = config.getInt("tiers.normal.level-offset-max", 1);
        normalNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.normal.name-prefix", ""));

        eliteChance = config.getDouble("tiers.elite.chance", 0.20);
        eliteLevelOffsetMin = config.getInt("tiers.elite.level-offset-min", 1);
        eliteLevelOffsetMax = config.getInt("tiers.elite.level-offset-max", 4);
        eliteStatMultiplier = config.getDouble("tiers.elite.stat-multiplier", 1.5);
        eliteNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.elite.name-prefix", "&6⚔ "));

        bossLevelOffsetMin = config.getInt("tiers.boss.level-offset-min", 3);
        bossLevelOffsetMax = config.getInt("tiers.boss.level-offset-max", 8);
        bossStatMultiplier = config.getDouble("tiers.boss.stat-multiplier", 3.0);
        bossNamePrefix = ChatColor.translateAlternateColorCodes('&', config.getString("tiers.boss.name-prefix", "&c✦ BOSS ✦ "));
        bossSpawnParticle = config.getString("tiers.boss.spawn-particle", "FLAME");
        bossParticleCount = config.getInt("tiers.boss.spawn-particle-count", 100);
        bossSpawnSound = config.getString("tiers.boss.spawn-sound", "ENTITY_ENDER_DRAGON_GROWL");
        bossSoundVolume = (float) config.getDouble("tiers.boss.spawn-sound-volume", 2.0);
        bossSoundPitch = (float) config.getDouble("tiers.boss.spawn-sound-pitch", 0.5);

        nightOnly = config.getBoolean("conditions.night-only", false);
        maxLightLevel = config.getInt("conditions.max-light-level", 15);
        requireSolidGround = config.getBoolean("conditions.require-solid-ground", true);
        requireAirSpace = config.getBoolean("conditions.require-air-space", true);
    }

    private void startSpawnTask() {
        if (spawnTask != null) {
            spawnTask.cancel();
        }

        spawnTask = new BukkitRunnable() {
            @Override
            public void run() {
                if (!enabled || !active) {
                    return;
                }

                for (Player player : plugin.getServer().getOnlinePlayers()) {
                    processPlayer(player);
                }
            }
        }.runTaskTimer(plugin, 40L, intervalTicks);
    }

    public boolean activateSystem() {
        if (!enabled) {
            return false;
        }

        active = true;
        lastSkipReason = "系統已啟動";
        if (bossZoneManager != null) {
            bossZoneManager.setActive(true);
        }
        return true;
    }

    public void deactivateSystem() {
        active = false;
        if (bossZoneManager != null) {
            bossZoneManager.setActive(false);
        }
    }

    public boolean isActive() {
        return active;
    }

    public boolean isEnabled() {
        return enabled;
    }

    private void processPlayer(Player player) {
        if (player.getGameMode() == org.bukkit.GameMode.SPECTATOR || player.getGameMode() == org.bukkit.GameMode.CREATIVE) {
            lastSkipReason = "玩家模式不生成 (" + player.getName() + " 為 " + player.getGameMode().name() + " 模式)";
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        if (disabledWorlds.contains(player.getWorld().getName())) {
            lastSkipReason = "世界禁用: " + player.getWorld().getName();
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        SafeZoneManager.SafeZone playerZone = safeZoneManager.getZoneAt(player.getLocation());
        if (playerZone != null) {
            lastSkipReason = "玩家位於安全區 [" + playerZone.getName() + "]，需離開安全區才能觸發生成";
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        if (nightOnly) {
            long time = player.getWorld().getTime();
            if (time < 13000 || time > 23000) {
                lastSkipReason = "白天不生成";
                if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
                return;
            }
        }

        ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
        if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea(player.getLocation())) {
            lastSkipReason = "玩家位於保護區域";
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        if (bossZoneManager != null) {
            bossZoneManager.trySpawnBossForPlayer(player);
        }

        int nearbyMobCount = countNearbyCustomMobs(player);
        if (nearbyMobCount >= maxMobsPerPlayer) {
            lastSkipReason = "附近自訂怪已達上限 (" + nearbyMobCount + "/" + maxMobsPerPlayer + ")";
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        List<String> availableMobKeys = new ArrayList<>(mobManager.getNormalMobKeys());
        if (debug) log.info("[DistanceSpawn] " + player.getName() + " 可用普通怪種數: " + availableMobKeys.size());

        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL) {
            availableMobKeys.removeIf(mobManager::willBeRemovedInPeaceful);
        }

        if (availableMobKeys.isEmpty()) {
            lastSkipReason = player.getWorld().getDifficulty() == Difficulty.PEACEFUL
                    ? "和平模式下沒有可生成的敵對自訂怪"
                    : "沒有可用的普通自訂怪（請確認 config/mobs/types/ 下有怪物設定檔）";
            if (debug) log.info("[DistanceSpawn] 跳過 " + player.getName() + "：" + lastSkipReason);
            return;
        }

        int toSpawn = Math.min(spawnsPerCycle, maxMobsPerPlayer - nearbyMobCount);
        if (debug) log.info("[DistanceSpawn] 為 " + player.getName() + " 嘗試生成 " + toSpawn + " 隻怪物");
        for (int i = 0; i < toSpawn; i++) {
            attemptSpawn(player, availableMobKeys);
        }
    }

    private boolean attemptSpawn(Player player, List<String> availableMobKeys) {
        totalSpawnAttempts++;

        Location spawnLoc = findSpawnLocation(player);
        if (spawnLoc == null) {
            totalLocationFails++;
            lastSkipReason = "找不到有效生成位置";
            return false;
        }

        if (bossZoneManager != null && bossZoneManager.isInsideBossZone(spawnLoc)) {
            lastSkipReason = "Boss 區域排他範圍內";
            return false;
        }

        MobTier tier = determineNaturalTier();
        int level = calculateLevelForLocation(spawnLoc, tier);
        String mobKey = selectMobTypeForLevel(filterBySpawnTime(availableMobKeys, spawnLoc.getWorld()), level);

        if (mobKey == null) {
            lastSkipReason = "沒有符合當前等級的怪物";
            return false;
        }

        boolean success = spawnTieredMob(mobKey, spawnLoc, level, tier);
        if (success) {
            totalSpawnSuccess++;
            lastSkipReason = "成功";
        }
        return success;
    }

    private List<String> filterBySpawnTime(List<String> mobKeys, World world) {
        long worldTime = world.getTime();
        boolean isNight = worldTime >= 13000 && worldTime < 23000;
        List<String> filtered = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            String spawnTime = data.getSpawnTime();
            if ("all".equalsIgnoreCase(spawnTime)
                    || ("night".equalsIgnoreCase(spawnTime) && isNight)
                    || ("day".equalsIgnoreCase(spawnTime) && !isNight)) {
                filtered.add(key);
            }
        }
        return filtered.isEmpty() ? mobKeys : filtered;
    }

    private MobTier determineNaturalTier() {
        return random.nextDouble() < eliteChance ? MobTier.ELITE : MobTier.NORMAL;
    }

    public int calculateBaseLevel(Location location) {
        double distance = calculateDistanceFromOrigin(location);
        return Math.max(1, baseLevel + (int) Math.floor(distance / blocksPerLevel));
    }

    public int calculateLevelForLocation(Location location, MobTier tier) {
        return Math.max(1, calculateBaseLevel(location) + calculateTierLevelOffset(tier));
    }

    public double calculateDistanceFromOrigin(Location location) {
        if (location == null || location.getWorld() == null) {
            return 0.0;
        }
        if (!location.getWorld().getName().equalsIgnoreCase(originWorld)) {
            return 0.0;
        }
        double dx = location.getX() - originX;
        double dy = location.getY() - originY;
        double dz = location.getZ() - originZ;
        return Math.sqrt(dx * dx + dy * dy + dz * dz);
    }

    private int calculateTierLevelOffset(MobTier tier) {
        return switch (tier) {
            case ELITE -> ThreadLocalRandom.current().nextInt(eliteLevelOffsetMin, eliteLevelOffsetMax + 1);
            case BOSS -> ThreadLocalRandom.current().nextInt(bossLevelOffsetMin, bossLevelOffsetMax + 1);
            default -> ThreadLocalRandom.current().nextInt(normalLevelOffsetMin, normalLevelOffsetMax + 1);
        };
    }

    private Location findSpawnLocation(Player player) {
        Location playerLoc = player.getLocation();
        World world = player.getWorld();

        for (int attempt = 0; attempt < 8; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = spawnRadiusMin + random.nextDouble() * Math.max(1.0, spawnRadiusMax - spawnRadiusMin);
            double x = playerLoc.getX() + Math.cos(angle) * distance;
            double z = playerLoc.getZ() + Math.sin(angle) * distance;

            int chunkX = ((int) Math.floor(x)) >> 4;
            int chunkZ = ((int) Math.floor(z)) >> 4;
            if (!world.isChunkLoaded(chunkX, chunkZ)) {
                continue;
            }

            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location desired = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location candidate = mobManager.findSafeSpawnLocation(desired);
            if (candidate == null || !isValidSpawnLocation(candidate)) {
                continue;
            }

            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }

            ProtectionAreaManager protectionAreaManager = plugin.getProtectionAreaManager();
            if (protectionAreaManager != null && protectionAreaManager.isInProtectedArea2D(candidate)) {
                continue;
            }

            if (bossZoneManager != null && bossZoneManager.isInsideBossZone(candidate)) {
                continue;
            }

            if (maxLightLevel < 15 && candidate.getBlock().getLightLevel() > maxLightLevel) {
                continue;
            }

            return candidate;
        }

        return null;
    }

    public Location findSpawnNear(Location center, int horizontalRadius) {
        if (center == null || center.getWorld() == null) {
            return null;
        }

        World world = center.getWorld();
        LinkedHashSet<Location> candidates = new LinkedHashSet<>();
        Location safeCenter = mobManager.findSafeSpawnLocation(center.clone());
        if (safeCenter != null) {
            candidates.add(safeCenter);
        }

        for (int attempt = 0; attempt < 10; attempt++) {
            double angle = random.nextDouble() * Math.PI * 2;
            double distance = random.nextDouble() * horizontalRadius;
            double x = center.getX() + Math.cos(angle) * distance;
            double z = center.getZ() + Math.sin(angle) * distance;
            int highestY = world.getHighestBlockYAt((int) Math.floor(x), (int) Math.floor(z));
            Location test = new Location(world, Math.floor(x) + 0.5, highestY + 1, Math.floor(z) + 0.5);
            Location safe = mobManager.findSafeSpawnLocation(test);
            if (safe != null) {
                candidates.add(safe);
            }
        }

        for (Location candidate : candidates) {
            if (!isValidSpawnLocation(candidate)) {
                continue;
            }
            if (safeZoneManager.isInSafeZone(candidate)) {
                continue;
            }
            return candidate;
        }
        return null;
    }

    private boolean isValidSpawnLocation(Location location) {
        Block feetBlock = location.getBlock();
        Block groundBlock = feetBlock.getRelative(BlockFace.DOWN);
        Block headBlock = feetBlock.getRelative(BlockFace.UP);

        if (requireSolidGround && !groundBlock.getType().isSolid()) {
            return false;
        }
        if (requireAirSpace && (!feetBlock.getType().isAir() || !headBlock.getType().isAir())) {
            return false;
        }
        if (groundBlock.isLiquid() || feetBlock.isLiquid()) {
            return false;
        }
        return true;
    }

    private String selectMobTypeForLevel(List<String> mobKeys, int level) {
        if (mobKeys == null || mobKeys.isEmpty()) {
            return null;
        }

        List<String> exactMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() && level <= data.getMaxLevel()) {
                exactMatches.add(key);
            }
        }
        if (!exactMatches.isEmpty()) {
            return exactMatches.get(random.nextInt(exactMatches.size()));
        }

        List<String> nearMatches = new ArrayList<>();
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data != null && level >= data.getMinLevel() - 5 && level <= data.getMaxLevel() + 5) {
                nearMatches.add(key);
            }
        }
        if (!nearMatches.isEmpty()) {
            return nearMatches.get(random.nextInt(nearMatches.size()));
        }

        String closest = null;
        int closestDistance = Integer.MAX_VALUE;
        for (String key : mobKeys) {
            MobManager.MobData data = mobManager.getMobData(key);
            if (data == null) {
                continue;
            }
            int distance = Math.min(Math.abs(level - data.getMinLevel()), Math.abs(level - data.getMaxLevel()));
            if (distance < closestDistance) {
                closestDistance = distance;
                closest = key;
            }
        }
        return closest;
    }

    public boolean spawnTieredMob(String mobKey, Location location, int level, MobTier tier) {
        LivingEntity mob = mobManager.spawnCustomMobWithLevel(mobKey, location, level);
        if (mob == null) {
            return false;
        }

        mobManager.setMobTier(mob, tier.name());
        spawnedMobs.add(mob.getUniqueId());

        switch (tier) {
            case ELITE -> applyEliteModifiers(mob);
            case BOSS -> applyBossModifiers(mob, location, level);
            default -> {
                if (!normalNamePrefix.isEmpty() && mob.getCustomName() != null) {
                    mob.setCustomName(normalNamePrefix + mob.getCustomName());
                }
            }
        }
        return true;
    }

    private void applyEliteModifiers(LivingEntity mob) {
        double newMaxHealth = mob.getMaxHealth() * eliteStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(eliteNamePrefix + ChatColor.translateAlternateColorCodes('&', "&e[精英] ") + mob.getCustomName());
        }
        mob.setGlowing(true);
    }

    public void applyBossModifiers(LivingEntity mob, Location location, int level) {
        double newMaxHealth = mob.getMaxHealth() * bossStatMultiplier;
        mob.setMaxHealth(newMaxHealth);
        mob.setHealth(newMaxHealth);
        if (mob.getCustomName() != null) {
            mob.setCustomName(bossNamePrefix + mob.getCustomName());
        }
        mob.setGlowing(true);

        try {
            Particle particle = Particle.valueOf(bossSpawnParticle);
            location.getWorld().spawnParticle(particle, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        } catch (Exception ignored) {
            location.getWorld().spawnParticle(Particle.FLAME, location.clone().add(0, 1, 0), bossParticleCount, 1.5, 1.5, 1.5, 0.1);
        }

        Sound sound = resolveConfiguredSound(bossSpawnSound);
        if (sound != null) {
            location.getWorld().playSound(location, sound, bossSoundVolume, bossSoundPitch);
        } else {
            location.getWorld().playSound(location, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.5f);
        }

        BossBarManager bossBarManager = plugin.getBossBarManager();
        if (bossBarManager != null) {
            bossBarManager.createBossBossBar(mob, level);
        }
    }

    private Sound resolveConfiguredSound(String configuredValue) {
        if (configuredValue == null || configuredValue.isBlank()) {
            return null;
        }

        String trimmed = configuredValue.trim();
        for (Sound sound : Sound.values()) {
            if (sound.name().equalsIgnoreCase(trimmed)) {
                return sound;
            }
        }

        String normalized = trimmed.toLowerCase();
        NamespacedKey key = normalized.contains(":")
                ? NamespacedKey.fromString(normalized)
                : NamespacedKey.minecraft(normalized);

        return key != null ? Registry.SOUNDS.get(key) : null;
    }

    public String forceSpawn(Player player, String mobKey, MobTier tier) {
        List<String> mobKeys = new ArrayList<>(mobManager.getMobKeys());
        if (mobKeys.isEmpty()) {
            return ChatColor.RED + "沒有已註冊的怪物類型！";
        }

        if (mobKey == null || mobKey.isBlank()) {
            mobKey = mobKeys.get(random.nextInt(mobKeys.size()));
        } else if (mobManager.getMobData(mobKey) == null) {
            return ChatColor.RED + "未知的怪物類型: " + mobKey;
        }

        if (player.getWorld().getDifficulty() == Difficulty.PEACEFUL && mobManager.willBeRemovedInPeaceful(mobKey)) {
            EntityType actualType = mobManager.getActualSpawnEntityType(mobKey);
            return ChatColor.RED + "此怪物在 Peaceful 世界中會被 Minecraft 立刻移除：" + mobKey
                    + ChatColor.GRAY + " (" + (actualType != null ? actualType.name() : "unknown") + ")";
        }

        Location desired = player.getLocation().clone().add(player.getLocation().getDirection().multiply(8));
        Location spawnLocation = mobManager.findSafeSpawnLocation(desired);
        if (spawnLocation == null) {
            return ChatColor.RED + "找不到安全生成位置，請前往空曠地區再試一次。";
        }

        int level = calculateLevelForLocation(spawnLocation, tier);
        boolean success = spawnTieredMob(mobKey, spawnLocation, level, tier);
        if (!success) {
            return ChatColor.RED + "生成失敗: " + mobKey;
        }

        return ChatColor.GREEN + "✓ 成功生成 " + tier.getColor() + "[" + tier.getDisplayName() + "] "
                + ChatColor.WHITE + mobKey + " Lv." + level
                + ChatColor.GRAY + " 距離中心 " + String.format("%.1f", calculateDistanceFromOrigin(spawnLocation));
    }

    private int countNearbyCustomMobs(Player player) {
        int count = 0;
        int searchRadius = Math.max(spawnRadiusMax, 64);
        NamespacedKey key = mobManager.getCustomMobNamespacedKey();
        for (Entity entity : player.getNearbyEntities(searchRadius, searchRadius, searchRadius)) {
            if (entity instanceof LivingEntity mob && mob.getPersistentDataContainer().has(key, PersistentDataType.STRING)) {
                count++;
            }
        }
        return count;
    }

    public List<String> getDebugStatus(Player player) {
        List<String> lines = new ArrayList<>();
        lines.add(ChatColor.GOLD + "========= DistanceSpawnManager 診斷 =========");
        lines.add(ChatColor.YELLOW + "配置啟用: " + (enabled ? ChatColor.GREEN + "是" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "RPG 已完成: " + (active ? ChatColor.GREEN + "是 (/finishrpg 已執行)" : ChatColor.RED + "否"));
        lines.add(ChatColor.YELLOW + "重生點中心: " + ChatColor.WHITE + originWorld + " (" + originX + ", " + originY + ", " + originZ + ")");
        lines.add(ChatColor.YELLOW + "等級公式: " + ChatColor.WHITE + "Lv = " + baseLevel + " + distance / " + String.format("%.1f", blocksPerLevel));
        lines.add(ChatColor.YELLOW + "安全區數量: " + ChatColor.WHITE + safeZoneManager.getZoneCount());
        lines.add(ChatColor.YELLOW + "Boss 區域數量: " + ChatColor.WHITE + (bossZoneManager != null ? bossZoneManager.getZoneCount() : 0));
        lines.add(ChatColor.YELLOW + "已註冊怪物: " + ChatColor.WHITE + mobManager.getMobKeys().size());
        lines.add(ChatColor.YELLOW + "最後狀態: " + ChatColor.WHITE + lastSkipReason);

        if (player != null) {
            lines.add("");
            lines.add(ChatColor.AQUA + "--- 你的位置 ---");
            lines.add(ChatColor.YELLOW + "世界: " + ChatColor.WHITE + player.getWorld().getName());
            lines.add(ChatColor.YELLOW + "難度: " + ChatColor.WHITE + player.getWorld().getDifficulty().name());
            lines.add(ChatColor.YELLOW + "距離中心: " + ChatColor.WHITE + String.format("%.2f", calculateDistanceFromOrigin(player.getLocation())));
            lines.add(ChatColor.YELLOW + "當前基礎怪物等級: " + ChatColor.WHITE + "Lv." + calculateLevelForLocation(player.getLocation(), MobTier.NORMAL));

            SafeZoneManager.SafeZone safeZone = safeZoneManager.getZoneAt(player.getLocation());
            if (safeZone != null) {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.GREEN + safeZone.getName() + ChatColor.GRAY + " (" + safeZone.getType() + ")");
            } else {
                lines.add(ChatColor.YELLOW + "安全區: " + ChatColor.RED + "不在安全區內");
            }

            if (bossZoneManager != null) {
                BossZoneManager.BossZone bossZone = bossZoneManager.getZoneAt(player.getLocation());
                if (bossZone != null) {
                    lines.add(ChatColor.YELLOW + "Boss 區域: " + ChatColor.LIGHT_PURPLE + bossZone.getName());
                    lines.add(ChatColor.YELLOW + "Boss: " + ChatColor.WHITE + bossZone.getBossMobKey());
                    lines.add(ChatColor.YELLOW + "綁定小怪: " + ChatColor.WHITE + String.join(", ", bossZone.getLinkedMinions()));
                }
            }
        }

        lines.add("");
        lines.add(ChatColor.AQUA + "--- 統計 ---");
        lines.add(ChatColor.YELLOW + "總嘗試: " + ChatColor.WHITE + totalSpawnAttempts);
        lines.add(ChatColor.YELLOW + "總成功: " + ChatColor.GREEN + totalSpawnSuccess);
        lines.add(ChatColor.YELLOW + "位置失敗: " + ChatColor.RED + totalLocationFails);
        lines.add(ChatColor.YELLOW + "追蹤中怪物: " + ChatColor.WHITE + getSpawnedMobCount());
        lines.add(ChatColor.GOLD + "===========================================");
        return lines;
    }

    public int clearAllSpawnedMobs() {
        int removed = 0;
        for (UUID uuid : new HashSet<>(spawnedMobs)) {
            Entity entity = plugin.getServer().getEntity(uuid);
            if (entity != null && !entity.isDead()) {
                entity.remove();
                removed++;
            }
        }
        spawnedMobs.clear();
        return removed;
    }

    public boolean toggleDebug() {
        debug = !debug;
        return debug;
    }

    public void reload() {
        boolean wasActive = active;
        loadConfig();
        active = wasActive && enabled;
        safeZoneManager.reload();
        if (bossZoneManager != null) {
            bossZoneManager.reload();
            bossZoneManager.setActive(active);
        }
        startSpawnTask();
    }

    public void shutdown() {
        if (spawnTask != null) {
            spawnTask.cancel();
            spawnTask = null;
        }
        clearAllSpawnedMobs();
    }

    public int getSpawnedMobCount() {
        spawnedMobs.removeIf(uuid -> {
            Entity entity = plugin.getServer().getEntity(uuid);
            return entity == null || entity.isDead();
        });
        return spawnedMobs.size();
    }
}

