        org.bukkit.command.PluginCommand mobCommand = getCommand("custommob");
        if (mobCommand != null) {
            MobCommand mobCommandExecutor = new MobCommand(this, mobManager);
            mobCommand.setExecutor(mobCommandExecutor);
