package com.customrpg.integration;

import com.customrpg.managers.MobManager;
import org.bukkit.Bukkit;
import org.bukkit.Material;
import org.bukkit.NamespacedKey;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.inventory.InventoryClickEvent;
import org.bukkit.event.inventory.InventoryCloseEvent;
import org.bukkit.inventory.Inventory;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;

/**
 * BeautyQuestsHook — CustomRPG 與 BeautyQuests 的整合入口
 *
 * 負責：
 * 1. 在 BeautyQuests 載入後注冊 CustomRPGMobFactory
 * 2. 提供 GUI 選擇器供任務編輯器選擇怪物 key
 * 3. 提供 notifyMobDeath() 讓 MobListener 通知 BeautyQuests 擊殺進度
 */
public class BeautyQuestsHook implements Listener {

    /** GUI 標題（用於識別這個選擇器的 Inventory） */
    static final String GUI_TITLE = "§6§lCustomRPG — 選擇目標怪物";

    /** 儲存在物品 PDC 中的怪物 key，供點擊時讀取 */
    static final NamespacedKey MOB_KEY_PDC = Objects.requireNonNull(
            NamespacedKey.fromString("customrpg:bq_mob_key"),
            "Failed to create mob key namespaced key"
    );

    /** 等待 GUI 選擇的 callback（admin UUID → callback） */
    private final Map<UUID, Consumer<String>> pendingGuiCallbacks = new ConcurrentHashMap<>();

    /** 追蹤已開啟的 GUI（用於 close 事件清理） */
    private final Map<UUID, Inventory> openGuiInventories = new ConcurrentHashMap<>();

    /** 記錄 GUI 最近一次開啟時間，用來辨識是否是 BeautyQuests 的切頁干擾 */
    private final Map<UUID, Long> selectorOpenedAt = new ConcurrentHashMap<>();

    /** 若 BeautyQuests 在剛開啟時把 GUI 搶回上一頁，最多自動重開幾次 */
    private final Map<UUID, Integer> selectorReopenAttempts = new ConcurrentHashMap<>();

    private final JavaPlugin plugin;
    private final MobManager mobManager;
    private CustomRPGMobFactory factory;
    private boolean enabled = false;

    public BeautyQuestsHook(JavaPlugin plugin, MobManager mobManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
    }

    /**
     * 嘗試連接 BeautyQuests。
     * 應在 onEnable() 後以 runTask 延遲一 tick 呼叫。
     */
    public void tryEnable() {
        if (Bukkit.getPluginManager().getPlugin("BeautyQuests") == null) {
            plugin.getLogger().info("[BeautyQuestsHook] BeautyQuests 未安裝，跳過整合。");
            return;
        }

        try {
            factory = new CustomRPGMobFactory(mobManager, this);
            registerMobFactoryWithBeautyQuests(factory);

            // 注冊 GUI 點擊/關閉 監聽器
            Bukkit.getPluginManager().registerEvents(this, plugin);

            enabled = true;
            plugin.getLogger().info("[BeautyQuestsHook] 已成功連接 BeautyQuests！已注冊 CustomRPG 怪物工廠。");
        } catch (Exception e) {
            plugin.getLogger().warning("[BeautyQuestsHook] 連接 BeautyQuests 失敗：" + e.getMessage());
        }
    }

    /**
     * 透過反射呼叫 BeautyQuests 的 QuestsAPI#getAPI().registerMobFactory(factory)，
     * 避免 IDE 偶發性無法解析 QuestsAPI 類別。
     */
    private void registerMobFactoryWithBeautyQuests(CustomRPGMobFactory mobFactory) throws Exception {
        Class<?> questsApiClass = Class.forName("fr.skytasul.quests.api.QuestsAPI");
        Object questsApi = questsApiClass.getMethod("getAPI").invoke(null);
        questsApiClass.getMethod("registerMobFactory", Class.forName("fr.skytasul.quests.api.mobs.MobFactory"))
                .invoke(questsApi, mobFactory);
    }

    // ─── 怪物選擇 GUI ─────────────────────────────────────────────

    /**
     * 開啟怪物選擇 GUI 給管理員。
     * 由 CustomRPGMobFactory.itemClick() 呼叫。
     */
    void openMobSelectionGUI(Player player, Consumer<String> callback) {
        List<MobManager.MobData> mobs = new ArrayList<>(mobManager.getMobTypes());

        // 計算所需列數（每列 9 格，上限 6 列 = 54 格）
        int rows = Math.max(1, Math.min(6, (int) Math.ceil(mobs.size() / 9.0)));
        int size = rows * 9;

        Inventory gui = Bukkit.createInventory(null, size, GUI_TITLE);

        for (int i = 0; i < mobs.size() && i < size; i++) {
            gui.setItem(i, buildMobItem(mobs.get(i)));
        }

        // 直接用 openInventory() 開啟選擇 GUI，不先呼叫 closeInventory()。
        // openInventory() 會讓 Minecraft 發送 InventoryCloseEvent 給 BQ，
        // 其 Reason = OPEN_NEW，BQ 現代版本看到此原因後知道是別的 GUI 接手，
        // 不會誤判成「管理員取消」而重新開啟自己的編輯器。
        // 等 1 tick 讓 BQ 的 InventoryClickEvent 處理完畢後再開啟。
        UUID playerId = player.getUniqueId();
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!player.isOnline()) {
                return;
            }

            pendingGuiCallbacks.put(playerId, callback);
            openGuiInventories.put(playerId, gui);
            selectorOpenedAt.put(playerId, System.currentTimeMillis());
            selectorReopenAttempts.put(playerId, 0);
            player.openInventory(gui);
        }, 1L);
    }

    /**
     * 為每隻怪物建立 GUI 物品，並將 mob key 存入 PDC。
     */
    private ItemStack buildMobItem(MobManager.MobData data) {
        // 嘗試用生怪蛋；找不到對應材質則用刷怪籠
        Material mat = getSpawnEggMaterial(data.getEntityType());

        ItemStack item = new ItemStack(mat);
        ItemMeta meta = item.getItemMeta();
        if (meta != null) {
            meta.setDisplayName("§f" + data.getName());
            List<String> lore = new ArrayList<>();
            lore.add("§7Key: §e" + data.getKey());
            lore.add("§7類型: §b" + data.getEntityType().name());
            lore.add("");
            lore.add("§a▶ 點擊選擇此怪物");
            meta.setLore(lore);
            // 將 mob key 儲存在 PDC，點擊時直接讀取
            meta.getPersistentDataContainer()
                    .set(MOB_KEY_PDC, PersistentDataType.STRING, data.getKey());
            item.setItemMeta(meta);
        }
        return item;
    }

    /**
     * 根據 EntityType 取得對應的生怪蛋材質。
     * Bukkit 材質命名規則：{ENTITY_TYPE}_SPAWN_EGG
     */
    private Material getSpawnEggMaterial(EntityType type) {
        if (type == null) return Material.SPAWNER;
        try {
            return Material.valueOf(type.name() + "_SPAWN_EGG");
        } catch (IllegalArgumentException e) {
            return Material.SPAWNER;
        }
    }

    // ─── GUI 事件監聽 ─────────────────────────────────────────────

    @EventHandler(priority = EventPriority.HIGH)
    public void onInventoryClick(InventoryClickEvent event) {
        if (!(event.getWhoClicked() instanceof Player player)) return;
        // 只處理我們的 GUI
        if (!GUI_TITLE.equals(event.getView().getTitle())) return;

        event.setCancelled(true);

        ItemStack clicked = event.getCurrentItem();
        if (clicked == null || clicked.getType() == Material.AIR || !clicked.hasItemMeta()) return;

        // 從 PDC 讀取 mob key
        String mobKey = clicked.getItemMeta().getPersistentDataContainer()
                .get(MOB_KEY_PDC, PersistentDataType.STRING);
        if (mobKey == null) return;

        // 先取出 callback 並從 Map 移除（close 事件不會重複清理）
        Consumer<String> callback = pendingGuiCallbacks.remove(player.getUniqueId());
        openGuiInventories.remove(player.getUniqueId());
        selectorOpenedAt.remove(player.getUniqueId());
        selectorReopenAttempts.remove(player.getUniqueId());
        if (callback == null) return;

        // 關閉 GUI，延遲 1 tick 後回傳結果（讓 BQ 在 GUI 完全關閉後處理）
        player.closeInventory();
        final String selectedKey = mobKey;
        final String displayName = clicked.getItemMeta().getDisplayName();
        Bukkit.getScheduler().runTask(plugin, () -> {
            callback.accept(selectedKey);
            player.sendMessage("§a§l[CustomRPG Quest] §r§a已選擇目標怪物：§f" + displayName
                    + " §7(" + selectedKey + ")");
        });
    }

    @EventHandler(priority = EventPriority.MONITOR)
    public void onInventoryClose(InventoryCloseEvent event) {
        if (!(event.getPlayer() instanceof Player player)) return;
        if (!GUI_TITLE.equals(event.getView().getTitle())) return;

        UUID playerId = player.getUniqueId();
        Consumer<String> leftover = pendingGuiCallbacks.get(playerId);
        if (leftover == null) {
            openGuiInventories.remove(playerId);
            selectorOpenedAt.remove(playerId);
            selectorReopenAttempts.remove(playerId);
            return;
        }

        long openedAt = selectorOpenedAt.getOrDefault(playerId, 0L);
        int reopenAttempts = selectorReopenAttempts.getOrDefault(playerId, 0);

        // BeautyQuests 有時會在我們剛開啟 GUI 後立刻把畫面切回上一頁。
        // 這種情況不是玩家取消，因此自動重開，不要直接清掉 callback。
        // 時間窗口 3 秒、最多 8 次，確保 BQ 重複搶回畫面的情況也能正確恢復。
        if (System.currentTimeMillis() - openedAt < 3000L && reopenAttempts < 8) {
            Inventory selectorGui = openGuiInventories.get(playerId);
            if (selectorGui != null) {
                selectorReopenAttempts.put(playerId, reopenAttempts + 1);
                Bukkit.getScheduler().runTaskLater(plugin, () -> {
                    if (!player.isOnline()) {
                        return;
                    }
                    if (!pendingGuiCallbacks.containsKey(playerId)) {
                        return;
                    }
                    selectorOpenedAt.put(playerId, System.currentTimeMillis());
                    player.openInventory(selectorGui);
                }, 3L);
                return;
            }
        }

        // 玩家未選擇直接關閉（按 Esc）→ 清理並提示
        pendingGuiCallbacks.remove(playerId);
        openGuiInventories.remove(playerId);
        selectorOpenedAt.remove(playerId);
        selectorReopenAttempts.remove(playerId);
        player.sendMessage("§c§l[CustomRPG Quest] §r§c已取消怪物選擇。");
    }

    // ─── BeautyQuests 擊殺通知 ────────────────────────────────────

    /**
     * 當自訂怪物死亡時，通知 BeautyQuests 更新任務進度。
     * 由 MobListener.onMobDeath() 呼叫。
     *
     * @param deathEvent 原始的 EntityDeathEvent
     * @param mobKey     CustomRPG 怪物 key（e.g. "boss_world_ender"）
     * @param entity     死亡實體
     * @param killer     擊殺玩家（可能為 null）
     */
    public void notifyMobDeath(EntityDeathEvent deathEvent, String mobKey,
                                Entity entity, Player killer) {
        if (!enabled || factory == null || killer == null) return;
        try {
            factory.fireBeautyQuestsMobEvent(deathEvent, mobKey, entity, killer);
        } catch (Exception e) {
            plugin.getLogger().warning("[BeautyQuestsHook] callEvent 失敗：" + e.getMessage());
        }
    }

    public boolean isEnabled() {
        return enabled;
    }
}

package com.customrpg.integration;

import com.customrpg.managers.MobManager;
import fr.skytasul.quests.api.editors.TextEditor;
import fr.skytasul.quests.api.editors.parsers.AbstractParser;
import org.bukkit.Bukkit;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.plugin.java.JavaPlugin;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * BeautyQuestsHook — CustomRPG 與 BeautyQuests 的整合入口
 *
 * 負責：
 * 1. 在 BeautyQuests 載入後注冊 CustomRPGMobFactory
 * 2. 透過 BQ 原生 TextEditor API 提供聊天室輸入模式讓管理員輸入怪物 key
 * 3. 提供 notifyMobDeath() 讓 MobListener 通知 BeautyQuests 擊殺進度
 */
public class BeautyQuestsHook {

    private final JavaPlugin plugin;
    private final MobManager mobManager;
    private CustomRPGMobFactory factory;
    private boolean enabled = false;

    public BeautyQuestsHook(JavaPlugin plugin, MobManager mobManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
    }

    /**
     * 嘗試連接 BeautyQuests。
     * 應在 onEnable() 後以 runTask 延遲一 tick 呼叫。
     */
    public void tryEnable() {
        if (Bukkit.getPluginManager().getPlugin("BeautyQuests") == null) {
            plugin.getLogger().info("[BeautyQuestsHook] BeautyQuests 未安裝，跳過整合。");
            return;
        }

        try {
            factory = new CustomRPGMobFactory(mobManager, this);
            registerMobFactoryWithBeautyQuests(factory);

            enabled = true;
            plugin.getLogger().info("[BeautyQuestsHook] 已成功連接 BeautyQuests！已注冊 CustomRPG 怪物工廠。");
        } catch (Exception e) {
            plugin.getLogger().warning("[BeautyQuestsHook] 連接 BeautyQuests 失敗：" + e.getMessage());
        }
    }

    /**
     * 透過反射呼叫 BeautyQuests 的 QuestsAPI#getAPI().registerMobFactory(factory)，
     * 避免 IDE 偶發性無法解析 QuestsAPI 類別。
     */
    private void registerMobFactoryWithBeautyQuests(CustomRPGMobFactory mobFactory) throws Exception {
        Class<?> questsApiClass = Class.forName("fr.skytasul.quests.api.QuestsAPI");
        Object questsApi = questsApiClass.getMethod("getAPI").invoke(null);
        questsApiClass.getMethod("registerMobFactory", Class.forName("fr.skytasul.quests.api.mobs.MobFactory"))
                .invoke(questsApi, mobFactory);
    }

    // ─── BQ TextEditor 輸入模式 ──────────────────────────────────

    /**
     * 使用 BeautyQuests 原生 TextEditor API 進入怪物 key 輸入模式。
     * 由 CustomRPGMobFactory.itemClick() 呼叫。
     *
     * TextEditor 由 BQ 的 EditorManager 管理，可正確整合 BQ 的 GUI 生命週期，
     * 確保 callback 被呼叫時 ListGUI 的 objects 狀態仍然正確（不會觸發 IndexOutOfBoundsException）。
     */
    void openTextEditor(Player player, Consumer<String> callback) {
        List<MobManager.MobData> mobs = new ArrayList<>(mobManager.getMobTypes());

        // 顯示可用怪物列表
        player.sendMessage("§6§l╔══ CustomRPG 怪物選擇器 ══╗");
        player.sendMessage("§e§l 在聊天室輸入怪物 Key 來選擇目標怪物");
        player.sendMessage("§7 輸入 §ccancel §7取消");
        player.sendMessage("§6§l ──── 可用怪物 ────");
        if (mobs.isEmpty()) {
            player.sendMessage("§c  （目前沒有已注冊的自訂怪物）");
        } else {
            for (MobManager.MobData data : mobs) {
                player.sendMessage("§a  • §f" + data.getKey() + " §7— " + data.getName()
                        + " §8(" + data.getEntityType().name() + ")");
            }
        }
        player.sendMessage("§6§l╚═══════════════════╝");

        // AbstractParser：驗證輸入的 mob key 是否存在
        // 返回 null 代表無效（BQ 會繼續等待下一次輸入）
        // 返回非 null 代表有效（BQ 會呼叫 success consumer）
        AbstractParser<String> mobKeyParser = (p, input) -> {
            String trimmed = input.trim();
            MobManager.MobData data = mobManager.getMobData(trimmed);
            if (data == null) {
                p.sendMessage("§c§l[CustomRPG Quest] §r§c找不到怪物 Key：§f" + trimmed);
                p.sendMessage("§7請重新輸入正確的 Key，或輸入 §ccancel §7取消。");
                return null; // 無效→BQ 保持 editor 開啟繼續等待
            }
            return data.getKey();
        };

        // Success consumer：BQ EditorManager 在 stop() 後同步呼叫，不需額外延遲
        Consumer<String> consumer = selectedKey -> {
            callback.accept(selectedKey);
            String displayName = mobs.stream()
                    .filter(m -> m.getKey().equals(selectedKey))
                    .map(MobManager.MobData::getName)
                    .findFirst()
                    .orElse(selectedKey);
            player.sendMessage("§a§l[CustomRPG Quest] §r§a已選擇目標怪物：§f" + displayName
                    + " §7(" + selectedKey + ")");
        };

        // 使用 BQ 原生 TextEditor(player, cancelRunnable, successConsumer, parser)
        // BQ 的 EditorManager 會攔截這個玩家的下一則聊天訊息
        TextEditor<String> editor = new TextEditor<>(
                player,
                () -> player.sendMessage("§c§l[CustomRPG Quest] §r§c已取消怪物選擇。"),
                consumer,
                mobKeyParser
        );
        editor.start();
    }

    // ─── BeautyQuests 擊殺通知 ────────────────────────────────────

    /**
     * 當自訂怪物死亡時，通知 BeautyQuests 更新任務進度。
     * 由 MobListener.onMobDeath() 呼叫。
     *
     * @param deathEvent 原始的 EntityDeathEvent
     * @param mobKey     CustomRPG 怪物 key（e.g. "boss_world_ender"）
     * @param entity     死亡實體
     * @param killer     擊殺玩家（可能為 null）
     */
    public void notifyMobDeath(EntityDeathEvent deathEvent, String mobKey,
                                Entity entity, Player killer) {
        if (!enabled || factory == null || killer == null) return;
        try {
            factory.fireBeautyQuestsMobEvent(deathEvent, mobKey, entity, killer);
        } catch (Exception e) {
            plugin.getLogger().warning("[BeautyQuestsHook] callEvent 失敗：" + e.getMessage());
        }
    }

    public boolean isEnabled() {
        return enabled;
    }
}

package com.customrpg.integration;

import com.customrpg.managers.MobManager;
import fr.skytasul.quests.api.mobs.MobFactory;
import org.bukkit.event.Event;
import org.bukkit.ChatColor;
import org.bukkit.Material;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.Player;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataType;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;

/**
 * CustomRPGMobFactory — BeautyQuests 的自訂怪物工廠
 *
 * 讓 BeautyQuests 能辨認並追蹤 CustomRPG 的自訂怪物擊殺任務。
 * T = String 代表怪物 Key（e.g. "boss_world_ender"）
 */
public class CustomRPGMobFactory implements MobFactory<String> {

    static final String FACTORY_ID = "customrpg";

    private final MobManager mobManager;
    private final BeautyQuestsHook beautyQuestsHook;

    public CustomRPGMobFactory(MobManager mobManager, BeautyQuestsHook beautyQuestsHook) {
        this.mobManager = mobManager;
        this.beautyQuestsHook = beautyQuestsHook;
    }

    // ─── MobFactory 必要實作 ───────────────────────────────────────

    @Override
    public String getID() {
        return FACTORY_ID;
    }

    /** 在 BeautyQuests 任務編輯器中顯示的工廠選擇圖示 */
    @Override
    public ItemStack getFactoryItem() {
        ItemStack item = new ItemStack(Material.SPAWNER);
        ItemMeta meta = item.getItemMeta();
        if (meta != null) {
            meta.setDisplayName(ChatColor.GOLD + "§6CustomRPG 自訂怪物");
            List<String> lore = new ArrayList<>();
            lore.add("§7點擊後在聊天室輸入怪物 Key");
            lore.add("§7即可選擇 CustomRPG 自訂怪物");
            lore.add("");
            lore.add("§e可用怪物：");
            for (MobManager.MobData data : mobManager.getMobTypes()) {
                lore.add("§a• §f" + data.getKey() + " §7(" + data.getName() + ")");
            }
            meta.setLore(lore);
            item.setItemMeta(meta);
        }
        return item;
    }

    /**
     * 管理員在任務編輯器中點擊圖示時呼叫。
     * 使用 BQ 原生 TextEditor API 進行聊天室輸入，正確整合 BQ GUI 生命週期。
     */
    @Override
    public void itemClick(Player player, Consumer<String> callback) {
        beautyQuestsHook.openTextEditor(player, callback);
    }

    /** 從 YAML 反序列化：直接回傳 key 字串 */
    @Override
    public String fromValue(String value) {
        return value;
    }

    /** 序列化為 YAML：直接儲存 key 字串 */
    @Override
    public String getValue(String mobKey) {
        return mobKey;
    }

    /** 在 BeautyQuests 任務 UI 中顯示的怪物名稱 */
    @Override
    public String getName(String mobKey) {
        MobManager.MobData data = mobManager.getMobData(mobKey);
        return data != null ? data.getName() : mobKey;
    }

    /**
     * 回傳這個怪物設定預期的 EntityType（用於 BeautyQuests 地圖標記）。
     * 若怪物設定找不到，回傳 UNKNOWN。
     */
    @Override
    public EntityType getEntityType(String mobKey) {
        MobManager.MobData data = mobManager.getMobData(mobKey);
        if (data == null) return EntityType.UNKNOWN;
        return data.getEntityType(); // MobData 已儲存 EntityType enum
    }

    /**
     * 判斷一個 Bukkit 實體是否符合這個怪物設定。
     * 只需檢查實體的 PDC 中的 customrpg:custom_mob_type 是否等於 mobKey。
     */
    @Override
    public boolean bukkitMobApplies(String mobKey, Entity entity) {
        if (entity == null) return false;
        String key = entity.getPersistentDataContainer()
                .get(mobManager.getCustomMobNamespacedKey(), PersistentDataType.STRING);
        return mobKey.equals(key);
    }

    /**
     * 顯式包裝 BeautyQuests 的 MobFactory#callEvent，
     * 避免在其他類中直接呼叫 default method 時出現 IDE 解析問題。
     */
    public void fireBeautyQuestsMobEvent(Event sourceEvent, String mobKey, Entity entity, Player killer) {
        MobFactory.super.callEvent(sourceEvent, mobKey, entity, killer);
    }
}

package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.FocusManager;
import com.customrpg.managers.TalentManager;
import com.customrpg.players.PlayerTalents;
import com.customrpg.talents.Talent;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.metadata.FixedMetadataValue;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * BowTalentListener — 風獵者之道 弓箭天賦事件處理器
 *
 * 負責：
 * 1. 被動增益應用（靜止傷害、距離傷害、爆頭、連擊、標記）
 * 2. 專注/連擊積累
 * 3. 幻影步伐自動閃避
 * 4. 分裂箭命中效果
 * 5. 緩速箭命中效果
 * 6. 獵人本能周期掃描
 */
public class BowTalentListener implements Listener {

    private final CustomRPG plugin;
    private final FocusManager focusManager;
    private final TalentManager talentManager;

    /** 幻影步伐冷卻 Map<PlayerUUID, lastUsedMs> */
    private final Map<UUID, Long> phantomStepCooldowns = new ConcurrentHashMap<>();

    public BowTalentListener(CustomRPG plugin, FocusManager focusManager, TalentManager talentManager) {
        this.plugin = plugin;
        this.focusManager = focusManager;
        this.talentManager = talentManager;
        startPassiveTasks();
    }

    // ══════════════════════════════════════════════════════
    //  1. 箭矢命中事件 — 被動乘數應用
    // ══════════════════════════════════════════════════════

    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onArrowHitEntity(EntityDamageByEntityEvent event) {
        // 只處理「箭矢射手是玩家」的情況
        if (!(event.getDamager() instanceof AbstractArrow arrow)) return;
        if (!(arrow.getShooter() instanceof Player player)) return;
        if (!(event.getEntity() instanceof LivingEntity target)) return;

        // 視覺型箭矢不造成傷害
        if (arrow.hasMetadata("bow_skill_visual")) {
            event.setCancelled(true);
            return;
        }

        PlayerTalents pt = talentManager.getPlayerTalents(player);
        double dmg = event.getDamage();
        double mult = 1.0;

        // ─ 1. 靜止姿態（still_stance）─
        int stillLv = pt.getTalentLevel("still_stance");
        if (stillLv > 0 && focusManager.isStill(player)) {
            Talent t = talentManager.findTalent("still_stance");
            mult += t.getEffectDouble(stillLv, "stillDamageBonus", 0.10);
        }

        // ─ 2. 鷹眼（eagle_eye）：距離加成 ─
        int eagleLv = pt.getTalentLevel("eagle_eye");
        if (eagleLv > 0) {
            Talent t = talentManager.findTalent("eagle_eye");
            double perBlock = t.getEffectDouble(eagleLv, "damagePerBlock", 0.01);
            double maxBonus = t.getEffectDouble(eagleLv, "maxDistanceBonus", 0.30);
            double dist = arrow.getLocation().distance(player.getLocation());
            mult += Math.min(maxBonus, dist * perBlock);
        }

        // ─ 3. 致命瞄準（deadly_aim）：專注加成 ─
        int deadlyLv = pt.getTalentLevel("deadly_aim");
        if (deadlyLv > 0) {
            Talent t = talentManager.findTalent("deadly_aim");
            double perFocus = t.getEffectDouble(deadlyLv, "damagePerFocus", 0.04);
            mult += focusManager.getFocus(player) * perFocus;
        }

        // ─ 4. 連擊強化（combo_shot）+ 急速殺機（rapid_fire）─
        int comboShotLv = pt.getTalentLevel("combo_shot");
        if (comboShotLv > 0) {
            Talent t = talentManager.findTalent("combo_shot");
            double perCombo = t.getEffectDouble(comboShotLv, "damagePerCombo", 0.05);
            int combo = focusManager.getCombo(player);
            mult += combo * perCombo;

            // 急速殺機：連擊滿時觸發倍率
            int rapidLv = pt.getTalentLevel("rapid_fire");
            if (rapidLv > 0 && combo >= FocusManager.MAX_COMBO) {
                Talent rtl = talentManager.findTalent("rapid_fire");
                double bonus = rtl.getEffectDouble(rapidLv, "maxComboBonus", 1.5);
                mult *= bonus;
                focusManager.resetCombo(player); // 消耗連擊
                player.sendMessage("§c§l[急速殺機] §e連擊爆發！");
            }
        }

        // ─ 5. 追蹤標記（tracking_mark）：標記加成 ─
        if (focusManager.isMarked(player, target)) {
            int markLv = pt.getTalentLevel("tracking_mark");
            if (markLv > 0) {
                Talent t = talentManager.findTalent("tracking_mark");
                mult += t.getEffectDouble(markLv, "markedDamageBonus", 0.25);
            }
        }

        // ─ 套用乘數 ─
        if (mult != 1.0) {
            event.setDamage(dmg * mult);
        }

        // ─ 6. 爆頭精通（headshot_mastery）─
        int headshotLv = pt.getTalentLevel("headshot_mastery");
        if (headshotLv > 0) {
            double arrowY  = arrow.getLocation().getY();
            double eyeY    = target.getEyeLocation().getY();
            if (Math.abs(arrowY - eyeY) < 0.35) { // 命中頭部範圍
                Talent t = talentManager.findTalent("headshot_mastery");
                double hsMult = t.getEffectDouble(headshotLv, "headshotMultiplier", 1.5);
                int focusGain = (int) t.getEffectDouble(headshotLv, "focusOnHeadshot", 2);

                event.setDamage(event.getDamage() * hsMult);
                focusManager.addFocus(player, focusGain);

                player.sendMessage("§6[爆頭！] §e+" + focusGain + " 專注");
                target.getWorld().spawnParticle(Particle.CRIT,
                        target.getEyeLocation(), 12, 0.2, 0.2, 0.2, 0.3);
                player.playSound(player.getLocation(),
                        Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 0.8f, 1.8f);
            }
        }

        // ─ 7. 連擊計數（quick_draw）─
        int quickDrawLv = pt.getTalentLevel("quick_draw");
        if (quickDrawLv > 0) {
            focusManager.addCombo(player);
        }

        // ─ 8. 獵人鎮定：命中獲得 1 專注（靜止時才觸發）─
        int huntersCalmLv = pt.getTalentLevel("hunters_calm");
        if (huntersCalmLv > 0 && focusManager.isStill(player)) {
            focusManager.addFocus(player, 1);
        }
    }

    // ══════════════════════════════════════════════════════
    //  2. 箭矢命中方塊/實體 — 特殊技能箭效果
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        if (!(event.getEntity() instanceof AbstractArrow arrow)) return;
        if (!(arrow.getShooter() instanceof Player player)) return;

        // ── 分裂箭 ──
        if (arrow.hasMetadata("bow_split_arrow")) {
            Entity hitEntity = event.getHitEntity();
            if (hitEntity == null) return; // 只在命中實體時分裂

            int splitCount = (int) arrow.getMetadata("bow_split_count").get(0).asDouble();
            double splitDmg = arrow.getMetadata("bow_split_damage").get(0).asDouble();
            Location hitLoc = hitEntity.getLocation().clone();

            for (int i = 0; i < splitCount; i++) {
                double angle = (2 * Math.PI / splitCount) * i;
                Vector dir = new Vector(Math.cos(angle), 0.15, Math.sin(angle))
                        .normalize().multiply(2.2);
                Arrow splitArrow = player.getWorld().spawn(
                        hitLoc.clone().add(0, 0.6, 0), Arrow.class);
                splitArrow.setVelocity(dir);
                splitArrow.setShooter(player);
                splitArrow.setDamage(splitDmg);
                splitArrow.setPickupStatus(AbstractArrow.PickupStatus.DISALLOWED);
            }
            hitLoc.getWorld().spawnParticle(Particle.CRIT,
                    hitLoc.add(0, 1, 0), 18, 0.5, 0.5, 0.5, 0.2);
            player.playSound(hitLoc, Sound.ENTITY_ARROW_SHOOT, 0.8f, 1.3f);
            arrow.remove();
            return;
        }

        // ── 緩速箭 ──
        if (arrow.hasMetadata("bow_slow_arrow")) {
            Entity hitEntity = event.getHitEntity();
            if (!(hitEntity instanceof LivingEntity le)) return;

            int slowLv  = (int) arrow.getMetadata("bow_slow_level").get(0).asDouble();
            int slowDur = (int) arrow.getMetadata("bow_slow_duration").get(0).asDouble();
            le.addPotionEffect(new PotionEffect(
                    PotionEffectType.SLOWNESS, slowDur, slowLv - 1, false, true, true));

            le.getWorld().spawnParticle(Particle.SNOWFLAKE,
                    le.getLocation().add(0, 1, 0), 18, 0.3, 0.5, 0.3, 0);
            le.getWorld().playSound(le.getLocation(),
                    Sound.BLOCK_POWDER_SNOW_PLACE, 1.0f, 1.0f);
        }
    }

    // ══════════════════════════════════════════════════════
    //  3. 幻影步伐（phantom_step）— 受傷時自動閃避
    // ══════════════════════════════════════════════════════

    @EventHandler(priority = EventPriority.LOW)
    public void onPlayerDamaged(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof Player player)) return;
        if (event.isCancelled()) return;

        PlayerTalents pt = talentManager.getPlayerTalents(player);
        int psLv = pt.getTalentLevel("phantom_step");
        if (psLv < 1) return;

        UUID pid = player.getUniqueId();
        long now = System.currentTimeMillis();
        Long last = phantomStepCooldowns.get(pid);

        Talent talent = talentManager.findTalent("phantom_step");
        long cdMs = (long) (talent.getEffectDouble(psLv, "cooldownSecs", 20) * 1000);
        if (last != null && now - last < cdMs) return;

        phantomStepCooldowns.put(pid, now);

        double dashForce   = talent.getEffectDouble(psLv, "dashForce", 1.2);
        int    invisTicks  = (int) talent.getEffectDouble(psLv, "invisDurationTicks", 20);
        double dmgReduction= talent.getEffectDouble(psLv, "damageReduction", 0.30);

        // 向後衝刺 (multiply(-1) = 反向)
        Vector dash = player.getLocation().getDirection().clone()
                .multiply(-1).setY(0.4).normalize().multiply(dashForce);
        player.setVelocity(dash);

        // 減免傷害
        event.setDamage(event.getDamage() * (1 - dmgReduction));

        // 短暫隱身
        player.addPotionEffect(new PotionEffect(
                PotionEffectType.INVISIBILITY, invisTicks, 0, false, false, false));

        // 特效
        player.getWorld().spawnParticle(Particle.CLOUD,
                player.getLocation().add(0, 1, 0), 15, 0.3, 0.5, 0.3, 0.05);
        player.playSound(player.getLocation(),
                Sound.ENTITY_ENDERMAN_TELEPORT, 0.5f, 1.5f);
        player.sendActionBar("§b§l[幻影步伐] §7閃避！");
    }

    // ══════════════════════════════════════════════════════
    //  4. 標記目標死亡時清除標記
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onEntityDeath(EntityDeathEvent event) {
        // 如果死亡的實體被某個玩家標記，清除標記
        UUID deadId = event.getEntity().getUniqueId();
        for (Player p : Bukkit.getOnlinePlayers()) {
            if (focusManager.isMarked(p, event.getEntity())) {
                event.getEntity().setGlowing(false);
            }
        }
    }

    // ══════════════════════════════════════════════════════
    //  5. 玩家離線清理
    // ══════════════════════════════════════════════════════

    @EventHandler
    public void onPlayerQuit(PlayerQuitEvent event) {
        focusManager.cleanup(event.getPlayer());
        phantomStepCooldowns.remove(event.getPlayer().getUniqueId());
    }

    // ══════════════════════════════════════════════════════
    //  6. 被動週期任務
    // ══════════════════════════════════════════════════════

    private void startPassiveTasks() {
        // ─ 獵人鎮定：靜止時每秒積累專注 ─
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    if (!focusManager.isStill(p)) continue;
                    PlayerTalents pt = talentManager.getPlayerTalents(p);
                    int lv = pt.getTalentLevel("hunters_calm");
                    if (lv < 1) continue;
                    if (focusManager.getFocus(p) >= FocusManager.MAX_FOCUS) continue;
                    Talent t = talentManager.findTalent("hunters_calm");
                    int fps = (int) t.getEffectDouble(lv, "focusPerSecond", 1);
                    focusManager.addFocus(p, fps);
                }
            }
        }.runTaskTimer(plugin, 20L, 20L); // 每秒

        // ─ 獵人本能：每 3 秒掃描周圍敵人並使其發光 ─
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    PlayerTalents pt = talentManager.getPlayerTalents(p);
                    int lv = pt.getTalentLevel("hunters_instinct");
                    if (lv < 1) continue;
                    Talent t = talentManager.findTalent("hunters_instinct");
                    double radius     = t.getEffectDouble(lv, "detectRadius", 20);
                    int    glowTicks  = (int) t.getEffectDouble(lv, "glowDurationTicks", 80);

                    for (Entity e : p.getNearbyEntities(radius, radius / 2, radius)) {
                        if (!(e instanceof LivingEntity le)) continue;
                        if (e instanceof Player) continue;
                        le.setGlowing(true);
                        Bukkit.getScheduler().runTaskLater(plugin,
                                () -> le.setGlowing(false), glowTicks);
                    }
                }
            }
        }.runTaskTimer(plugin, 60L, 60L); // 每 3 秒
    }
}

package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.MobManager;
import com.customrpg.managers.PlayerStatsManager;
import com.customrpg.managers.WeaponManager;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityCombustEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityRegainHealthEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.entity.ProjectileLaunchEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.projectiles.ProjectileSource;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.UUID;

/**
 * MobListener - Handles custom mob behavior events
 *
 * This listener implements special behaviors for custom mobs such as
 * projectile attacks, death mechanics, and combat modifications.
 *
 * Handles:
 * - Snow Zombie: Throws snowballs periodically
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Splits into smaller slimes on death
 */
public class MobListener implements Listener {

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final WeaponManager weaponManager;
    private final Random random;

    // ══ 熔核巨獸 (boss_magma_core) 階段狀態追蹤 ══
    private final Map<UUID, MagmaCoreState> magmaCoreStates = new HashMap<>();

    private static class MagmaCoreState {
        int phase = 1;          // 1=初始, 2=75%分裂完, 3=50%分裂完, 4=25%分裂完
        boolean inSplitPhase = false;
        long splitMergeDeadline = 0L;
        final List<UUID> activeSplits = new ArrayList<>();
        long lastSlamMs    = 0L;   // 冷卻 14s (狂暴 8s)
        long lastEruptMs   = 0L;   // 冷卻 10s (狂暴 6s)
        long lastAbsorbMs  = 0L;   // 冷卻 25s
        long lastWaveMs    = 0L;   // 冷卻 15s (狂暴 8s)
        boolean berserkActive = false;
    }

    /**
     * Constructor for MobListener
     * @param plugin Main plugin instance
     * @param mobManager MobManager instance
     */
    public MobListener(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager, WeaponManager weaponManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.weaponManager = weaponManager;
        this.random = new Random();
        startCustomMobBehaviors();
    }

    /**
     * Start periodic behaviors for custom mobs
     */
    private void startCustomMobBehaviors() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (org.bukkit.World world : plugin.getServer().getWorlds()) {
                    for (Entity entity : world.getEntities()) {
                        String mobKey = mobManager.getCustomMobKey(entity);
                        if (mobKey == null) continue;

                        MobManager.MobData mobData = mobManager.getMobData(mobKey);
                        if (mobData == null) continue;

                        applyPeriodicBehavior(entity, mobData);
                    }
                }
            }
        }.runTaskTimer(plugin, 0L, 60L);
    }

    /**
     * Apply periodic behaviors to custom mobs
     * @param entity The mob entity
     * @param mobData The mob data
     */
    private void applyPeriodicBehavior(Entity entity, MobManager.MobData mobData) {
        if (!(entity instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) entity;
        String behavior = mobData.getSpecialBehavior().toLowerCase();

        switch (behavior) {
            case "snowball_thrower" -> {
                if (random.nextDouble() < 0.3) {
                    throwSnowball(mob);
                }
            }
            case "snowball_mage" -> {
                // 骷髏法師：丟出傷害性雪球
                if (random.nextDouble() < 0.4) {
                    throwDamagingSnowball(mob);
                }
            }
            case "shadow_teleport" -> {
                // 影襲蜘蛛：暗影粒子 + 短距離瞬移
                // 持續噴出粒子
                Location loc = mob.getLocation().add(0, 0.5, 0);
                mob.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, loc, 2, 0.3, 0.3, 0.3, 0);
                mob.getWorld().spawnParticle(Particle.SQUID_INK, loc, 1, 0.2, 0.2, 0.2, 0.01);

                // 15% 機率瞬移到附近玩家身邊
                if (random.nextDouble() < 0.15) {
                    shadowTeleport(mob);
                }
            }
            case "charge_attack" -> {
                // 狂暴野豬：直線衝撞
                if (random.nextDouble() < 0.2) {
                    chargeAttack(mob);
                }
            }
            case "flee" -> {
                // 逃跑型：看到玩家就跑
                fleeFromPlayer(mob);
            }
            case "stalker_stealth" -> {
                // 潛伏蜘蛛：靠近玩家時隱形
                stalkerStealth(mob);
            }
            case "plague_aura" -> {
                // 瘟疫散播者：周圍持續毒氣
                plagueAura(mob);
            }
            case "charge_beast" -> {
                // 衝鋒野獸：鎖定後直線衝刺
                if (random.nextDouble() < 0.2) {
                    chargeBeastAttack(mob);
                }
            }
            case "berserker_rage" -> {
                // 狂戰殭屍：低血量時發紅光粒子
                double hpPercent = MobManager.hasVirtualHP(mob)
                        ? MobManager.getVirtualCurrentHP(mob) / MobManager.getVirtualMaxHP(mob)
                        : mob.getHealth() / mob.getMaxHealth();
                if (hpPercent < 0.3) {
                    mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, mob.getLocation().add(0, 1, 0),
                            3, 0.3, 0.3, 0.3, 0.02);
                }
            }
            // ═══ 野外 Boss 行為 ═══
            case "boss_pumpkin_knight" -> {
                // 南瓜騎士：Boss 光環粒子
                mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 2.2, 0),
                        3, 0.2, 0.1, 0.2, 0.01);
            }
            case "boss_scissor_frenzy" -> {
                // 瘋狂剪刀手：快速揮砍粒子 + 加速
                mob.getWorld().spawnParticle(Particle.SWEEP_ATTACK, mob.getLocation().add(0, 1, 0),
                        1, 0.5, 0.3, 0.5, 0);
                if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
                    mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 80, 1, false, false));
                }
            }
            case "boss_zombie_beast" -> {
                // 豬屍獸：衝撞（10秒冷卻）+ Boss 粒子
                mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                        1, 0.3, 0.3, 0.3, 0);
                bossZombieBeastCharge(mob);
            }
            // ══ 熔核巨獸系列 ══
            case "boss_magma_core"   -> magmaCoreBehavior(mob);
            case "magma_core_medium" -> magmaMediumBehavior(mob);
            case "magma_core_small"  -> magmaSmallBehavior(mob);
        }
    }

    /**
     * Handle custom mob death events
     * @param event EntityDeathEvent
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onMobDeath(EntityDeathEvent event) {
        // 排除玩家死亡
        if (event.getEntity() instanceof Player) {
            return;
        }

        Player killer = event.getEntity().getKiller();
        if (killer == null) {
            // 支援野獸擊殺：如果 killer 為 null，檢查 beast_kill_owner metadata
            if (event.getEntity().hasMetadata("beast_kill_owner")) {
                try {
                    String ownerId = event.getEntity().getMetadata("beast_kill_owner").get(0).asString();
                    Player owner = Bukkit.getPlayer(UUID.fromString(ownerId));
                    if (owner != null && owner.isOnline()) {
                        killer = owner;
                    }
                } catch (Exception ignored) {}
            }
        }

        String mobKey = mobManager.getCustomMobKey(event.getEntity());

        // 如果是自製怪物
        if (mobKey != null) {
            MobManager.MobData mobData = mobManager.getMobData(mobKey);
            if (mobData == null) {
                return;
            }

            // 沒有擊殺者（例如跌落死亡），跳過獎勵
            if (killer == null) {
                return;
            }

            int mobLevel = mobManager.getMobLevel(event.getEntity());

            // Handle custom mob drops or effects
            // For example, splitting slimes
            if (mobData.getSpecialBehavior().equalsIgnoreCase("split_on_death")) {
                splitSlime(event.getEntity(), mobData);
            }

            // 黏液爆破者：延遲爆炸
            if (mobData.getSpecialBehavior().equalsIgnoreCase("delayed_explosion")) {
                delayedExplosion(event.getEntity().getLocation(), mobLevel);
            }

            // 熔核巨獸：Boss 死亡 → 清理狀態 + 公告
            if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_magma_core")) {
                MagmaCoreState bossState = magmaCoreStates.remove(event.getEntity().getUniqueId());
                if (bossState != null) {
                    for (UUID splitUuid : bossState.activeSplits) {
                        Entity e = plugin.getServer().getEntity(splitUuid);
                        if (e != null && !e.isDead()) e.remove();
                    }
                }
                Location dl = event.getEntity().getLocation();
                dl.getWorld().spawnParticle(Particle.EXPLOSION_EMITTER, dl.clone().add(0, 2, 0), 4, 2, 2, 2, 0);
                dl.getWorld().playSound(dl, Sound.ENTITY_ENDER_DRAGON_DEATH, 0.5f, 0.5f);
                for (Player p : dl.getWorld().getPlayers()) {
                    if (p.getLocation().distance(dl) <= 100) {
                        p.sendMessage(ChatColor.GOLD + "" + ChatColor.BOLD + "[熔核巨獸] " + ChatColor.YELLOW + "熔岩之核冷卻沉眠... 已被討伐！");
                        p.sendTitle(ChatColor.GOLD + "" + ChatColor.BOLD + "BOSS 擊敗！", ChatColor.WHITE + "✦ 熔核巨獸 ✦", 10, 80, 20);
                    }
                }
            }

            // 熔核分裂體：死亡 → 分裂成 2 隻小型碎體
            if (mobData.getSpecialBehavior().equalsIgnoreCase("magma_core_medium")) {
                spawnSmallSplits(event.getEntity(), 2);
            }

            // 清除預設掉落物（如果有自定義掉落物）
            if (!mobData.getVanillaDrops().isEmpty() || !mobData.getWeaponDrops().isEmpty() || !mobData.getEquipmentDrops().isEmpty()) {
                event.getDrops().clear();

                // 掉落原版物品
                for (MobManager.DropItem dropItem : mobData.getVanillaDrops()) {
                    if (random.nextDouble() < dropItem.getChance()) {
                        int amount = dropItem.getMinAmount();
                        if (dropItem.getMaxAmount() > dropItem.getMinAmount()) {
                            amount = random.nextInt(dropItem.getMaxAmount() - dropItem.getMinAmount() + 1) + dropItem.getMinAmount();
                        }
                        event.getDrops().add(new ItemStack(dropItem.getMaterial(), amount));
                    }
                }

                // 掉落自定義武器
                for (MobManager.WeaponDrop weaponDrop : mobData.getWeaponDrops()) {
                    if (random.nextDouble() < weaponDrop.getChance()) {
                        ItemStack weapon = weaponManager.createWeapon(weaponDrop.getWeaponKey());
                        if (weapon != null) {
                            event.getDrops().add(weapon);
                            killer.sendMessage(ChatColor.GOLD + "★ 獲得稀有武器: " + weapon.getItemMeta().getDisplayName());
                        }
                    }
                }

                // 掉落自定義裝備 (飾品 / 裝甲)
                for (MobManager.EquipmentDrop equipDrop : mobData.getEquipmentDrops()) {
                    if (random.nextDouble() < equipDrop.getChance()) {
                        ItemStack dropItem = null;
                        if ("armor".equalsIgnoreCase(equipDrop.getType())) {
                            // 裝甲掉落
                            com.customrpg.equipment.ArmorManager armorMgr = plugin.getArmorManager();
                            if (armorMgr != null) {
                                com.customrpg.equipment.ArmorData armor = armorMgr.createArmor(equipDrop.getEquipmentKey());
                                if (armor != null) {
                                    dropItem = armor.toItemStack();
                                }
                            }
                        } else {
                            // 飾品掉落
                            com.customrpg.equipment.EquipmentManager equipMgr = plugin.getEquipmentManager();
                            if (equipMgr != null) {
                                com.customrpg.equipment.EquipmentData equip = equipMgr.createEquipment(equipDrop.getEquipmentKey());
                                if (equip != null) {
                                    dropItem = equip.toItemStack();
                                }
                            }
                        }
                        if (dropItem != null) {
                            event.getDrops().add(dropItem);
                            String itemName = dropItem.hasItemMeta() && dropItem.getItemMeta().hasDisplayName()
                                    ? dropItem.getItemMeta().getDisplayName()
                                    : equipDrop.getEquipmentKey();
                            killer.sendMessage(ChatColor.LIGHT_PURPLE + "★ 獲得稀有裝備: " + itemName);
                        }
                    }
                }
            }

            // 給予經驗值（基於等級 + 階級倍率 + 等級差距調整）
            int baseExpReward = mobData.calculateExp(mobLevel);

            // 階級經驗倍率：普通 x1, 精英 x2.5, Boss x5
            String mobTier = mobManager.getMobTier(event.getEntity());
            double tierMultiplier = switch (mobTier) {
                case "ELITE" -> 2.5;
                case "BOSS" -> 5.0;
                default -> 1.0;
            };

            // 等級差距調整：怪物等級比玩家高 → 加成，比玩家低太多 → 減少
            com.customrpg.players.PlayerStats killerStats = statsManager.getStats(killer);
            int playerLevel = killerStats.getLevel();
            int levelDiff = mobLevel - playerLevel;
            double levelMultiplier;
            if (levelDiff >= 5) {
                levelMultiplier = 1.5;  // 怪物比玩家高 5 級以上 → +50%
            } else if (levelDiff >= 0) {
                levelMultiplier = 1.0 + (levelDiff * 0.05); // 每高 1 級 +5%
            } else if (levelDiff >= -5) {
                levelMultiplier = 1.0;  // 低 1~5 級 → 正常
            } else if (levelDiff >= -10) {
                levelMultiplier = 0.5;  // 低 6~10 級 → 50%
            } else {
                levelMultiplier = 0.1;  // 低 10 級以上 → 10%（防止刷低等怪）
            }

            int finalExp = Math.max(1, (int) (baseExpReward * tierMultiplier * levelMultiplier));
            if (finalExp > 0) {
                statsManager.addExp(killer, finalExp);

                // 根據階級顯示不同顏色的訊息
                String tierTag = switch (mobTier) {
                    case "ELITE" -> ChatColor.GOLD + "[精英] ";
                    case "BOSS" -> ChatColor.RED + "[BOSS] ";
                    default -> "";
                };

                killer.sendMessage(ChatColor.YELLOW + "擊敗 " + tierTag +
                    ChatColor.YELLOW + "[Lv." + mobLevel + "] " +
                    ChatColor.stripColor(mobData.getName()) + " 獲得 " +
                    ChatColor.GREEN + finalExp + ChatColor.YELLOW + " 經驗值" +
                    (tierMultiplier > 1.0 ? ChatColor.GOLD + " (x" + tierMultiplier + ")" : ""));
            }

            // 移除 BossBar
            com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
            if (bossBarMgr != null) {
                bossBarMgr.onMobDeath(event.getEntity().getUniqueId());
            }

            com.customrpg.managers.BossZoneManager bossZoneManager = plugin.getBossZoneManager();
            if (bossZoneManager != null) {
                bossZoneManager.handleEntityDeath(event.getEntity());
            }
        } else {
            // 普通原版怪物：依類型給予不同經驗值
            if (killer == null) return; // 無擊殺者（跌落、其他原因死亡）
            int vanillaExp = switch (event.getEntity().getType()) {
                case ENDER_DRAGON -> 500;
                case WITHER -> 300;
                case ELDER_GUARDIAN -> 80;
                case WARDEN -> 100;
                case RAVAGER -> 50;
                case EVOKER, VINDICATOR -> 20;
                case GHAST, BLAZE, GUARDIAN -> 15;
                case ENDERMAN, PIGLIN_BRUTE -> 10;
                case CREEPER, SKELETON, ZOMBIE, SPIDER -> 5;
                case SLIME, MAGMA_CUBE -> 3;
                default -> 2;
            };
            statsManager.addExp(killer, vanillaExp);
            killer.sendMessage(ChatColor.YELLOW + "獲得 " + vanillaExp + " 經驗值");
        }
    }

    /**
     * Handle custom mob damage events (level-scaled damage)
     * 處理玩家攻擊 BlockDisplay 偽裝系統的情況
     * @param event EntityDamageByEntityEvent
     */
    @EventHandler
    public void onMobAttack(EntityDamageByEntityEvent event) {
        // === 情況 1：玩家攻擊 BlockDisplay 或名稱標籤 ArmorStand ===
        // BlockDisplay 和 ArmorStand 不是 LivingEntity，需要找到對應的隱形核心
        if (event.getDamager() instanceof Player player) {
            Entity target = event.getEntity();

            // 檢查是否攻擊到 BlockDisplay
            if (target instanceof org.bukkit.entity.BlockDisplay) {
                event.setCancelled(true); // 取消對 BlockDisplay 的傷害

                // 從 BlockDisplay 的 PersistentData 獲取核心 UUID
                String coreUuidString = target.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_blockdisplay"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害（考慮玩家的武器）
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                // 這裡可以加入自定義武器傷害計算
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊 BlockDisplay，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }

            // 檢查是否攻擊到名稱標籤 ArmorStand
            if (target instanceof ArmorStand armorStand) {
                String coreUuidString = armorStand.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_nametag"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    event.setCancelled(true); // 取消對 ArmorStand 的傷害

                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊名稱標籤，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }
        }

        // === 情況 1.5：玩家攻擊自訂 Boss 怪物（特殊防禦機制）===
        if (event.getDamager() instanceof Player player && event.getEntity() instanceof LivingEntity target) {
            String targetMobKey = mobManager.getCustomMobKey(target);
            if (targetMobKey != null) {
                MobManager.MobData targetData = mobManager.getMobData(targetMobKey);
                if (targetData != null) {
                    // 南瓜騎士：35% 格擋 → 減傷60%
                    if (targetData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
                        if (random.nextDouble() < 0.35) {
                            event.setDamage(event.getDamage() * 0.4);
                            target.getWorld().spawnParticle(Particle.ENCHANTED_HIT, target.getLocation().add(0, 1, 0),
                                    10, 0.3, 0.3, 0.3, 0.05);
                            target.getWorld().playSound(target.getLocation(), Sound.ITEM_SHIELD_BLOCK, 1.0f, 1.0f);
                            player.sendMessage(ChatColor.YELLOW + " 南瓜騎士格擋了你的攻擊！");
                        }
                    }
                }

                // BossBar 顯示：玩家攻擊自訂怪物時顯示血量條
                com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
                if (bossBarMgr != null) {
                    // 延遲1tick更新，讓傷害先生效
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (!target.isDead()) {
                                bossBarMgr.onMobDamaged(target);
                            }
                        }
                    }.runTaskLater(plugin, 1L);
                }
            }
        }

        // === 情況 2：自定義生物攻擊玩家（等級化傷害）===
        // 檢查是否為自定義生物攻擊玩家
        if (!(event.getDamager() instanceof LivingEntity)) {
            return;
        }

        if (!(event.getEntity() instanceof Player)) {
            return;
        }

        LivingEntity attacker = (LivingEntity) event.getDamager();
        String mobKey = mobManager.getCustomMobKey(attacker);

        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        // 獲取生物等級並計算傷害
        int mobLevel = mobManager.getMobLevel(attacker);
        double scaledDamage = mobData.calculateDamage(mobLevel);

        // 狂戰殭屍：HP < 30% → +50% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("berserker_rage")) {
            double hpPercent = MobManager.hasVirtualHP(attacker)
                    ? MobManager.getVirtualCurrentHP(attacker) / MobManager.getVirtualMaxHP(attacker)
                    : attacker.getHealth() / attacker.getMaxHealth();
            if (hpPercent < 0.3) {
                scaledDamage *= 1.5;
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, attacker.getLocation().add(0, 1.5, 0),
                        8, 0.3, 0.3, 0.3, 0.05);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.4f, 1.5f);
            }
        }

        // 潛伏蜘蛛：隱形狀態下第一擊 +80% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("stalker_stealth")) {
            if (attacker.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
                scaledDamage *= 1.8;
                attacker.removePotionEffect(PotionEffectType.INVISIBILITY);
                attacker.getWorld().spawnParticle(Particle.CRIT, attacker.getLocation().add(0, 1, 0),
                        15, 0.3, 0.3, 0.3, 0.1);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_CRIT, 1.0f, 1.0f);
            }
        }

        // 設置等級化傷害（對於偽裝生物，確保傷害大於0）
        if (scaledDamage < 1.0) {
            scaledDamage = 1.0; // 最低傷害為 1
        }
        event.setDamage(scaledDamage);

        // 冰霜殭屍：攻擊附帶緩速
        if (mobData.getSpecialBehavior().equalsIgnoreCase("frost_attack")) {
            if (event.getEntity() instanceof Player victim) {
                victim.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 60, 1)); // 3秒 緩速II
                victim.getWorld().spawnParticle(Particle.SNOWFLAKE, victim.getLocation().add(0, 1, 0),
                        10, 0.3, 0.5, 0.3, 0.02);
                victim.getWorld().playSound(victim.getLocation(), Sound.BLOCK_GLASS_BREAK, 0.5f, 1.8f);
            }
        }

        // ═══ 南瓜騎士：30% 重擊（2倍傷害 + 擊退） ═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
            if (random.nextDouble() < 0.3) {
                scaledDamage *= 2.0;
                event.setDamage(scaledDamage);
                if (event.getEntity() instanceof Player victim) {
                    Vector knockback = attacker.getLocation().getDirection().normalize().multiply(1.0).setY(0.4);
                    victim.setVelocity(knockback);
                    attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.0f, 0.6f);
                    attacker.getWorld().spawnParticle(Particle.CRIT, victim.getLocation().add(0, 1, 0),
                            20, 0.3, 0.3, 0.3, 0.1);
                    victim.sendMessage(ChatColor.RED + "⚔ 南瓜騎士使出了重擊！");
                }
            }
        }

        // ═══ 瘋狂剪刀手：每次攻擊附帶流血（凋零 1 秒）+ 雙重攻擊（40% 機率連擊）═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_scissor_frenzy")) {
            if (event.getEntity() instanceof Player victim) {
                // 流血
                victim.addPotionEffect(new PotionEffect(PotionEffectType.WITHER, 20, 0, false, true)); // 1秒凋零
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, victim.getLocation().add(0, 1, 0),
                        5, 0.2, 0.3, 0.2, 0.02);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 1.0f, 1.5f);

                // 40% 連擊（延遲 5 tick 再打一下）
                if (random.nextDouble() < 0.4) {
                    final double comboDamage = scaledDamage * 0.6;
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (attacker.isDead() || victim.isDead()) return;
                            if (attacker.getLocation().distance(victim.getLocation()) > 4) return;
                            victim.damage(comboDamage, attacker);
                            attacker.getWorld().spawnParticle(Particle.SWEEP_ATTACK, victim.getLocation().add(0, 1, 0),
                                    3, 0.3, 0.3, 0.3, 0);
                            attacker.getWorld().playSound(victim.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 0.8f, 1.8f);
                        }
                    }.runTaskLater(plugin, 5L);
                }
            }
        }

        // Debug 訊息
        plugin.getLogger().info("Custom mob " + mobData.getName() + " (Lv." + mobLevel + ") attacked player with " + scaledDamage + " damage");
    }

    /**
     * Split a giant slime into smaller ones
     * @param entity The dying entity
     * @param mobData The mob data
     */
    private void splitSlime(LivingEntity entity, MobManager.MobData mobData) {
        Location location = entity.getLocation();

        for (int i = 0; i < 4; i++) {
            Slime smallSlime = (Slime) location.getWorld().spawnEntity(location, EntityType.SLIME);
            smallSlime.setSize(1);

            Vector velocity = new Vector(
                random.nextDouble() - 0.5,
                0.5,
                random.nextDouble() - 0.5
            ).normalize().multiply(0.5);
            smallSlime.setVelocity(velocity);
        }
    }

    /**
     * Handle projectile launch events for custom mobs
     * @param event ProjectileLaunchEvent
     */
    @EventHandler
    public void onProjectileLaunch(ProjectileLaunchEvent event) {
        ProjectileSource shooter = event.getEntity().getShooter();
        if (!(shooter instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) shooter;
        String mobKey = mobManager.getCustomMobKey(mob);
        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        if (mobData.getSpecialBehavior().equalsIgnoreCase("fire_arrows")) {
            if (event.getEntity() instanceof Arrow) {
                Arrow arrow = (Arrow) event.getEntity();
                arrow.setFireTicks(1000);
            }
        }

        // 爆裂骷髏：標記箭矢為爆炸箭
        if (mobData.getSpecialBehavior().equalsIgnoreCase("explosive_arrow")) {
            if (event.getEntity() instanceof Arrow arrow) {
                arrow.getPersistentDataContainer().set(
                        new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                        org.bukkit.persistence.PersistentDataType.BOOLEAN, true
                );
                // 火焰軌跡視覺提示
                arrow.setFireTicks(200);
            }
        }
    }

    /**
     * Throw a snowball from the mob
     * @param mob The mob entity
     */
    private void throwSnowball(LivingEntity mob) {
        Player nearestPlayer = getNearestPlayer(mob, 15.0);
        if (nearestPlayer == null) {
            return;
        }

        Location mobLocation = mob.getEyeLocation();
        Location playerLocation = nearestPlayer.getEyeLocation();

        Vector direction = playerLocation.toVector().subtract(mobLocation.toVector()).normalize();

        Snowball snowball = (Snowball) mob.getWorld().spawnEntity(mobLocation, EntityType.SNOWBALL);
        snowball.setVelocity(direction.multiply(1.5));
        snowball.setShooter(mob);
    }

    /**
     * Get the nearest player to a mob within range
     * @param mob The mob entity
     * @param range The search range
     * @return The nearest player or null
     */
    private Player getNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range;

        for (Entity entity : mob.getNearbyEntities(range, range, range)) {
            if (entity instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                double distance = mob.getLocation().distance(player.getLocation());
                if (distance < nearestDistance) {
                    nearest = player;
                    nearestDistance = distance;
                }
            }
        }

        return nearest;
    }

    // ═══════════════════════════════════════
    //  新增特殊行為
    // ═══════════════════════════════════════

    /**
     * 黏液爆破者：死亡2秒後小範圍爆炸
     */
    private void delayedExplosion(Location deathLocation, int mobLevel) {
        // 生成粒子警告
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 40) { // 2秒 = 40 ticks
                    // 爆炸！
                    deathLocation.getWorld().spawnParticle(Particle.EXPLOSION, deathLocation, 3, 0.5, 0.5, 0.5, 0);
                    deathLocation.getWorld().spawnParticle(Particle.HAPPY_VILLAGER, deathLocation, 30, 1.5, 1.0, 1.5, 0.1);
                    deathLocation.getWorld().playSound(deathLocation, Sound.ENTITY_GENERIC_EXPLODE, 1.0f, 1.5f);

                    // 對範圍內玩家造成傷害（半徑3格）
                    double damage = 5.0 + mobLevel * 1.5;
                    for (Entity entity : deathLocation.getWorld().getNearbyEntities(deathLocation, 3, 3, 3)) {
                        if (entity instanceof Player player) {
                            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                            player.damage(damage);
                            player.sendMessage(ChatColor.RED + " 你被黏液爆炸波及了！");
                        }
                    }
                    cancel();
                    return;
                }
                // 警告粒子 (越來越密集)
                int particleCount = 3 + (ticks / 10);
                deathLocation.getWorld().spawnParticle(Particle.FLAME, deathLocation.clone().add(0, 0.5, 0),
                        particleCount, 0.3, 0.3, 0.3, 0.02);
                if (ticks % 10 == 0) {
                    deathLocation.getWorld().playSound(deathLocation, Sound.BLOCK_NOTE_BLOCK_BASS, 0.8f, 0.5f + (ticks / 40f));
                }
                ticks += 5;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    /**
     * 影襲蜘蛛：短距離瞬移到玩家附近
     */
    private void shadowTeleport(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 12.0);
        if (target == null) return;

        Location playerLoc = target.getLocation();
        // 隨機在玩家周圍 2~4 格瞬移
        double angle = random.nextDouble() * Math.PI * 2;
        double dist = 2.0 + random.nextDouble() * 2.0;
        Location teleportLoc = playerLoc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);

        // 確保目標位置安全
        teleportLoc.setY(teleportLoc.getWorld().getHighestBlockYAt(teleportLoc) + 1);

        // 起點粒子效果
        Location fromLoc = mob.getLocation();
        fromLoc.getWorld().spawnParticle(Particle.SQUID_INK, fromLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        fromLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, fromLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        fromLoc.getWorld().playSound(fromLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.5f);

        // 瞬移
        mob.teleport(teleportLoc);

        // 終點粒子效果
        teleportLoc.getWorld().spawnParticle(Particle.SQUID_INK, teleportLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        teleportLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, teleportLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        teleportLoc.getWorld().playSound(teleportLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.8f);
    }

    /**
     * 狂暴野豬：直線衝撞
     */
    private void chargeAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 10.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 3.0 || distance > 10.0) return; // 太近或太遠不衝

        // 衝撞方向
        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 播放音效
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.5f, 1.5f);

        // 衝撞動畫 (粒子軌跡)
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 10 || mob.isDead()) {
                    cancel();
                    return;
                }
                mob.setVelocity(direction.clone().multiply(1.2).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        5, 0.2, 0.1, 0.2, 0.02);

                // 碰到玩家就擊退
                for (Entity nearby : mob.getNearbyEntities(1.5, 1.5, 1.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        Vector knockback = direction.clone().multiply(0.8).setY(0.4);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 1.0f, 0.8f);
                        cancel();
                        return;
                    }
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 逃跑型：遠離玩家
     */
    private void fleeFromPlayer(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 8.0);
        if (nearest == null) return;

        // 計算遠離方向
        Vector away = mob.getLocation().toVector()
                .subtract(nearest.getLocation().toVector()).normalize();
        away.setY(0).normalize().multiply(0.5);
        if (random.nextDouble() < 0.3) {
            away.setY(0.2); // 偶爾跳一下
        }
        mob.setVelocity(away);
    }

    /**
     * 骷髏法師：丟出傷害性雪球（標記為魔法雪球）
     */
    private void throwDamagingSnowball(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        Location mobLoc = mob.getEyeLocation();
        Vector direction = target.getEyeLocation().toVector()
                .subtract(mobLoc.toVector()).normalize();

        Snowball snowball = mob.getWorld().spawn(mobLoc, Snowball.class);
        snowball.setVelocity(direction.multiply(1.2));
        snowball.setShooter(mob);

        // 標記這顆雪球為魔法雪球
        snowball.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN, true
        );

        // 紫色粒子
        mob.getWorld().spawnParticle(Particle.WITCH, mobLoc, 5, 0.2, 0.2, 0.2, 0.05);
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_SNOWBALL_THROW, 1.0f, 0.6f);
    }

    /**
     * 處理雪球命中事件 — 骷髏法師的魔法雪球造成傷害
     */
    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        // === 爆裂骷髏：爆炸箭 ===
        if (event.getEntity() instanceof Arrow arrow) {
            boolean isExplosive = arrow.getPersistentDataContainer().has(
                    new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                    org.bukkit.persistence.PersistentDataType.BOOLEAN
            );
            if (isExplosive) {
                Location hitLoc = arrow.getLocation();
                // 小範圍爆炸 (不破壞方塊)
                hitLoc.getWorld().spawnParticle(Particle.EXPLOSION, hitLoc, 2, 0.3, 0.3, 0.3, 0);
                hitLoc.getWorld().spawnParticle(Particle.FLAME, hitLoc, 15, 0.5, 0.5, 0.5, 0.05);
                hitLoc.getWorld().playSound(hitLoc, Sound.ENTITY_GENERIC_EXPLODE, 0.7f, 1.5f);

                // 計算傷害
                double damage = 5.0;
                if (arrow.getShooter() instanceof LivingEntity shooter) {
                    String mobKey = mobManager.getCustomMobKey(shooter);
                    if (mobKey != null) {
                        MobManager.MobData data = mobManager.getMobData(mobKey);
                        int level = mobManager.getMobLevel(shooter);
                        if (data != null) {
                            damage = data.calculateDamage(level) * 0.4;
                        }
                    }
                }

                // 半徑2.5格範圍傷害
                for (Entity nearby : hitLoc.getWorld().getNearbyEntities(hitLoc, 2.5, 2.5, 2.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        player.damage(damage);
                    }
                }
                arrow.remove();
                return;
            }
        }

        // === 骷髏法師：魔法雪球 ===
        if (!(event.getEntity() instanceof Snowball snowball)) return;

        // 檢查是否為魔法雪球
        boolean isMagic = snowball.getPersistentDataContainer().has(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN
        );
        if (!isMagic) return;

        // 如果命中實體
        if (event.getHitEntity() instanceof Player player) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) return;

            // 計算傷害 (根據射擊者等級)
            double damage = 4.0;
            if (snowball.getShooter() instanceof LivingEntity shooter) {
                String mobKey = mobManager.getCustomMobKey(shooter);
                if (mobKey != null) {
                    MobManager.MobData mobData = mobManager.getMobData(mobKey);
                    int level = mobManager.getMobLevel(shooter);
                    if (mobData != null) {
                        damage = mobData.calculateDamage(level) * 0.6;
                    }
                }
            }

            player.damage(damage);
            player.getWorld().spawnParticle(Particle.WITCH, player.getLocation().add(0, 1, 0),
                    10, 0.3, 0.5, 0.3, 0.05);
            player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 0.8f, 1.2f);
        }
    }

    /**
     * 潛伏蜘蛛：靠近玩家後隱形（距離8格以內）
     */
    private void stalkerStealth(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 12.0);
        if (nearest == null) return;

        double distance = mob.getLocation().distance(nearest.getLocation());

        // 8格以內且尚未隱形 → 進入隱形
        if (distance <= 8.0 && distance > 2.0 && !mob.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.INVISIBILITY, 100, 0, false, false)); // 5秒隱形
            mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0), 10, 0.3, 0.3, 0.3, 0.02);
            mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_ILLUSIONER_MIRROR_MOVE, 0.5f, 1.5f);
        }
    }

    /**
     * 瘟疫散播者：周圍持續毒氣（半徑4格）
     */
    private void plagueAura(LivingEntity mob) {
        Location loc = mob.getLocation();

        // 毒氣粒子效果
        mob.getWorld().spawnParticle(Particle.ITEM_SLIME, loc.clone().add(0, 0.5, 0), 5, 1.5, 0.5, 1.5, 0.01);
        mob.getWorld().spawnParticle(Particle.ENTITY_EFFECT, loc.clone().add(0, 0.3, 0), 3, 1.0, 0.3, 1.0, 0);

        // 對4格內的玩家施加中毒
        for (Entity nearby : mob.getNearbyEntities(4, 4, 4)) {
            if (nearby instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                if (!player.hasPotionEffect(PotionEffectType.POISON)) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.POISON, 80, 0)); // 4秒中毒I
                }
            }
        }
    }

    /**
     * 衝鋒野獸：鎖定後直線衝刺 (更猛烈的衝撞)
     */
    private void chargeBeastAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 15.0) return;

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.0f, 0.8f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);

        new BukkitRunnable() {
            int warmup = 20; // 1秒蓄力
            int chargeTicks = 0;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.5, 0),
                            2, 0.2, 0.1, 0.2, 0.01);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 15) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.5).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        8, 0.3, 0.1, 0.3, 0.03);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        5, 0.3, 0.1, 0.3, 0.1, org.bukkit.Material.DIRT.createBlockData());

                // 碰撞檢測
                for (Entity nearby : mob.getNearbyEntities(1.8, 1.8, 1.8)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 + 擊飛
                        Vector knockback = direction.clone().multiply(1.2).setY(0.6);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT_SWEET_BERRY_BUSH, 1.0f, 0.5f);
                        player.getWorld().spawnParticle(Particle.CRIT, player.getLocation().add(0, 1, 0),
                                15, 0.3, 0.3, 0.3, 0.1);
                        cancel();
                        return;
                    }
                }
                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ═══════════════════════════════════════
    //  野外 Boss 專用行為
    // ═══════════════════════════════════════

    /**
     * 豬屍獸：衝撞攻擊（10秒冷卻）
     * 使用 PersistentDataContainer 儲存上次衝撞時間
     */
    private void bossZombieBeastCharge(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 18.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 18.0) return;

        // 檢查冷卻 (10秒 = 10000ms)
        org.bukkit.NamespacedKey cdKey = new org.bukkit.NamespacedKey(plugin, "beast_charge_cd");
        Long lastCharge = mob.getPersistentDataContainer().get(cdKey, org.bukkit.persistence.PersistentDataType.LONG);
        long now = System.currentTimeMillis();
        if (lastCharge != null && (now - lastCharge) < 10000) return;

        // 設定冷卻
        mob.getPersistentDataContainer().set(cdKey, org.bukkit.persistence.PersistentDataType.LONG, now);

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1.5秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.5f, 0.5f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 2, 0), 8, 0.4, 0.3, 0.4, 0);

        // 通知附近玩家
        for (Entity nearby : mob.getNearbyEntities(18, 18, 18)) {
            if (nearby instanceof Player p) {
                p.sendMessage(ChatColor.RED + "⚠ 豬屍獸正在蓄力衝撞！");
            }
        }

        new BukkitRunnable() {
            int warmup = 30; // 1.5秒蓄力
            int chargeTicks = 0;
            boolean hit = false;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段 — 身體泛紅
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0),
                            3, 0.3, 0.2, 0.3, 0.02);
                    mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                            2, 0.2, 0.2, 0.2, 0);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 20 || hit) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.8).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        10, 0.4, 0.1, 0.4, 0.04);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        8, 0.4, 0.1, 0.4, 0.1, org.bukkit.Material.NETHERRACK.createBlockData());

                // 碰撞檢測 — 範圍更大、傷害更高
                for (Entity nearby : mob.getNearbyEntities(2.0, 2.0, 2.0)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 = 怪物傷害 * 2.5
                        int level = mobManager.getMobLevel(mob);
                        String key = mobManager.getCustomMobKey(mob);
                        double chargeDmg = 10.0;
                        if (key != null) {
                            MobManager.MobData data = mobManager.getMobData(key);
                            if (data != null) chargeDmg = data.calculateDamage(level) * 2.5;
                        }
                        player.damage(chargeDmg, mob);

                        // 擊飛
                        Vector knockback = direction.clone().multiply(1.5).setY(0.7);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.5f, 0.5f);
                        player.getWorld().spawnParticle(Particle.EXPLOSION, player.getLocation().add(0, 1, 0),
                                3, 0.3, 0.3, 0.3, 0);
                        player.sendMessage(ChatColor.RED + " 你被豬屍獸衝撞擊飛了！");
                        hit = true;
                        cancel();
                        return;
                    }
                }

                // 衝撞音效
                if (chargeTicks % 3 == 0) {
                    mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_STEP, 1.0f, 0.8f);
                }

                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ══════════════════════════════════════════════════════════
    //  虛擬 HP 系統：傷害 & 回血攔截
    // ══════════════════════════════════════════════════════════

    /**
     * 攔截對「虛擬 HP 怪物」的所有傷害事件
     * 將 MC 傷害按比例轉換為虛擬傷害，並同步 MC HP
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onVirtualHPDamage(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof LivingEntity mob)) return;
        if (!MobManager.hasVirtualHP(mob)) return;

        double finalDamage = event.getFinalDamage();
        if (finalDamage <= 0) return;

        double virtualMaxHp = MobManager.getVirtualMaxHP(mob);
        double currentVirtualHp = MobManager.getVirtualCurrentHP(mob);

        // 比例：1 MC 傷害 = ratio 虛擬傷害
        double ratio = virtualMaxHp / MobManager.getMcMaxHealthCap();
        double virtualDamage = finalDamage * ratio;
        double newVirtualHp = currentVirtualHp - virtualDamage;

        if (newVirtualHp <= 0) {
            // 怪物應死亡 — 儲存虛擬 HP = 0，讓事件通過以觸發死亡
            mob.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                    org.bukkit.persistence.PersistentDataType.DOUBLE, 0.0);
            return; // 不取消 → 讓 Minecraft 自然觸發死亡事件
        }

        // 取消事件，手動扣虛擬 HP 並同步 MC HP
        event.setCancelled(true);

        // 儲存新虛擬 HP
        mob.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                org.bukkit.persistence.PersistentDataType.DOUBLE, newVirtualHp);

        // 計算目標 MC HP
        double targetMcHp = (newVirtualHp / virtualMaxHp) * mob.getMaxHealth();
        targetMcHp = Math.max(0.1, Math.min(targetMcHp, mob.getMaxHealth()));
        final double finalMcHp = targetMcHp;

        // 下一 tick 設定 MC HP（不能在事件中直接 setHealth）
        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isValid() && !mob.isDead()) {
                    mob.setHealth(finalMcHp);
                }
            }
        }.runTask(plugin);

        // === 手動觸發受傷效果（因事件被取消，這些不會自動觸發） ===
        // 受傷音效
        Sound hurtSound = switch (mob.getType()) {
            case ZOMBIE, ZOMBIE_VILLAGER, HUSK, DROWNED, ZOMBIFIED_PIGLIN -> Sound.ENTITY_ZOMBIE_HURT;
            case SKELETON, STRAY, WITHER_SKELETON -> Sound.ENTITY_SKELETON_HURT;
            case SPIDER, CAVE_SPIDER -> Sound.ENTITY_SPIDER_HURT;
            case CREEPER -> Sound.ENTITY_CREEPER_HURT;
            case ENDERMAN -> Sound.ENTITY_ENDERMAN_HURT;
            case BLAZE -> Sound.ENTITY_BLAZE_HURT;
            case MAGMA_CUBE, SLIME -> Sound.ENTITY_SLIME_HURT;
            case GHAST -> Sound.ENTITY_GHAST_HURT;
            case IRON_GOLEM -> Sound.ENTITY_IRON_GOLEM_HURT;
            default -> Sound.ENTITY_GENERIC_HURT;
        };
        mob.getWorld().playSound(mob.getLocation(), hurtSound, 1.0f, 1.0f);

        // 受傷粒子
        Location hurtLoc = mob.getLocation().add(0, mob.getHeight() * 0.6, 0);
        mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, hurtLoc, 1, 0.2, 0.2, 0.2, 0.05);

        // 設定無敵幀（防止連續傷害）
        mob.setNoDamageTicks(10);
    }

    /**
     * 攔截對「虛擬 HP 怪物」的回血事件（如天然再生、藥水效果）
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onVirtualHPHeal(EntityRegainHealthEvent event) {
        if (!(event.getEntity() instanceof LivingEntity mob)) return;
        if (!MobManager.hasVirtualHP(mob)) return;

        double healAmount = event.getAmount();
        if (healAmount <= 0) return;

        double virtualMaxHp = MobManager.getVirtualMaxHP(mob);
        double currentVirtualHp = MobManager.getVirtualCurrentHP(mob);

        double ratio = virtualMaxHp / MobManager.getMcMaxHealthCap();
        double virtualHeal = healAmount * ratio;
        double newVirtualHp = Math.min(virtualMaxHp, currentVirtualHp + virtualHeal);

        event.setCancelled(true);

        mob.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                org.bukkit.persistence.PersistentDataType.DOUBLE, newVirtualHp);

        double newMcHp = (newVirtualHp / virtualMaxHp) * mob.getMaxHealth();
        final double finalMcHp = Math.min(newMcHp, mob.getMaxHealth());

        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isValid() && !mob.isDead()) {
                    mob.setHealth(finalMcHp);
                }
            }
        }.runTask(plugin);
    }

    /**
     * 防止自訂怪物被陽光燃燒
     * 殭屍、骷髏等不死生物在白天會著火，取消此行為
     */
    @EventHandler
    public void onCustomMobCombust(EntityCombustEvent event) {
        if (!(event.getEntity() instanceof LivingEntity)) return;

        String mobKey = mobManager.getCustomMobKey(event.getEntity());
        if (mobKey != null) {
            // 是自訂怪物 → 取消燃燒
            event.setCancelled(true);
        }
    }

    // ══════════════════════════════════════════════════════════
    //  熔核巨獸 Boss 行為系統
    // ══════════════════════════════════════════════════════════

    /** 主 Boss 每 3 秒執行一次 */
    private void magmaCoreBehavior(LivingEntity mob) {
        // 設定超大體型（只在需要時設定，避免覆蓋血量）
        if (mob instanceof MagmaCube cube && cube.getSize() < 8) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(8);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }

        MagmaCoreState state = magmaCoreStates.computeIfAbsent(mob.getUniqueId(), k -> new MagmaCoreState());
        double maxHp  = MobManager.hasVirtualHP(mob) ? MobManager.getVirtualMaxHP(mob) : mob.getMaxHealth();
        double curHp  = MobManager.hasVirtualHP(mob) ? MobManager.getVirtualCurrentHP(mob) : mob.getHealth();
        double hpPct  = curHp / maxHp;
        long   now    = System.currentTimeMillis();
        Location loc  = mob.getLocation();

        // 固定粒子光環
        loc.getWorld().spawnParticle(Particle.LAVA,  loc.clone().add(0, 2.5, 0), 8, 1.8, 1.0, 1.8, 0);
        loc.getWorld().spawnParticle(Particle.FLAME, loc.clone().add(0, 1.0, 0), 5, 1.0, 0.8, 1.0, 0.02);
        if (hpPct < 0.20) {
            loc.getWorld().spawnParticle(Particle.SOUL_FIRE_FLAME, loc.clone().add(0, 3.5, 0), 12, 1.2, 1.2, 1.2, 0.05);
        }

        // ── 分裂階段管理 ──────────────────────────────────────
        if (state.inSplitPhase) {
            // 清理已死亡分裂體
            state.activeSplits.removeIf(uuid -> {
                Entity e = plugin.getServer().getEntity(uuid);
                return e == null || e.isDead();
            });

            if (state.activeSplits.isEmpty()) {
                // 玩家勝利：所有分裂體被消滅
                state.inSplitPhase = false;
                broadcast(loc, 40, ChatColor.GREEN + "[熔核巨獸] 所有分裂體被消滅！熔核巨獸受到重創！");
            } else if (now > state.splitMergeDeadline) {
                // 時間到：強制融合，恢復 15% HP
                for (UUID uid : state.activeSplits) {
                    Entity e = plugin.getServer().getEntity(uid);
                    if (e != null && !e.isDead()) e.remove();
                }
                state.activeSplits.clear();
                state.inSplitPhase = false;
                double heal = maxHp * 0.15;
                if (MobManager.hasVirtualHP(mob)) {
                    MobManager.healVirtualHP(mob, heal);
                } else {
                    mob.setHealth(Math.min(curHp + heal, maxHp));
                }
                loc.getWorld().spawnParticle(Particle.EXPLOSION, loc.clone().add(0, 2, 0), 20, 2, 2, 2, 0.1);
                loc.getWorld().playSound(loc, Sound.ENTITY_GENERIC_EXPLODE, 2.0f, 0.35f);
                broadcast(loc, 60, ChatColor.DARK_RED + "" + ChatColor.BOLD + "[熔核巨獸] 熔核再生！" + ChatColor.RED + "分裂體重新融合，回復 15% 生命值！");
            } else {
                // 倒計時警告
                long remain = (state.splitMergeDeadline - now) / 1000;
                if (remain == 20 || remain == 10 || remain == 5) {
                    broadcast(loc, 50, ChatColor.YELLOW + "[熔核巨獸] 分裂體融合倒計時：" + ChatColor.RED + remain + "秒！");
                    loc.getWorld().playSound(loc, Sound.BLOCK_NOTE_BLOCK_BASS, 1.0f, 0.5f);
                }
            }
            return; // 分裂期間不使用技能
        }

        // ── 血量門檻觸發分裂 ─────────────────────────────────
        if (hpPct <= 0.75 && state.phase == 1) { state.phase = 2; triggerSplit(mob, state); return; }
        if (hpPct <= 0.50 && state.phase == 2) { state.phase = 3; triggerSplit(mob, state); return; }
        if (hpPct <= 0.25 && state.phase == 3) { state.phase = 4; triggerSplit(mob, state); return; }

        // ── 狂暴模式（≤20%）────────────────────────────────
        if (hpPct <= 0.20 && !state.berserkActive) {
            state.berserkActive = true;
            mob.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH,  Integer.MAX_VALUE, 2, false, false));
            mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,     Integer.MAX_VALUE, 1, false, false));
            loc.getWorld().playSound(loc, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.4f);
            broadcast(loc, 80, ChatColor.DARK_RED + "" + ChatColor.BOLD + "⚠ [熔核巨獸] 進入狂暴！！！");
        }

        // 第三/四階段：隨機火柱
        if (state.phase >= 3 && random.nextDouble() < 0.35) {
            spawnFirePillar(mob);
        }

        // ── 技能冷卻（狂暴時縮短）─────────────────────────
        long slamCd  = state.berserkActive ?  8_000L : 14_000L;
        long eruptCd = state.berserkActive ?  6_000L : 10_000L;
        long absorbCd = 25_000L;
        long waveCd  = state.berserkActive ?  8_000L : 15_000L;

        List<Runnable> ready = new ArrayList<>();
        if (now - state.lastSlamMs   > slamCd)  ready.add(() -> magmaLavaSlam(mob, state));
        if (now - state.lastEruptMs  > eruptCd) ready.add(() -> magmaErupt(mob, state));
        if (state.phase >= 2 && now - state.lastAbsorbMs > absorbCd) ready.add(() -> magmaAbsorb(mob, state));
        if (state.phase >= 3 && now - state.lastWaveMs   > waveCd)   ready.add(() -> magmaWave(mob, state));

        if (!ready.isEmpty() && random.nextDouble() < 0.60) {
            ready.get(random.nextInt(ready.size())).run();
        }
    }

    /** 觸發分裂：生成 4 隻中型分裂體，倒計時 30 秒 */
    private void triggerSplit(LivingEntity boss, MagmaCoreState state) {
        Location loc = boss.getLocation();
        state.inSplitPhase = true;
        state.splitMergeDeadline = System.currentTimeMillis() + 30_000L;
        state.activeSplits.clear();

        loc.getWorld().spawnParticle(Particle.EXPLOSION, loc.clone().add(0, 2, 0), 15, 2, 2, 2, 0.1);
        loc.getWorld().playSound(loc, Sound.ENTITY_GENERIC_EXPLODE, 2.0f, 0.3f);
        broadcast(loc, 60, ChatColor.DARK_RED + "" + ChatColor.BOLD + "[熔核巨獸] 熔核分裂！§c在 30 秒內消滅所有分裂體！");
        for (Player p : loc.getWorld().getPlayers()) {
            if (p.getLocation().distance(loc) <= 60) {
                p.sendTitle(ChatColor.RED + "" + ChatColor.BOLD + "⚠ 熔核分裂！", ChatColor.YELLOW + "在 30 秒內擊殺所有分裂體！", 5, 70, 10);
            }
        }

        int level = mobManager.getMobLevel(boss);
        int splitLevel = Math.max(1, level - 5);
        for (int i = 0; i < 4; i++) {
            double angle = (Math.PI * 2.0 / 4) * i;
            Location spawnLoc = loc.clone().add(Math.cos(angle) * 4, 0, Math.sin(angle) * 4);
            spawnLoc.setY(spawnLoc.getWorld().getHighestBlockYAt(spawnLoc) + 1);

            LivingEntity split = mobManager.spawnCustomMobWithLevel("magma_core_medium", spawnLoc, splitLevel);
            if (split != null) {
                split.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
                    org.bukkit.persistence.PersistentDataType.STRING,
                    boss.getUniqueId().toString());
                state.activeSplits.add(split.getUniqueId());
            }
        }
    }

    /** 中型分裂體死亡後，再生成 2 隻小型碎體 */
    private void spawnSmallSplits(LivingEntity medium, int count) {
        Location loc = medium.getLocation();
        String parentUuidStr = medium.getPersistentDataContainer().get(
            new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
            org.bukkit.persistence.PersistentDataType.STRING);

        int level = Math.max(1, mobManager.getMobLevel(medium) - 3);
        for (int i = 0; i < count; i++) {
            double angle = random.nextDouble() * Math.PI * 2;
            Location spawnLoc = loc.clone().add(Math.cos(angle) * 2, 0, Math.sin(angle) * 2);
            spawnLoc.setY(spawnLoc.getWorld().getHighestBlockYAt(spawnLoc) + 1);

            LivingEntity small = mobManager.spawnCustomMobWithLevel("magma_core_small", spawnLoc, level);
            if (small != null && parentUuidStr != null) {
                small.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
                    org.bukkit.persistence.PersistentDataType.STRING, parentUuidStr);
                try {
                    MagmaCoreState bossState = magmaCoreStates.get(UUID.fromString(parentUuidStr));
                    if (bossState != null) bossState.activeSplits.add(small.getUniqueId());
                } catch (Exception ignored) {}
            }
        }
    }

    // ── 技能 1：熔岩重壓 ─────────────────────────────────────
    private void magmaLavaSlam(LivingEntity mob, MagmaCoreState state) {
        state.lastSlamMs = System.currentTimeMillis();
        Location loc = mob.getLocation();
        broadcast(loc, 25, ChatColor.RED + "⚠ 熔核巨獸正在蓄力重壓！");
        mob.getWorld().playSound(loc, Sound.ENTITY_MAGMA_CUBE_JUMP, 2.0f, 0.5f);
        mob.setVelocity(new Vector(0, 1.4, 0));
        loc.getWorld().spawnParticle(Particle.LAVA, loc.clone().add(0, 1, 0), 20, 1.5, 0.5, 1.5, 0);

        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }
                Location landLoc = mob.getLocation();
                landLoc.getWorld().playSound(landLoc, Sound.ENTITY_GENERIC_EXPLODE, 1.8f, 0.35f);

                // 震波粒子環
                for (double r = 1; r <= 7; r += 0.8) {
                    for (double a = 0; a < Math.PI * 2; a += 0.4) {
                        Location pl = landLoc.clone().add(Math.cos(a) * r, 0.1, Math.sin(a) * r);
                        landLoc.getWorld().spawnParticle(Particle.LAVA, pl, 1, 0, 0, 0, 0);
                    }
                }

                // 地面點火
                for (int x = -5; x <= 5; x++) {
                    for (int z = -5; z <= 5; z++) {
                        if (random.nextDouble() < 0.35) {
                            org.bukkit.block.Block above = landLoc.clone().add(x, 0, z).getBlock();
                            org.bukkit.block.Block below = landLoc.clone().add(x, -1, z).getBlock();
                            if (above.getType().isAir() && below.getType().isSolid() && !below.isLiquid()) {
                                above.setType(org.bukkit.Material.FIRE);
                            }
                        }
                    }
                }

                // 擊退 + 傷害玩家
                for (Entity e : landLoc.getWorld().getNearbyEntities(landLoc, 7, 5, 7)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    Vector kb = p.getLocation().toVector().subtract(landLoc.toVector()).normalize().multiply(1.8).setY(0.6);
                    p.setVelocity(kb);
                    p.damage(18.0, mob);
                    p.sendMessage(ChatColor.RED + " 熔核重壓震波！");
                }
                cancel();
            }
        }.runTaskLater(plugin, 32L);
    }

    // ── 技能 2：熔核噴發 ─────────────────────────────────────
    private void magmaErupt(LivingEntity mob, MagmaCoreState state) {
        state.lastEruptMs = System.currentTimeMillis();
        Location loc = mob.getLocation().add(0, 2.5, 0);
        mob.getWorld().playSound(loc, Sound.ENTITY_BLAZE_SHOOT, 1.5f, 0.4f);
        broadcast(mob.getLocation(), 25, ChatColor.RED + "⚠ 熔核噴發！");

        int shots = state.berserkActive ? 12 : 8;
        for (int i = 0; i < shots; i++) {
            double angle = (Math.PI * 2.0 / shots) * i;
            Vector dir = new Vector(Math.cos(angle), 0.25 + random.nextDouble() * 0.25, Math.sin(angle)).normalize().multiply(1.6);
            SmallFireball fb = mob.getWorld().spawn(loc, SmallFireball.class);
            fb.setVelocity(dir);
            fb.setShooter(mob);
            fb.setIsIncendiary(true);
            fb.setYield(2.0f);
        }
    }

    // ── 技能 3：熔岩吞噬 ─────────────────────────────────────
    private void magmaAbsorb(LivingEntity mob, MagmaCoreState state) {
        state.lastAbsorbMs = System.currentTimeMillis();
        Location loc = mob.getLocation();
        broadcast(loc, 30, ChatColor.GOLD + "⚠ 熔核吞噬！摧毀附近的熔岩阻止回血！");
        mob.getWorld().playSound(loc, Sound.BLOCK_LAVA_AMBIENT, 2.0f, 0.5f);

        // 在周圍放 3 塊熔岩（玩家可以清除）
        List<org.bukkit.block.Block> lavaBlocks = new ArrayList<>();
        for (int t = 0; t < 3; t++) {
            double angle = random.nextDouble() * Math.PI * 2;
            int dist = 4 + random.nextInt(4);
            org.bukkit.block.Block above = loc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist).getBlock();
            org.bukkit.block.Block below = above.getRelative(org.bukkit.block.BlockFace.DOWN);
            if (above.getType().isAir() && below.getType().isSolid() && !below.isLiquid()) {
                above.setType(org.bukkit.Material.LAVA);
                lavaBlocks.add(above);
            }
        }

        // 吸收粒子動畫
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (mob.isDead() || ticks >= 20) { cancel(); return; }
                Location center = mob.getLocation().add(0, 1, 0);
                for (int k = 0; k < 8; k++) {
                    double px = center.getX() + (random.nextDouble() - 0.5) * 12;
                    double py = center.getY() + (random.nextDouble() - 0.5) * 4;
                    double pz = center.getZ() + (random.nextDouble() - 0.5) * 12;
                    center.getWorld().spawnParticle(Particle.DRIPPING_LAVA, new Location(center.getWorld(), px, py, pz), 1, 0, 0, 0, 0);
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 5L);

        // 5 秒後判定
        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isDead()) { lavaBlocks.forEach(b -> { if (b.getType() == org.bukkit.Material.LAVA) b.setType(org.bukkit.Material.AIR); }); return; }
                long remaining = lavaBlocks.stream().filter(b -> b.getType() == org.bukkit.Material.LAVA).count();
                if (remaining > 0) {
                    double heal = mob.getMaxHealth() * 0.05 * remaining;
                    if (MobManager.hasVirtualHP(mob)) {
                        MobManager.healVirtualHP(mob, heal);
                        double vCurrent = MobManager.getVirtualCurrentHP(mob);
                        broadcast(mob.getLocation(), 35, ChatColor.RED + "[熔核巨獸] 吸收了熔岩！回復 " + ChatColor.YELLOW + (int)(heal * MobManager.getVirtualMaxHP(mob) / MobManager.getMcMaxHealthCap()) + ChatColor.RED + " 生命值！");
                    } else {
                        mob.setHealth(Math.min(mob.getHealth() + heal, mob.getMaxHealth()));
                        broadcast(mob.getLocation(), 35, ChatColor.RED + "[熔核巨獸] 吸收了熔岩！回復 " + ChatColor.YELLOW + (int) heal + ChatColor.RED + " 生命值！");
                    }
                    mob.getWorld().spawnParticle(Particle.HEART, mob.getLocation().add(0, 3, 0), 10, 0.5, 0.5, 0.5, 0.1);
                } else {
                    broadcast(mob.getLocation(), 35, ChatColor.GREEN + "[熔核巨獸] 熔岩被全數摧毀！回血被阻止！");
                }
                lavaBlocks.forEach(b -> { if (b.getType() == org.bukkit.Material.LAVA) b.setType(org.bukkit.Material.AIR); });
            }
        }.runTaskLater(plugin, 100L);
    }

    // ── 技能 4：岩漿浪潮 ─────────────────────────────────────
    private void magmaWave(LivingEntity mob, MagmaCoreState state) {
        state.lastWaveMs = System.currentTimeMillis();
        Player target = getNearestPlayer(mob, 28.0);
        if (target == null) return;

        Location mobLoc = mob.getLocation();
        Vector toward = target.getLocation().toVector().subtract(mobLoc.toVector()).normalize();
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_MAGMA_CUBE_SQUISH_SMALL, 2.0f, 0.35f);
        broadcast(mobLoc, 28, ChatColor.RED + "⚠ 岩漿浪潮！");

        new BukkitRunnable() {
            int wave = 0;
            @Override
            public void run() {
                if (wave >= 9 || mob.isDead()) { cancel(); return; }
                double dist = 2.5 + wave * 1.8;
                // 扇形粒子
                for (double a = -Math.PI / 3; a <= Math.PI / 3; a += 0.25) {
                    double sx = Math.cos(a) * toward.getX() - Math.sin(a) * toward.getZ();
                    double sz = Math.sin(a) * toward.getX() + Math.cos(a) * toward.getZ();
                    Location pl = mobLoc.clone().add(sx * dist, 0.5, sz * dist);
                    mobLoc.getWorld().spawnParticle(Particle.LAVA, pl, 2, 0.1, 0.2, 0.1, 0);
                    mobLoc.getWorld().spawnParticle(Particle.FLAME, pl, 1, 0, 0, 0, 0.04);
                }
                // 波浪中心傷害
                Location waveCenter = mobLoc.clone().add(toward.clone().multiply(dist)).add(0, 0.5, 0);
                for (Entity e : waveCenter.getWorld().getNearbyEntities(waveCenter, 3, 2, 3)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    p.setVelocity(toward.clone().multiply(1.5).setY(0.35));
                    p.setFireTicks(80);
                    p.damage(8.0, mob);
                    p.sendMessage(ChatColor.RED + " 岩漿浪潮衝擊！");
                }
                wave++;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    // ── 第三/四階段：火柱 ────────────────────────────────────
    private void spawnFirePillar(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 28.0);
        if (target == null) return;
        Location pillarLoc = target.getLocation().clone().add(
            (random.nextDouble() - 0.5) * 8, 0, (random.nextDouble() - 0.5) * 8);
        pillarLoc.setY(pillarLoc.getWorld().getHighestBlockYAt(pillarLoc));
        final Location finalLoc = pillarLoc;

        // 0.5s 警告後火柱噴發
        new BukkitRunnable() {
            @Override
            public void run() {
                finalLoc.getWorld().spawnParticle(Particle.SMOKE, finalLoc.clone().add(0, 0.5, 0), 6, 0.3, 0, 0.3, 0.02);
            }
        }.runTaskTimer(plugin, 0L, 5L);

        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 30 || mob.isDead()) { cancel(); return; }
                for (int h = 0; h <= 5; h++) {
                    finalLoc.getWorld().spawnParticle(Particle.FLAME, finalLoc.clone().add(0, h, 0), 4, 0.3, 0, 0.3, 0.06);
                    finalLoc.getWorld().spawnParticle(Particle.LAVA,  finalLoc.clone().add(0, h, 0), 1, 0.2, 0, 0.2, 0);
                }
                for (Entity e : finalLoc.getWorld().getNearbyEntities(finalLoc, 1.5, 6, 1.5)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    p.setFireTicks(60);
                    p.damage(5.0, mob);
                }
                ticks += 5;
            }
        }.runTaskLater(plugin, 10L);
    }

    // ── 中型分裂體行為 ────────────────────────────────────────
    private void magmaMediumBehavior(LivingEntity mob) {
        if (mob instanceof MagmaCube cube && cube.getSize() < 3) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(3);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }
        mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0), 3, 0.5, 0.3, 0.5, 0);
        // 25% 機率朝最近玩家跳躍
        if (random.nextDouble() < 0.25) {
            Player t = getNearestPlayer(mob, 16.0);
            if (t != null) {
                Vector leap = t.getLocation().toVector().subtract(mob.getLocation().toVector())
                    .normalize().multiply(1.0).setY(0.9);
                mob.setVelocity(leap);
                mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_MAGMA_CUBE_JUMP, 1.0f, 0.7f);
            }
        }
    }

    // ── 小型碎體行為 ─────────────────────────────────────────
    private void magmaSmallBehavior(LivingEntity mob) {
        if (mob instanceof MagmaCube cube && cube.getSize() != 1) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(1);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }
        if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 120, 3, false, false));
        }
        mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 0.3, 0), 2, 0.2, 0.2, 0.2, 0.02);
    }

    /** 向 Boss 周圍玩家廣播訊息 */
    private void broadcast(Location center, double radius, String msg) {
        for (Player p : center.getWorld().getPlayers()) {
            if (p.getLocation().distance(center) <= radius) {
                p.sendMessage(msg);
            }
        }
    }
}

package com.customrpg.listeners;

import com.customrpg.CustomRPG;
import com.customrpg.managers.MobManager;
import com.customrpg.managers.PlayerStatsManager;
import com.customrpg.managers.WeaponManager;
import org.bukkit.*;
import org.bukkit.entity.*;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityCombustEvent;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.EntityDamageEvent;
import org.bukkit.event.entity.EntityDeathEvent;
import org.bukkit.event.entity.EntityRegainHealthEvent;
import org.bukkit.event.entity.ProjectileHitEvent;
import org.bukkit.event.entity.ProjectileLaunchEvent;
import org.bukkit.inventory.ItemStack;
import org.bukkit.potion.PotionEffect;
import org.bukkit.potion.PotionEffectType;
import org.bukkit.projectiles.ProjectileSource;
import org.bukkit.scheduler.BukkitRunnable;
import org.bukkit.util.Vector;

import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.Random;
import java.util.UUID;

/**
 * MobListener - Handles custom mob behavior events
 *
 * This listener implements special behaviors for custom mobs such as
 * projectile attacks, death mechanics, and combat modifications.
 *
 * Handles:
 * - Snow Zombie: Throws snowballs periodically
 * - Fire Skeleton: Shoots fire arrows
 * - Giant Slime: Splits into smaller slimes on death
 */
public class MobListener implements Listener {

    private final CustomRPG plugin;
    private final MobManager mobManager;
    private final PlayerStatsManager statsManager;
    private final WeaponManager weaponManager;
    private final Random random;

    // ══ 熔核巨獸 (boss_magma_core) 階段狀態追蹤 ══
    private final Map<UUID, MagmaCoreState> magmaCoreStates = new HashMap<>();

    private static class MagmaCoreState {
        int phase = 1;          // 1=初始, 2=75%分裂完, 3=50%分裂完, 4=25%分裂完
        boolean inSplitPhase = false;
        long splitMergeDeadline = 0L;
        final List<UUID> activeSplits = new ArrayList<>();
        long lastSlamMs    = 0L;   // 冷卻 14s (狂暴 8s)
        long lastEruptMs   = 0L;   // 冷卻 10s (狂暴 6s)
        long lastAbsorbMs  = 0L;   // 冷卻 25s
        long lastWaveMs    = 0L;   // 冷卻 15s (狂暴 8s)
        boolean berserkActive = false;
    }

    /**
     * Constructor for MobListener
     * @param plugin Main plugin instance
     * @param mobManager MobManager instance
     */
    public MobListener(CustomRPG plugin, MobManager mobManager, PlayerStatsManager statsManager, WeaponManager weaponManager) {
        this.plugin = plugin;
        this.mobManager = mobManager;
        this.statsManager = statsManager;
        this.weaponManager = weaponManager;
        this.random = new Random();
        startCustomMobBehaviors();
    }

    /**
     * Start periodic behaviors for custom mobs
     */
    private void startCustomMobBehaviors() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (org.bukkit.World world : plugin.getServer().getWorlds()) {
                    for (Entity entity : world.getEntities()) {
                        String mobKey = mobManager.getCustomMobKey(entity);
                        if (mobKey == null) continue;

                        MobManager.MobData mobData = mobManager.getMobData(mobKey);
                        if (mobData == null) continue;

                        applyPeriodicBehavior(entity, mobData);
                    }
                }
            }
        }.runTaskTimer(plugin, 0L, 60L);
    }

    /**
     * Apply periodic behaviors to custom mobs
     * @param entity The mob entity
     * @param mobData The mob data
     */
    private void applyPeriodicBehavior(Entity entity, MobManager.MobData mobData) {
        if (!(entity instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) entity;
        String behavior = mobData.getSpecialBehavior().toLowerCase();

        switch (behavior) {
            case "snowball_thrower" -> {
                if (random.nextDouble() < 0.3) {
                    throwSnowball(mob);
                }
            }
            case "snowball_mage" -> {
                // 骷髏法師：丟出傷害性雪球
                if (random.nextDouble() < 0.4) {
                    throwDamagingSnowball(mob);
                }
            }
            case "shadow_teleport" -> {
                // 影襲蜘蛛：暗影粒子 + 短距離瞬移
                // 持續噴出粒子
                Location loc = mob.getLocation().add(0, 0.5, 0);
                mob.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, loc, 2, 0.3, 0.3, 0.3, 0);
                mob.getWorld().spawnParticle(Particle.SQUID_INK, loc, 1, 0.2, 0.2, 0.2, 0.01);

                // 15% 機率瞬移到附近玩家身邊
                if (random.nextDouble() < 0.15) {
                    shadowTeleport(mob);
                }
            }
            case "charge_attack" -> {
                // 狂暴野豬：直線衝撞
                if (random.nextDouble() < 0.2) {
                    chargeAttack(mob);
                }
            }
            case "flee" -> {
                // 逃跑型：看到玩家就跑
                fleeFromPlayer(mob);
            }
            case "stalker_stealth" -> {
                // 潛伏蜘蛛：靠近玩家時隱形
                stalkerStealth(mob);
            }
            case "plague_aura" -> {
                // 瘟疫散播者：周圍持續毒氣
                plagueAura(mob);
            }
            case "charge_beast" -> {
                // 衝鋒野獸：鎖定後直線衝刺
                if (random.nextDouble() < 0.2) {
                    chargeBeastAttack(mob);
                }
            }
            case "berserker_rage" -> {
                // 狂戰殭屍：低血量時發紅光粒子
                double hpPercent = MobManager.hasVirtualHP(mob)
                        ? MobManager.getVirtualCurrentHP(mob) / MobManager.getVirtualMaxHP(mob)
                        : mob.getHealth() / mob.getMaxHealth();
                if (hpPercent < 0.3) {
                    mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, mob.getLocation().add(0, 1, 0),
                            3, 0.3, 0.3, 0.3, 0.02);
                }
            }
            // ═══ 野外 Boss 行為 ═══
            case "boss_pumpkin_knight" -> {
                // 南瓜騎士：Boss 光環粒子
                mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 2.2, 0),
                        3, 0.2, 0.1, 0.2, 0.01);
            }
            case "boss_scissor_frenzy" -> {
                // 瘋狂剪刀手：快速揮砍粒子 + 加速
                mob.getWorld().spawnParticle(Particle.SWEEP_ATTACK, mob.getLocation().add(0, 1, 0),
                        1, 0.5, 0.3, 0.5, 0);
                if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
                    mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 80, 1, false, false));
                }
            }
            case "boss_zombie_beast" -> {
                // 豬屍獸：衝撞（10秒冷卻）+ Boss 粒子
                mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                        1, 0.3, 0.3, 0.3, 0);
                bossZombieBeastCharge(mob);
            }
            // ══ 熔核巨獸系列 ══
            case "boss_magma_core"   -> magmaCoreBehavior(mob);
            case "magma_core_medium" -> magmaMediumBehavior(mob);
            case "magma_core_small"  -> magmaSmallBehavior(mob);
        }
    }

    /**
     * Handle custom mob death events
     * @param event EntityDeathEvent
     */
    @EventHandler(priority = EventPriority.HIGH)
    public void onMobDeath(EntityDeathEvent event) {
        // 排除玩家死亡
        if (event.getEntity() instanceof Player) {
            return;
        }

        Player killer = event.getEntity().getKiller();
        if (killer == null) {
            // 支援野獸擊殺：如果 killer 為 null，檢查 beast_kill_owner metadata
            if (event.getEntity().hasMetadata("beast_kill_owner")) {
                try {
                    String ownerId = event.getEntity().getMetadata("beast_kill_owner").get(0).asString();
                    Player owner = Bukkit.getPlayer(UUID.fromString(ownerId));
                    if (owner != null && owner.isOnline()) {
                        killer = owner;
                    }
                } catch (Exception ignored) {}
            }
        }

        String mobKey = mobManager.getCustomMobKey(event.getEntity());

        // 如果是自製怪物
        if (mobKey != null) {
            MobManager.MobData mobData = mobManager.getMobData(mobKey);
            if (mobData == null) {
                return;
            }

            // 沒有擊殺者（例如跌落死亡），跳過獎勵
            if (killer == null) {
                return;
            }

            int mobLevel = mobManager.getMobLevel(event.getEntity());

            // Handle custom mob drops or effects
            // For example, splitting slimes
            if (mobData.getSpecialBehavior().equalsIgnoreCase("split_on_death")) {
                splitSlime(event.getEntity(), mobData);
            }

            // 黏液爆破者：延遲爆炸
            if (mobData.getSpecialBehavior().equalsIgnoreCase("delayed_explosion")) {
                delayedExplosion(event.getEntity().getLocation(), mobLevel);
            }

            // 熔核巨獸：Boss 死亡 → 清理狀態 + 公告
            if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_magma_core")) {
                MagmaCoreState bossState = magmaCoreStates.remove(event.getEntity().getUniqueId());
                if (bossState != null) {
                    for (UUID splitUuid : bossState.activeSplits) {
                        Entity e = plugin.getServer().getEntity(splitUuid);
                        if (e != null && !e.isDead()) e.remove();
                    }
                }
                Location dl = event.getEntity().getLocation();
                dl.getWorld().spawnParticle(Particle.EXPLOSION_EMITTER, dl.clone().add(0, 2, 0), 4, 2, 2, 2, 0);
                dl.getWorld().playSound(dl, Sound.ENTITY_ENDER_DRAGON_DEATH, 0.5f, 0.5f);
                for (Player p : dl.getWorld().getPlayers()) {
                    if (p.getLocation().distance(dl) <= 100) {
                        p.sendMessage(ChatColor.GOLD + "" + ChatColor.BOLD + "[熔核巨獸] " + ChatColor.YELLOW + "熔岩之核冷卻沉眠... 已被討伐！");
                        p.sendTitle(ChatColor.GOLD + "" + ChatColor.BOLD + "BOSS 擊敗！", ChatColor.WHITE + "✦ 熔核巨獸 ✦", 10, 80, 20);
                    }
                }
            }

            // 熔核分裂體：死亡 → 分裂成 2 隻小型碎體
            if (mobData.getSpecialBehavior().equalsIgnoreCase("magma_core_medium")) {
                spawnSmallSplits(event.getEntity(), 2);
            }

            // 清除預設掉落物（如果有自定義掉落物）
            if (!mobData.getVanillaDrops().isEmpty() || !mobData.getWeaponDrops().isEmpty() || !mobData.getEquipmentDrops().isEmpty()) {
                event.getDrops().clear();

                // 掉落原版物品
                for (MobManager.DropItem dropItem : mobData.getVanillaDrops()) {
                    if (random.nextDouble() < dropItem.getChance()) {
                        int amount = dropItem.getMinAmount();
                        if (dropItem.getMaxAmount() > dropItem.getMinAmount()) {
                            amount = random.nextInt(dropItem.getMaxAmount() - dropItem.getMinAmount() + 1) + dropItem.getMinAmount();
                        }
                        event.getDrops().add(new ItemStack(dropItem.getMaterial(), amount));
                    }
                }

                // 掉落自定義武器
                for (MobManager.WeaponDrop weaponDrop : mobData.getWeaponDrops()) {
                    if (random.nextDouble() < weaponDrop.getChance()) {
                        ItemStack weapon = weaponManager.createWeapon(weaponDrop.getWeaponKey());
                        if (weapon != null) {
                            event.getDrops().add(weapon);
                            killer.sendMessage(ChatColor.GOLD + "★ 獲得稀有武器: " + weapon.getItemMeta().getDisplayName());
                        }
                    }
                }

                // 掉落自定義裝備 (飾品 / 裝甲)
                for (MobManager.EquipmentDrop equipDrop : mobData.getEquipmentDrops()) {
                    if (random.nextDouble() < equipDrop.getChance()) {
                        ItemStack dropItem = null;
                        if ("armor".equalsIgnoreCase(equipDrop.getType())) {
                            // 裝甲掉落
                            com.customrpg.equipment.ArmorManager armorMgr = plugin.getArmorManager();
                            if (armorMgr != null) {
                                com.customrpg.equipment.ArmorData armor = armorMgr.createArmor(equipDrop.getEquipmentKey());
                                if (armor != null) {
                                    dropItem = armor.toItemStack();
                                }
                            }
                        } else {
                            // 飾品掉落
                            com.customrpg.equipment.EquipmentManager equipMgr = plugin.getEquipmentManager();
                            if (equipMgr != null) {
                                com.customrpg.equipment.EquipmentData equip = equipMgr.createEquipment(equipDrop.getEquipmentKey());
                                if (equip != null) {
                                    dropItem = equip.toItemStack();
                                }
                            }
                        }
                        if (dropItem != null) {
                            event.getDrops().add(dropItem);
                            String itemName = dropItem.hasItemMeta() && dropItem.getItemMeta().hasDisplayName()
                                    ? dropItem.getItemMeta().getDisplayName()
                                    : equipDrop.getEquipmentKey();
                            killer.sendMessage(ChatColor.LIGHT_PURPLE + "★ 獲得稀有裝備: " + itemName);
                        }
                    }
                }
            }

            // 給予經驗值（基於等級 + 階級倍率 + 等級差距調整）
            int baseExpReward = mobData.calculateExp(mobLevel);

            // 階級經驗倍率：普通 x1, 精英 x2.5, Boss x5
            String mobTier = mobManager.getMobTier(event.getEntity());
            double tierMultiplier = switch (mobTier) {
                case "ELITE" -> 2.5;
                case "BOSS" -> 5.0;
                default -> 1.0;
            };

            // 等級差距調整：怪物等級比玩家高 → 加成，比玩家低太多 → 減少
            com.customrpg.players.PlayerStats killerStats = statsManager.getStats(killer);
            int playerLevel = killerStats.getLevel();
            int levelDiff = mobLevel - playerLevel;
            double levelMultiplier;
            if (levelDiff >= 5) {
                levelMultiplier = 1.5;  // 怪物比玩家高 5 級以上 → +50%
            } else if (levelDiff >= 0) {
                levelMultiplier = 1.0 + (levelDiff * 0.05); // 每高 1 級 +5%
            } else if (levelDiff >= -5) {
                levelMultiplier = 1.0;  // 低 1~5 級 → 正常
            } else if (levelDiff >= -10) {
                levelMultiplier = 0.5;  // 低 6~10 級 → 50%
            } else {
                levelMultiplier = 0.1;  // 低 10 級以上 → 10%（防止刷低等怪）
            }

            int finalExp = Math.max(1, (int) (baseExpReward * tierMultiplier * levelMultiplier));
            if (finalExp > 0) {
                statsManager.addExp(killer, finalExp);

                // 根據階級顯示不同顏色的訊息
                String tierTag = switch (mobTier) {
                    case "ELITE" -> ChatColor.GOLD + "[精英] ";
                    case "BOSS" -> ChatColor.RED + "[BOSS] ";
                    default -> "";
                };

                killer.sendMessage(ChatColor.YELLOW + "擊敗 " + tierTag +
                    ChatColor.YELLOW + "[Lv." + mobLevel + "] " +
                    ChatColor.stripColor(mobData.getName()) + " 獲得 " +
                    ChatColor.GREEN + finalExp + ChatColor.YELLOW + " 經驗值" +
                    (tierMultiplier > 1.0 ? ChatColor.GOLD + " (x" + tierMultiplier + ")" : ""));
            }

            // 移除 BossBar
            com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
            if (bossBarMgr != null) {
                bossBarMgr.onMobDeath(event.getEntity().getUniqueId());
            }

            // 通知 BeautyQuests 擊殺進度
            com.customrpg.integration.BeautyQuestsHook bqHook = plugin.getBeautyQuestsHook();
            if (bqHook != null && bqHook.isEnabled()) {
                bqHook.notifyMobDeath(event, mobKey, event.getEntity(), killer);
            }

            com.customrpg.managers.BossZoneManager bossZoneManager = plugin.getBossZoneManager();
            if (bossZoneManager != null) {
                bossZoneManager.handleEntityDeath(event.getEntity());
            }
        } else {
            // 普通原版怪物：依類型給予不同經驗值
            if (killer == null) return; // 無擊殺者（跌落、其他原因死亡）
            int vanillaExp = switch (event.getEntity().getType()) {
                case ENDER_DRAGON -> 500;
                case WITHER -> 300;
                case ELDER_GUARDIAN -> 80;
                case WARDEN -> 100;
                case RAVAGER -> 50;
                case EVOKER, VINDICATOR -> 20;
                case GHAST, BLAZE, GUARDIAN -> 15;
                case ENDERMAN, PIGLIN_BRUTE -> 10;
                case CREEPER, SKELETON, ZOMBIE, SPIDER -> 5;
                case SLIME, MAGMA_CUBE -> 3;
                default -> 2;
            };
            statsManager.addExp(killer, vanillaExp);
            killer.sendMessage(ChatColor.YELLOW + "獲得 " + vanillaExp + " 經驗值");
        }
    }

    /**
     * Handle custom mob damage events (level-scaled damage)
     * 處理玩家攻擊 BlockDisplay 偽裝系統的情況
     * @param event EntityDamageByEntityEvent
     */
    @EventHandler
    public void onMobAttack(EntityDamageByEntityEvent event) {
        // === 情況 1：玩家攻擊 BlockDisplay 或名稱標籤 ArmorStand ===
        // BlockDisplay 和 ArmorStand 不是 LivingEntity，需要找到對應的隱形核心
        if (event.getDamager() instanceof Player player) {
            Entity target = event.getEntity();

            // 檢查是否攻擊到 BlockDisplay
            if (target instanceof org.bukkit.entity.BlockDisplay) {
                event.setCancelled(true); // 取消對 BlockDisplay 的傷害

                // 從 BlockDisplay 的 PersistentData 獲取核心 UUID
                String coreUuidString = target.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_blockdisplay"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害（考慮玩家的武器）
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                // 這裡可以加入自定義武器傷害計算
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊 BlockDisplay，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }

            // 檢查是否攻擊到名稱標籤 ArmorStand
            if (target instanceof ArmorStand armorStand) {
                String coreUuidString = armorStand.getPersistentDataContainer().get(
                    new org.bukkit.NamespacedKey(plugin, "disguise_nametag"),
                    org.bukkit.persistence.PersistentDataType.STRING
                );

                if (coreUuidString != null) {
                    event.setCancelled(true); // 取消對 ArmorStand 的傷害

                    java.util.UUID coreUuid = java.util.UUID.fromString(coreUuidString);
                    // 在同一世界中尋找核心實體
                    for (Entity entity : target.getWorld().getEntities()) {
                        if (entity.getUniqueId().equals(coreUuid) && entity instanceof LivingEntity core) {
                            // 找到核心，對其造成傷害

                            // 計算傷害
                            double damage = 1.0;
                            ItemStack weapon = player.getInventory().getItemInMainHand();
                            if (weapon != null && !weapon.getType().isAir()) {
                                damage = weaponManager.getBaseDamage(weapon);
                            }

                            core.damage(damage, player);
                            plugin.getLogger().fine("玩家攻擊名稱標籤，轉移 " + damage + " 傷害到核心");
                            return;
                        }
                    }
                }
            }
        }

        // === 情況 1.5：玩家攻擊自訂 Boss 怪物（特殊防禦機制）===
        if (event.getDamager() instanceof Player player && event.getEntity() instanceof LivingEntity target) {
            String targetMobKey = mobManager.getCustomMobKey(target);
            if (targetMobKey != null) {
                MobManager.MobData targetData = mobManager.getMobData(targetMobKey);
                if (targetData != null) {
                    // 南瓜騎士：35% 格擋 → 減傷60%
                    if (targetData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
                        if (random.nextDouble() < 0.35) {
                            event.setDamage(event.getDamage() * 0.4);
                            target.getWorld().spawnParticle(Particle.ENCHANTED_HIT, target.getLocation().add(0, 1, 0),
                                    10, 0.3, 0.3, 0.3, 0.05);
                            target.getWorld().playSound(target.getLocation(), Sound.ITEM_SHIELD_BLOCK, 1.0f, 1.0f);
                            player.sendMessage(ChatColor.YELLOW + " 南瓜騎士格擋了你的攻擊！");
                        }
                    }
                }

                // BossBar 顯示：玩家攻擊自訂怪物時顯示血量條
                com.customrpg.managers.BossBarManager bossBarMgr = plugin.getBossBarManager();
                if (bossBarMgr != null) {
                    // 延遲1tick更新，讓傷害先生效
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (!target.isDead()) {
                                bossBarMgr.onMobDamaged(target);
                            }
                        }
                    }.runTaskLater(plugin, 1L);
                }
            }
        }

        // === 情況 2：自定義生物攻擊玩家（等級化傷害）===
        // 檢查是否為自定義生物攻擊玩家
        if (!(event.getDamager() instanceof LivingEntity)) {
            return;
        }

        if (!(event.getEntity() instanceof Player)) {
            return;
        }

        LivingEntity attacker = (LivingEntity) event.getDamager();
        String mobKey = mobManager.getCustomMobKey(attacker);

        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        // 獲取生物等級並計算傷害
        int mobLevel = mobManager.getMobLevel(attacker);
        double scaledDamage = mobData.calculateDamage(mobLevel);

        // 狂戰殭屍：HP < 30% → +50% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("berserker_rage")) {
            double hpPercent = MobManager.hasVirtualHP(attacker)
                    ? MobManager.getVirtualCurrentHP(attacker) / MobManager.getVirtualMaxHP(attacker)
                    : attacker.getHealth() / attacker.getMaxHealth();
            if (hpPercent < 0.3) {
                scaledDamage *= 1.5;
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, attacker.getLocation().add(0, 1.5, 0),
                        8, 0.3, 0.3, 0.3, 0.05);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.4f, 1.5f);
            }
        }

        // 潛伏蜘蛛：隱形狀態下第一擊 +80% 傷害
        if (mobData.getSpecialBehavior().equalsIgnoreCase("stalker_stealth")) {
            if (attacker.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
                scaledDamage *= 1.8;
                attacker.removePotionEffect(PotionEffectType.INVISIBILITY);
                attacker.getWorld().spawnParticle(Particle.CRIT, attacker.getLocation().add(0, 1, 0),
                        15, 0.3, 0.3, 0.3, 0.1);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_CRIT, 1.0f, 1.0f);
            }
        }

        // 設置等級化傷害（對於偽裝生物，確保傷害大於0）
        if (scaledDamage < 1.0) {
            scaledDamage = 1.0; // 最低傷害為 1
        }
        event.setDamage(scaledDamage);

        // 冰霜殭屍：攻擊附帶緩速
        if (mobData.getSpecialBehavior().equalsIgnoreCase("frost_attack")) {
            if (event.getEntity() instanceof Player victim) {
                victim.addPotionEffect(new PotionEffect(PotionEffectType.SLOWNESS, 60, 1)); // 3秒 緩速II
                victim.getWorld().spawnParticle(Particle.SNOWFLAKE, victim.getLocation().add(0, 1, 0),
                        10, 0.3, 0.5, 0.3, 0.02);
                victim.getWorld().playSound(victim.getLocation(), Sound.BLOCK_GLASS_BREAK, 0.5f, 1.8f);
            }
        }

        // ═══ 南瓜騎士：30% 重擊（2倍傷害 + 擊退） ═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_pumpkin_knight")) {
            if (random.nextDouble() < 0.3) {
                scaledDamage *= 2.0;
                event.setDamage(scaledDamage);
                if (event.getEntity() instanceof Player victim) {
                    Vector knockback = attacker.getLocation().getDirection().normalize().multiply(1.0).setY(0.4);
                    victim.setVelocity(knockback);
                    attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.0f, 0.6f);
                    attacker.getWorld().spawnParticle(Particle.CRIT, victim.getLocation().add(0, 1, 0),
                            20, 0.3, 0.3, 0.3, 0.1);
                    victim.sendMessage(ChatColor.RED + "⚔ 南瓜騎士使出了重擊！");
                }
            }
        }

        // ═══ 瘋狂剪刀手：每次攻擊附帶流血（凋零 1 秒）+ 雙重攻擊（40% 機率連擊）═══
        if (mobData.getSpecialBehavior().equalsIgnoreCase("boss_scissor_frenzy")) {
            if (event.getEntity() instanceof Player victim) {
                // 流血
                victim.addPotionEffect(new PotionEffect(PotionEffectType.WITHER, 20, 0, false, true)); // 1秒凋零
                attacker.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, victim.getLocation().add(0, 1, 0),
                        5, 0.2, 0.3, 0.2, 0.02);
                attacker.getWorld().playSound(attacker.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 1.0f, 1.5f);

                // 40% 連擊（延遲 5 tick 再打一下）
                if (random.nextDouble() < 0.4) {
                    final double comboDamage = scaledDamage * 0.6;
                    new BukkitRunnable() {
                        @Override
                        public void run() {
                            if (attacker.isDead() || victim.isDead()) return;
                            if (attacker.getLocation().distance(victim.getLocation()) > 4) return;
                            victim.damage(comboDamage, attacker);
                            attacker.getWorld().spawnParticle(Particle.SWEEP_ATTACK, victim.getLocation().add(0, 1, 0),
                                    3, 0.3, 0.3, 0.3, 0);
                            attacker.getWorld().playSound(victim.getLocation(), Sound.ENTITY_PLAYER_ATTACK_SWEEP, 0.8f, 1.8f);
                        }
                    }.runTaskLater(plugin, 5L);
                }
            }
        }

        // Debug 訊息
        plugin.getLogger().info("Custom mob " + mobData.getName() + " (Lv." + mobLevel + ") attacked player with " + scaledDamage + " damage");
    }

    /**
     * Split a giant slime into smaller ones
     * @param entity The dying entity
     * @param mobData The mob data
     */
    private void splitSlime(LivingEntity entity, MobManager.MobData mobData) {
        Location location = entity.getLocation();

        for (int i = 0; i < 4; i++) {
            Slime smallSlime = (Slime) location.getWorld().spawnEntity(location, EntityType.SLIME);
            smallSlime.setSize(1);

            Vector velocity = new Vector(
                random.nextDouble() - 0.5,
                0.5,
                random.nextDouble() - 0.5
            ).normalize().multiply(0.5);
            smallSlime.setVelocity(velocity);
        }
    }

    /**
     * Handle projectile launch events for custom mobs
     * @param event ProjectileLaunchEvent
     */
    @EventHandler
    public void onProjectileLaunch(ProjectileLaunchEvent event) {
        ProjectileSource shooter = event.getEntity().getShooter();
        if (!(shooter instanceof LivingEntity)) {
            return;
        }

        LivingEntity mob = (LivingEntity) shooter;
        String mobKey = mobManager.getCustomMobKey(mob);
        if (mobKey == null) {
            return;
        }

        MobManager.MobData mobData = mobManager.getMobData(mobKey);
        if (mobData == null) {
            return;
        }

        if (mobData.getSpecialBehavior().equalsIgnoreCase("fire_arrows")) {
            if (event.getEntity() instanceof Arrow) {
                Arrow arrow = (Arrow) event.getEntity();
                arrow.setFireTicks(1000);
            }
        }

        // 爆裂骷髏：標記箭矢為爆炸箭
        if (mobData.getSpecialBehavior().equalsIgnoreCase("explosive_arrow")) {
            if (event.getEntity() instanceof Arrow arrow) {
                arrow.getPersistentDataContainer().set(
                        new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                        org.bukkit.persistence.PersistentDataType.BOOLEAN, true
                );
                // 火焰軌跡視覺提示
                arrow.setFireTicks(200);
            }
        }
    }

    /**
     * Throw a snowball from the mob
     * @param mob The mob entity
     */
    private void throwSnowball(LivingEntity mob) {
        Player nearestPlayer = getNearestPlayer(mob, 15.0);
        if (nearestPlayer == null) {
            return;
        }

        Location mobLocation = mob.getEyeLocation();
        Location playerLocation = nearestPlayer.getEyeLocation();

        Vector direction = playerLocation.toVector().subtract(mobLocation.toVector()).normalize();

        Snowball snowball = (Snowball) mob.getWorld().spawnEntity(mobLocation, EntityType.SNOWBALL);
        snowball.setVelocity(direction.multiply(1.5));
        snowball.setShooter(mob);
    }

    /**
     * Get the nearest player to a mob within range
     * @param mob The mob entity
     * @param range The search range
     * @return The nearest player or null
     */
    private Player getNearestPlayer(LivingEntity mob, double range) {
        Player nearest = null;
        double nearestDistance = range;

        for (Entity entity : mob.getNearbyEntities(range, range, range)) {
            if (entity instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                double distance = mob.getLocation().distance(player.getLocation());
                if (distance < nearestDistance) {
                    nearest = player;
                    nearestDistance = distance;
                }
            }
        }

        return nearest;
    }

    // ═══════════════════════════════════════
    //  新增特殊行為
    // ═══════════════════════════════════════

    /**
     * 黏液爆破者：死亡2秒後小範圍爆炸
     */
    private void delayedExplosion(Location deathLocation, int mobLevel) {
        // 生成粒子警告
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 40) { // 2秒 = 40 ticks
                    // 爆炸！
                    deathLocation.getWorld().spawnParticle(Particle.EXPLOSION, deathLocation, 3, 0.5, 0.5, 0.5, 0);
                    deathLocation.getWorld().spawnParticle(Particle.HAPPY_VILLAGER, deathLocation, 30, 1.5, 1.0, 1.5, 0.1);
                    deathLocation.getWorld().playSound(deathLocation, Sound.ENTITY_GENERIC_EXPLODE, 1.0f, 1.5f);

                    // 對範圍內玩家造成傷害（半徑3格）
                    double damage = 5.0 + mobLevel * 1.5;
                    for (Entity entity : deathLocation.getWorld().getNearbyEntities(deathLocation, 3, 3, 3)) {
                        if (entity instanceof Player player) {
                            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                            player.damage(damage);
                            player.sendMessage(ChatColor.RED + " 你被黏液爆炸波及了！");
                        }
                    }
                    cancel();
                    return;
                }
                // 警告粒子 (越來越密集)
                int particleCount = 3 + (ticks / 10);
                deathLocation.getWorld().spawnParticle(Particle.FLAME, deathLocation.clone().add(0, 0.5, 0),
                        particleCount, 0.3, 0.3, 0.3, 0.02);
                if (ticks % 10 == 0) {
                    deathLocation.getWorld().playSound(deathLocation, Sound.BLOCK_NOTE_BLOCK_BASS, 0.8f, 0.5f + (ticks / 40f));
                }
                ticks += 5;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    /**
     * 影襲蜘蛛：短距離瞬移到玩家附近
     */
    private void shadowTeleport(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 12.0);
        if (target == null) return;

        Location playerLoc = target.getLocation();
        // 隨機在玩家周圍 2~4 格瞬移
        double angle = random.nextDouble() * Math.PI * 2;
        double dist = 2.0 + random.nextDouble() * 2.0;
        Location teleportLoc = playerLoc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist);

        // 確保目標位置安全
        teleportLoc.setY(teleportLoc.getWorld().getHighestBlockYAt(teleportLoc) + 1);

        // 起點粒子效果
        Location fromLoc = mob.getLocation();
        fromLoc.getWorld().spawnParticle(Particle.SQUID_INK, fromLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        fromLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, fromLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        fromLoc.getWorld().playSound(fromLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.5f);

        // 瞬移
        mob.teleport(teleportLoc);

        // 終點粒子效果
        teleportLoc.getWorld().spawnParticle(Particle.SQUID_INK, teleportLoc.clone().add(0, 0.5, 0), 15, 0.3, 0.5, 0.3, 0.05);
        teleportLoc.getWorld().spawnParticle(Particle.DRIPPING_OBSIDIAN_TEAR, teleportLoc.clone().add(0, 1, 0), 10, 0.4, 0.6, 0.4, 0);
        teleportLoc.getWorld().playSound(teleportLoc, Sound.ENTITY_ENDERMAN_TELEPORT, 0.6f, 1.8f);
    }

    /**
     * 狂暴野豬：直線衝撞
     */
    private void chargeAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 10.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 3.0 || distance > 10.0) return; // 太近或太遠不衝

        // 衝撞方向
        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 播放音效
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 0.5f, 1.5f);

        // 衝撞動畫 (粒子軌跡)
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 10 || mob.isDead()) {
                    cancel();
                    return;
                }
                mob.setVelocity(direction.clone().multiply(1.2).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        5, 0.2, 0.1, 0.2, 0.02);

                // 碰到玩家就擊退
                for (Entity nearby : mob.getNearbyEntities(1.5, 1.5, 1.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        Vector knockback = direction.clone().multiply(0.8).setY(0.4);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 1.0f, 0.8f);
                        cancel();
                        return;
                    }
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    /**
     * 逃跑型：遠離玩家
     */
    private void fleeFromPlayer(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 8.0);
        if (nearest == null) return;

        // 計算遠離方向
        Vector away = mob.getLocation().toVector()
                .subtract(nearest.getLocation().toVector()).normalize();
        away.setY(0).normalize().multiply(0.5);
        if (random.nextDouble() < 0.3) {
            away.setY(0.2); // 偶爾跳一下
        }
        mob.setVelocity(away);
    }

    /**
     * 骷髏法師：丟出傷害性雪球（標記為魔法雪球）
     */
    private void throwDamagingSnowball(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        Location mobLoc = mob.getEyeLocation();
        Vector direction = target.getEyeLocation().toVector()
                .subtract(mobLoc.toVector()).normalize();

        Snowball snowball = mob.getWorld().spawn(mobLoc, Snowball.class);
        snowball.setVelocity(direction.multiply(1.2));
        snowball.setShooter(mob);

        // 標記這顆雪球為魔法雪球
        snowball.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN, true
        );

        // 紫色粒子
        mob.getWorld().spawnParticle(Particle.WITCH, mobLoc, 5, 0.2, 0.2, 0.2, 0.05);
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_SNOWBALL_THROW, 1.0f, 0.6f);
    }

    /**
     * 處理雪球命中事件 — 骷髏法師的魔法雪球造成傷害
     */
    @EventHandler
    public void onProjectileHit(ProjectileHitEvent event) {
        // === 爆裂骷髏：爆炸箭 ===
        if (event.getEntity() instanceof Arrow arrow) {
            boolean isExplosive = arrow.getPersistentDataContainer().has(
                    new org.bukkit.NamespacedKey(plugin, "explosive_arrow"),
                    org.bukkit.persistence.PersistentDataType.BOOLEAN
            );
            if (isExplosive) {
                Location hitLoc = arrow.getLocation();
                // 小範圍爆炸 (不破壞方塊)
                hitLoc.getWorld().spawnParticle(Particle.EXPLOSION, hitLoc, 2, 0.3, 0.3, 0.3, 0);
                hitLoc.getWorld().spawnParticle(Particle.FLAME, hitLoc, 15, 0.5, 0.5, 0.5, 0.05);
                hitLoc.getWorld().playSound(hitLoc, Sound.ENTITY_GENERIC_EXPLODE, 0.7f, 1.5f);

                // 計算傷害
                double damage = 5.0;
                if (arrow.getShooter() instanceof LivingEntity shooter) {
                    String mobKey = mobManager.getCustomMobKey(shooter);
                    if (mobKey != null) {
                        MobManager.MobData data = mobManager.getMobData(mobKey);
                        int level = mobManager.getMobLevel(shooter);
                        if (data != null) {
                            damage = data.calculateDamage(level) * 0.4;
                        }
                    }
                }

                // 半徑2.5格範圍傷害
                for (Entity nearby : hitLoc.getWorld().getNearbyEntities(hitLoc, 2.5, 2.5, 2.5)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        player.damage(damage);
                    }
                }
                arrow.remove();
                return;
            }
        }

        // === 骷髏法師：魔法雪球 ===
        if (!(event.getEntity() instanceof Snowball snowball)) return;

        // 檢查是否為魔法雪球
        boolean isMagic = snowball.getPersistentDataContainer().has(
                new org.bukkit.NamespacedKey(plugin, "magic_snowball"),
                org.bukkit.persistence.PersistentDataType.BOOLEAN
        );
        if (!isMagic) return;

        // 如果命中實體
        if (event.getHitEntity() instanceof Player player) {
            if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) return;

            // 計算傷害 (根據射擊者等級)
            double damage = 4.0;
            if (snowball.getShooter() instanceof LivingEntity shooter) {
                String mobKey = mobManager.getCustomMobKey(shooter);
                if (mobKey != null) {
                    MobManager.MobData mobData = mobManager.getMobData(mobKey);
                    int level = mobManager.getMobLevel(shooter);
                    if (mobData != null) {
                        damage = mobData.calculateDamage(level) * 0.6;
                    }
                }
            }

            player.damage(damage);
            player.getWorld().spawnParticle(Particle.WITCH, player.getLocation().add(0, 1, 0),
                    10, 0.3, 0.5, 0.3, 0.05);
            player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT, 0.8f, 1.2f);
        }
    }

    /**
     * 潛伏蜘蛛：靠近玩家後隱形（距離8格以內）
     */
    private void stalkerStealth(LivingEntity mob) {
        Player nearest = getNearestPlayer(mob, 12.0);
        if (nearest == null) return;

        double distance = mob.getLocation().distance(nearest.getLocation());

        // 8格以內且尚未隱形 → 進入隱形
        if (distance <= 8.0 && distance > 2.0 && !mob.hasPotionEffect(PotionEffectType.INVISIBILITY)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.INVISIBILITY, 100, 0, false, false)); // 5秒隱形
            mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0), 10, 0.3, 0.3, 0.3, 0.02);
            mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_ILLUSIONER_MIRROR_MOVE, 0.5f, 1.5f);
        }
    }

    /**
     * 瘟疫散播者：周圍持續毒氣（半徑4格）
     */
    private void plagueAura(LivingEntity mob) {
        Location loc = mob.getLocation();

        // 毒氣粒子效果
        mob.getWorld().spawnParticle(Particle.ITEM_SLIME, loc.clone().add(0, 0.5, 0), 5, 1.5, 0.5, 1.5, 0.01);
        mob.getWorld().spawnParticle(Particle.ENTITY_EFFECT, loc.clone().add(0, 0.3, 0), 3, 1.0, 0.3, 1.0, 0);

        // 對4格內的玩家施加中毒
        for (Entity nearby : mob.getNearbyEntities(4, 4, 4)) {
            if (nearby instanceof Player player) {
                if (player.getGameMode() == org.bukkit.GameMode.CREATIVE || player.getGameMode() == org.bukkit.GameMode.SPECTATOR) continue;
                if (!player.hasPotionEffect(PotionEffectType.POISON)) {
                    player.addPotionEffect(new PotionEffect(PotionEffectType.POISON, 80, 0)); // 4秒中毒I
                }
            }
        }
    }

    /**
     * 衝鋒野獸：鎖定後直線衝刺 (更猛烈的衝撞)
     */
    private void chargeBeastAttack(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 15.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 15.0) return;

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.0f, 0.8f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 1.5, 0), 5, 0.3, 0.3, 0.3, 0);

        new BukkitRunnable() {
            int warmup = 20; // 1秒蓄力
            int chargeTicks = 0;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.5, 0),
                            2, 0.2, 0.1, 0.2, 0.01);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 15) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.5).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        8, 0.3, 0.1, 0.3, 0.03);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        5, 0.3, 0.1, 0.3, 0.1, org.bukkit.Material.DIRT.createBlockData());

                // 碰撞檢測
                for (Entity nearby : mob.getNearbyEntities(1.8, 1.8, 1.8)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 + 擊飛
                        Vector knockback = direction.clone().multiply(1.2).setY(0.6);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_PLAYER_HURT_SWEET_BERRY_BUSH, 1.0f, 0.5f);
                        player.getWorld().spawnParticle(Particle.CRIT, player.getLocation().add(0, 1, 0),
                                15, 0.3, 0.3, 0.3, 0.1);
                        cancel();
                        return;
                    }
                }
                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ═══════════════════════════════════════
    //  野外 Boss 專用行為
    // ═══════════════════════════════════════

    /**
     * 豬屍獸：衝撞攻擊（10秒冷卻）
     * 使用 PersistentDataContainer 儲存上次衝撞時間
     */
    private void bossZombieBeastCharge(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 18.0);
        if (target == null) return;

        double distance = mob.getLocation().distance(target.getLocation());
        if (distance < 4.0 || distance > 18.0) return;

        // 檢查冷卻 (10秒 = 10000ms)
        org.bukkit.NamespacedKey cdKey = new org.bukkit.NamespacedKey(plugin, "beast_charge_cd");
        Long lastCharge = mob.getPersistentDataContainer().get(cdKey, org.bukkit.persistence.PersistentDataType.LONG);
        long now = System.currentTimeMillis();
        if (lastCharge != null && (now - lastCharge) < 10000) return;

        // 設定冷卻
        mob.getPersistentDataContainer().set(cdKey, org.bukkit.persistence.PersistentDataType.LONG, now);

        Vector direction = target.getLocation().toVector()
                .subtract(mob.getLocation().toVector()).normalize();

        // 蓄力警告 (1.5秒)
        mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_ROAR, 1.5f, 0.5f);
        mob.getWorld().spawnParticle(Particle.ANGRY_VILLAGER, mob.getLocation().add(0, 2, 0), 8, 0.4, 0.3, 0.4, 0);

        // 通知附近玩家
        for (Entity nearby : mob.getNearbyEntities(18, 18, 18)) {
            if (nearby instanceof Player p) {
                p.sendMessage(ChatColor.RED + "⚠ 豬屍獸正在蓄力衝撞！");
            }
        }

        new BukkitRunnable() {
            int warmup = 30; // 1.5秒蓄力
            int chargeTicks = 0;
            boolean hit = false;
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }

                // 蓄力階段 — 身體泛紅
                if (warmup > 0) {
                    warmup -= 2;
                    mob.getWorld().spawnParticle(Particle.SMOKE, mob.getLocation().add(0, 0.5, 0),
                            3, 0.3, 0.2, 0.3, 0.02);
                    mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0),
                            2, 0.2, 0.2, 0.2, 0);
                    return;
                }

                // 衝刺階段
                if (chargeTicks >= 20 || hit) { cancel(); return; }

                mob.setVelocity(direction.clone().multiply(1.8).setY(0.05));
                mob.getWorld().spawnParticle(Particle.CLOUD, mob.getLocation().add(0, 0.3, 0),
                        10, 0.4, 0.1, 0.4, 0.04);
                mob.getWorld().spawnParticle(Particle.BLOCK, mob.getLocation(),
                        8, 0.4, 0.1, 0.4, 0.1, org.bukkit.Material.NETHERRACK.createBlockData());

                // 碰撞檢測 — 範圍更大、傷害更高
                for (Entity nearby : mob.getNearbyEntities(2.0, 2.0, 2.0)) {
                    if (nearby instanceof Player player) {
                        if (player.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                        // 衝撞傷害 = 怪物傷害 * 2.5
                        int level = mobManager.getMobLevel(mob);
                        String key = mobManager.getCustomMobKey(mob);
                        double chargeDmg = 10.0;
                        if (key != null) {
                            MobManager.MobData data = mobManager.getMobData(key);
                            if (data != null) chargeDmg = data.calculateDamage(level) * 2.5;
                        }
                        player.damage(chargeDmg, mob);

                        // 擊飛
                        Vector knockback = direction.clone().multiply(1.5).setY(0.7);
                        player.setVelocity(knockback);
                        player.getWorld().playSound(player.getLocation(), Sound.ENTITY_IRON_GOLEM_ATTACK, 1.5f, 0.5f);
                        player.getWorld().spawnParticle(Particle.EXPLOSION, player.getLocation().add(0, 1, 0),
                                3, 0.3, 0.3, 0.3, 0);
                        player.sendMessage(ChatColor.RED + " 你被豬屍獸衝撞擊飛了！");
                        hit = true;
                        cancel();
                        return;
                    }
                }

                // 衝撞音效
                if (chargeTicks % 3 == 0) {
                    mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_RAVAGER_STEP, 1.0f, 0.8f);
                }

                chargeTicks++;
            }
        }.runTaskTimer(plugin, 0L, 2L);
    }

    // ══════════════════════════════════════════════════════════
    //  虛擬 HP 系統：傷害 & 回血攔截
    // ══════════════════════════════════════════════════════════

    /**
     * 攔截對「虛擬 HP 怪物」的所有傷害事件
     * 將 MC 傷害按比例轉換為虛擬傷害，並同步 MC HP
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onVirtualHPDamage(EntityDamageEvent event) {
        if (!(event.getEntity() instanceof LivingEntity mob)) return;
        if (!MobManager.hasVirtualHP(mob)) return;

        double finalDamage = event.getFinalDamage();
        if (finalDamage <= 0) return;

        double virtualMaxHp = MobManager.getVirtualMaxHP(mob);
        double currentVirtualHp = MobManager.getVirtualCurrentHP(mob);

        // 比例：1 MC 傷害 = ratio 虛擬傷害
        double ratio = virtualMaxHp / MobManager.getMcMaxHealthCap();
        double virtualDamage = finalDamage * ratio;
        double newVirtualHp = currentVirtualHp - virtualDamage;

        if (newVirtualHp <= 0) {
            // 怪物應死亡 — 儲存虛擬 HP = 0，讓事件通過以觸發死亡
            mob.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                    org.bukkit.persistence.PersistentDataType.DOUBLE, 0.0);
            return; // 不取消 → 讓 Minecraft 自然觸發死亡事件
        }

        // 取消事件，手動扣虛擬 HP 並同步 MC HP
        event.setCancelled(true);

        // 儲存新虛擬 HP
        mob.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                org.bukkit.persistence.PersistentDataType.DOUBLE, newVirtualHp);

        // 計算目標 MC HP
        double targetMcHp = (newVirtualHp / virtualMaxHp) * mob.getMaxHealth();
        targetMcHp = Math.max(0.1, Math.min(targetMcHp, mob.getMaxHealth()));
        final double finalMcHp = targetMcHp;

        // 下一 tick 設定 MC HP（不能在事件中直接 setHealth）
        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isValid() && !mob.isDead()) {
                    mob.setHealth(finalMcHp);
                }
            }
        }.runTask(plugin);

        // === 手動觸發受傷效果（因事件被取消，這些不會自動觸發） ===
        // 受傷音效
        Sound hurtSound = switch (mob.getType()) {
            case ZOMBIE, ZOMBIE_VILLAGER, HUSK, DROWNED, ZOMBIFIED_PIGLIN -> Sound.ENTITY_ZOMBIE_HURT;
            case SKELETON, STRAY, WITHER_SKELETON -> Sound.ENTITY_SKELETON_HURT;
            case SPIDER, CAVE_SPIDER -> Sound.ENTITY_SPIDER_HURT;
            case CREEPER -> Sound.ENTITY_CREEPER_HURT;
            case ENDERMAN -> Sound.ENTITY_ENDERMAN_HURT;
            case BLAZE -> Sound.ENTITY_BLAZE_HURT;
            case MAGMA_CUBE, SLIME -> Sound.ENTITY_SLIME_HURT;
            case GHAST -> Sound.ENTITY_GHAST_HURT;
            case IRON_GOLEM -> Sound.ENTITY_IRON_GOLEM_HURT;
            default -> Sound.ENTITY_GENERIC_HURT;
        };
        mob.getWorld().playSound(mob.getLocation(), hurtSound, 1.0f, 1.0f);

        // 受傷粒子
        Location hurtLoc = mob.getLocation().add(0, mob.getHeight() * 0.6, 0);
        mob.getWorld().spawnParticle(Particle.DAMAGE_INDICATOR, hurtLoc, 1, 0.2, 0.2, 0.2, 0.05);

        // 設定無敵幀（防止連續傷害）
        mob.setNoDamageTicks(10);
    }

    /**
     * 攔截對「虛擬 HP 怪物」的回血事件（如天然再生、藥水效果）
     */
    @EventHandler(priority = EventPriority.HIGH, ignoreCancelled = true)
    public void onVirtualHPHeal(EntityRegainHealthEvent event) {
        if (!(event.getEntity() instanceof LivingEntity mob)) return;
        if (!MobManager.hasVirtualHP(mob)) return;

        double healAmount = event.getAmount();
        if (healAmount <= 0) return;

        double virtualMaxHp = MobManager.getVirtualMaxHP(mob);
        double currentVirtualHp = MobManager.getVirtualCurrentHP(mob);

        double ratio = virtualMaxHp / MobManager.getMcMaxHealthCap();
        double virtualHeal = healAmount * ratio;
        double newVirtualHp = Math.min(virtualMaxHp, currentVirtualHp + virtualHeal);

        event.setCancelled(true);

        mob.getPersistentDataContainer().set(
                new org.bukkit.NamespacedKey(plugin, MobManager.VIRTUAL_CURRENT_HP_KEY),
                org.bukkit.persistence.PersistentDataType.DOUBLE, newVirtualHp);

        double newMcHp = (newVirtualHp / virtualMaxHp) * mob.getMaxHealth();
        final double finalMcHp = Math.min(newMcHp, mob.getMaxHealth());

        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isValid() && !mob.isDead()) {
                    mob.setHealth(finalMcHp);
                }
            }
        }.runTask(plugin);
    }

    /**
     * 防止自訂怪物被陽光燃燒
     * 殭屍、骷髏等不死生物在白天會著火，取消此行為
     */
    @EventHandler
    public void onCustomMobCombust(EntityCombustEvent event) {
        if (!(event.getEntity() instanceof LivingEntity)) return;

        String mobKey = mobManager.getCustomMobKey(event.getEntity());
        if (mobKey != null) {
            // 是自訂怪物 → 取消燃燒
            event.setCancelled(true);
        }
    }

    // ══════════════════════════════════════════════════════════
    //  熔核巨獸 Boss 行為系統
    // ══════════════════════════════════════════════════════════

    /** 主 Boss 每 3 秒執行一次 */
    private void magmaCoreBehavior(LivingEntity mob) {
        // 設定超大體型（只在需要時設定，避免覆蓋血量）
        if (mob instanceof MagmaCube cube && cube.getSize() < 8) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(8);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }

        MagmaCoreState state = magmaCoreStates.computeIfAbsent(mob.getUniqueId(), k -> new MagmaCoreState());
        double maxHp  = MobManager.hasVirtualHP(mob) ? MobManager.getVirtualMaxHP(mob) : mob.getMaxHealth();
        double curHp  = MobManager.hasVirtualHP(mob) ? MobManager.getVirtualCurrentHP(mob) : mob.getHealth();
        double hpPct  = curHp / maxHp;
        long   now    = System.currentTimeMillis();
        Location loc  = mob.getLocation();

        // 固定粒子光環
        loc.getWorld().spawnParticle(Particle.LAVA,  loc.clone().add(0, 2.5, 0), 8, 1.8, 1.0, 1.8, 0);
        loc.getWorld().spawnParticle(Particle.FLAME, loc.clone().add(0, 1.0, 0), 5, 1.0, 0.8, 1.0, 0.02);
        if (hpPct < 0.20) {
            loc.getWorld().spawnParticle(Particle.SOUL_FIRE_FLAME, loc.clone().add(0, 3.5, 0), 12, 1.2, 1.2, 1.2, 0.05);
        }

        // ── 分裂階段管理 ──────────────────────────────────────
        if (state.inSplitPhase) {
            // 清理已死亡分裂體
            state.activeSplits.removeIf(uuid -> {
                Entity e = plugin.getServer().getEntity(uuid);
                return e == null || e.isDead();
            });

            if (state.activeSplits.isEmpty()) {
                // 玩家勝利：所有分裂體被消滅
                state.inSplitPhase = false;
                broadcast(loc, 40, ChatColor.GREEN + "[熔核巨獸] 所有分裂體被消滅！熔核巨獸受到重創！");
            } else if (now > state.splitMergeDeadline) {
                // 時間到：強制融合，恢復 15% HP
                for (UUID uid : state.activeSplits) {
                    Entity e = plugin.getServer().getEntity(uid);
                    if (e != null && !e.isDead()) e.remove();
                }
                state.activeSplits.clear();
                state.inSplitPhase = false;
                double heal = maxHp * 0.15;
                if (MobManager.hasVirtualHP(mob)) {
                    MobManager.healVirtualHP(mob, heal);
                } else {
                    mob.setHealth(Math.min(curHp + heal, maxHp));
                }
                loc.getWorld().spawnParticle(Particle.EXPLOSION, loc.clone().add(0, 2, 0), 20, 2, 2, 2, 0.1);
                loc.getWorld().playSound(loc, Sound.ENTITY_GENERIC_EXPLODE, 2.0f, 0.35f);
                broadcast(loc, 60, ChatColor.DARK_RED + "" + ChatColor.BOLD + "[熔核巨獸] 熔核再生！" + ChatColor.RED + "分裂體重新融合，回復 15% 生命值！");
            } else {
                // 倒計時警告
                long remain = (state.splitMergeDeadline - now) / 1000;
                if (remain == 20 || remain == 10 || remain == 5) {
                    broadcast(loc, 50, ChatColor.YELLOW + "[熔核巨獸] 分裂體融合倒計時：" + ChatColor.RED + remain + "秒！");
                    loc.getWorld().playSound(loc, Sound.BLOCK_NOTE_BLOCK_BASS, 1.0f, 0.5f);
                }
            }
            return; // 分裂期間不使用技能
        }

        // ── 血量門檻觸發分裂 ─────────────────────────────────
        if (hpPct <= 0.75 && state.phase == 1) { state.phase = 2; triggerSplit(mob, state); return; }
        if (hpPct <= 0.50 && state.phase == 2) { state.phase = 3; triggerSplit(mob, state); return; }
        if (hpPct <= 0.25 && state.phase == 3) { state.phase = 4; triggerSplit(mob, state); return; }

        // ── 狂暴模式（≤20%）────────────────────────────────
        if (hpPct <= 0.20 && !state.berserkActive) {
            state.berserkActive = true;
            mob.addPotionEffect(new PotionEffect(PotionEffectType.STRENGTH,  Integer.MAX_VALUE, 2, false, false));
            mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED,     Integer.MAX_VALUE, 1, false, false));
            loc.getWorld().playSound(loc, Sound.ENTITY_ENDER_DRAGON_GROWL, 2.0f, 0.4f);
            broadcast(loc, 80, ChatColor.DARK_RED + "" + ChatColor.BOLD + "⚠ [熔核巨獸] 進入狂暴！！！");
        }

        // 第三/四階段：隨機火柱
        if (state.phase >= 3 && random.nextDouble() < 0.35) {
            spawnFirePillar(mob);
        }

        // ── 技能冷卻（狂暴時縮短）─────────────────────────
        long slamCd  = state.berserkActive ?  8_000L : 14_000L;
        long eruptCd = state.berserkActive ?  6_000L : 10_000L;
        long absorbCd = 25_000L;
        long waveCd  = state.berserkActive ?  8_000L : 15_000L;

        List<Runnable> ready = new ArrayList<>();
        if (now - state.lastSlamMs   > slamCd)  ready.add(() -> magmaLavaSlam(mob, state));
        if (now - state.lastEruptMs  > eruptCd) ready.add(() -> magmaErupt(mob, state));
        if (state.phase >= 2 && now - state.lastAbsorbMs > absorbCd) ready.add(() -> magmaAbsorb(mob, state));
        if (state.phase >= 3 && now - state.lastWaveMs   > waveCd)   ready.add(() -> magmaWave(mob, state));

        if (!ready.isEmpty() && random.nextDouble() < 0.60) {
            ready.get(random.nextInt(ready.size())).run();
        }
    }

    /** 觸發分裂：生成 4 隻中型分裂體，倒計時 30 秒 */
    private void triggerSplit(LivingEntity boss, MagmaCoreState state) {
        Location loc = boss.getLocation();
        state.inSplitPhase = true;
        state.splitMergeDeadline = System.currentTimeMillis() + 30_000L;
        state.activeSplits.clear();

        loc.getWorld().spawnParticle(Particle.EXPLOSION, loc.clone().add(0, 2, 0), 15, 2, 2, 2, 0.1);
        loc.getWorld().playSound(loc, Sound.ENTITY_GENERIC_EXPLODE, 2.0f, 0.3f);
        broadcast(loc, 60, ChatColor.DARK_RED + "" + ChatColor.BOLD + "[熔核巨獸] 熔核分裂！§c在 30 秒內消滅所有分裂體！");
        for (Player p : loc.getWorld().getPlayers()) {
            if (p.getLocation().distance(loc) <= 60) {
                p.sendTitle(ChatColor.RED + "" + ChatColor.BOLD + "⚠ 熔核分裂！", ChatColor.YELLOW + "在 30 秒內擊殺所有分裂體！", 5, 70, 10);
            }
        }

        int level = mobManager.getMobLevel(boss);
        int splitLevel = Math.max(1, level - 5);
        for (int i = 0; i < 4; i++) {
            double angle = (Math.PI * 2.0 / 4) * i;
            Location spawnLoc = loc.clone().add(Math.cos(angle) * 4, 0, Math.sin(angle) * 4);
            spawnLoc.setY(spawnLoc.getWorld().getHighestBlockYAt(spawnLoc) + 1);

            LivingEntity split = mobManager.spawnCustomMobWithLevel("magma_core_medium", spawnLoc, splitLevel);
            if (split != null) {
                split.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
                    org.bukkit.persistence.PersistentDataType.STRING,
                    boss.getUniqueId().toString());
                state.activeSplits.add(split.getUniqueId());
            }
        }
    }

    /** 中型分裂體死亡後，再生成 2 隻小型碎體 */
    private void spawnSmallSplits(LivingEntity medium, int count) {
        Location loc = medium.getLocation();
        String parentUuidStr = medium.getPersistentDataContainer().get(
            new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
            org.bukkit.persistence.PersistentDataType.STRING);

        int level = Math.max(1, mobManager.getMobLevel(medium) - 3);
        for (int i = 0; i < count; i++) {
            double angle = random.nextDouble() * Math.PI * 2;
            Location spawnLoc = loc.clone().add(Math.cos(angle) * 2, 0, Math.sin(angle) * 2);
            spawnLoc.setY(spawnLoc.getWorld().getHighestBlockYAt(spawnLoc) + 1);

            LivingEntity small = mobManager.spawnCustomMobWithLevel("magma_core_small", spawnLoc, level);
            if (small != null && parentUuidStr != null) {
                small.getPersistentDataContainer().set(
                    new org.bukkit.NamespacedKey(plugin, "magma_parent_uuid"),
                    org.bukkit.persistence.PersistentDataType.STRING, parentUuidStr);
                try {
                    MagmaCoreState bossState = magmaCoreStates.get(UUID.fromString(parentUuidStr));
                    if (bossState != null) bossState.activeSplits.add(small.getUniqueId());
                } catch (Exception ignored) {}
            }
        }
    }

    // ── 技能 1：熔岩重壓 ─────────────────────────────────────
    private void magmaLavaSlam(LivingEntity mob, MagmaCoreState state) {
        state.lastSlamMs = System.currentTimeMillis();
        Location loc = mob.getLocation();
        broadcast(loc, 25, ChatColor.RED + "⚠ 熔核巨獸正在蓄力重壓！");
        mob.getWorld().playSound(loc, Sound.ENTITY_MAGMA_CUBE_JUMP, 2.0f, 0.5f);
        mob.setVelocity(new Vector(0, 1.4, 0));
        loc.getWorld().spawnParticle(Particle.LAVA, loc.clone().add(0, 1, 0), 20, 1.5, 0.5, 1.5, 0);

        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isDead()) { cancel(); return; }
                Location landLoc = mob.getLocation();
                landLoc.getWorld().playSound(landLoc, Sound.ENTITY_GENERIC_EXPLODE, 1.8f, 0.35f);

                // 震波粒子環
                for (double r = 1; r <= 7; r += 0.8) {
                    for (double a = 0; a < Math.PI * 2; a += 0.4) {
                        Location pl = landLoc.clone().add(Math.cos(a) * r, 0.1, Math.sin(a) * r);
                        landLoc.getWorld().spawnParticle(Particle.LAVA, pl, 1, 0, 0, 0, 0);
                    }
                }

                // 地面點火
                for (int x = -5; x <= 5; x++) {
                    for (int z = -5; z <= 5; z++) {
                        if (random.nextDouble() < 0.35) {
                            org.bukkit.block.Block above = landLoc.clone().add(x, 0, z).getBlock();
                            org.bukkit.block.Block below = landLoc.clone().add(x, -1, z).getBlock();
                            if (above.getType().isAir() && below.getType().isSolid() && !below.isLiquid()) {
                                above.setType(org.bukkit.Material.FIRE);
                            }
                        }
                    }
                }

                // 擊退 + 傷害玩家
                for (Entity e : landLoc.getWorld().getNearbyEntities(landLoc, 7, 5, 7)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    Vector kb = p.getLocation().toVector().subtract(landLoc.toVector()).normalize().multiply(1.8).setY(0.6);
                    p.setVelocity(kb);
                    p.damage(18.0, mob);
                    p.sendMessage(ChatColor.RED + " 熔核重壓震波！");
                }
                cancel();
            }
        }.runTaskLater(plugin, 32L);
    }

    // ── 技能 2：熔核噴發 ─────────────────────────────────────
    private void magmaErupt(LivingEntity mob, MagmaCoreState state) {
        state.lastEruptMs = System.currentTimeMillis();
        Location loc = mob.getLocation().add(0, 2.5, 0);
        mob.getWorld().playSound(loc, Sound.ENTITY_BLAZE_SHOOT, 1.5f, 0.4f);
        broadcast(mob.getLocation(), 25, ChatColor.RED + "⚠ 熔核噴發！");

        int shots = state.berserkActive ? 12 : 8;
        for (int i = 0; i < shots; i++) {
            double angle = (Math.PI * 2.0 / shots) * i;
            Vector dir = new Vector(Math.cos(angle), 0.25 + random.nextDouble() * 0.25, Math.sin(angle)).normalize().multiply(1.6);
            SmallFireball fb = mob.getWorld().spawn(loc, SmallFireball.class);
            fb.setVelocity(dir);
            fb.setShooter(mob);
            fb.setIsIncendiary(true);
            fb.setYield(2.0f);
        }
    }

    // ── 技能 3：熔岩吞噬 ─────────────────────────────────────
    private void magmaAbsorb(LivingEntity mob, MagmaCoreState state) {
        state.lastAbsorbMs = System.currentTimeMillis();
        Location loc = mob.getLocation();
        broadcast(loc, 30, ChatColor.GOLD + "⚠ 熔核吞噬！摧毀附近的熔岩阻止回血！");
        mob.getWorld().playSound(loc, Sound.BLOCK_LAVA_AMBIENT, 2.0f, 0.5f);

        // 在周圍放 3 塊熔岩（玩家可以清除）
        List<org.bukkit.block.Block> lavaBlocks = new ArrayList<>();
        for (int t = 0; t < 3; t++) {
            double angle = random.nextDouble() * Math.PI * 2;
            int dist = 4 + random.nextInt(4);
            org.bukkit.block.Block above = loc.clone().add(Math.cos(angle) * dist, 0, Math.sin(angle) * dist).getBlock();
            org.bukkit.block.Block below = above.getRelative(org.bukkit.block.BlockFace.DOWN);
            if (above.getType().isAir() && below.getType().isSolid() && !below.isLiquid()) {
                above.setType(org.bukkit.Material.LAVA);
                lavaBlocks.add(above);
            }
        }

        // 吸收粒子動畫
        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (mob.isDead() || ticks >= 20) { cancel(); return; }
                Location center = mob.getLocation().add(0, 1, 0);
                for (int k = 0; k < 8; k++) {
                    double px = center.getX() + (random.nextDouble() - 0.5) * 12;
                    double py = center.getY() + (random.nextDouble() - 0.5) * 4;
                    double pz = center.getZ() + (random.nextDouble() - 0.5) * 12;
                    center.getWorld().spawnParticle(Particle.DRIPPING_LAVA, new Location(center.getWorld(), px, py, pz), 1, 0, 0, 0, 0);
                }
                ticks++;
            }
        }.runTaskTimer(plugin, 0L, 5L);

        // 5 秒後判定
        new BukkitRunnable() {
            @Override
            public void run() {
                if (mob.isDead()) { lavaBlocks.forEach(b -> { if (b.getType() == org.bukkit.Material.LAVA) b.setType(org.bukkit.Material.AIR); }); return; }
                long remaining = lavaBlocks.stream().filter(b -> b.getType() == org.bukkit.Material.LAVA).count();
                if (remaining > 0) {
                    double heal = mob.getMaxHealth() * 0.05 * remaining;
                    if (MobManager.hasVirtualHP(mob)) {
                        MobManager.healVirtualHP(mob, heal);
                        double vCurrent = MobManager.getVirtualCurrentHP(mob);
                        broadcast(mob.getLocation(), 35, ChatColor.RED + "[熔核巨獸] 吸收了熔岩！回復 " + ChatColor.YELLOW + (int)(heal * MobManager.getVirtualMaxHP(mob) / MobManager.getMcMaxHealthCap()) + ChatColor.RED + " 生命值！");
                    } else {
                        mob.setHealth(Math.min(mob.getHealth() + heal, mob.getMaxHealth()));
                        broadcast(mob.getLocation(), 35, ChatColor.RED + "[熔核巨獸] 吸收了熔岩！回復 " + ChatColor.YELLOW + (int) heal + ChatColor.RED + " 生命值！");
                    }
                    mob.getWorld().spawnParticle(Particle.HEART, mob.getLocation().add(0, 3, 0), 10, 0.5, 0.5, 0.5, 0.1);
                } else {
                    broadcast(mob.getLocation(), 35, ChatColor.GREEN + "[熔核巨獸] 熔岩被全數摧毀！回血被阻止！");
                }
                lavaBlocks.forEach(b -> { if (b.getType() == org.bukkit.Material.LAVA) b.setType(org.bukkit.Material.AIR); });
            }
        }.runTaskLater(plugin, 100L);
    }

    // ── 技能 4：岩漿浪潮 ─────────────────────────────────────
    private void magmaWave(LivingEntity mob, MagmaCoreState state) {
        state.lastWaveMs = System.currentTimeMillis();
        Player target = getNearestPlayer(mob, 28.0);
        if (target == null) return;

        Location mobLoc = mob.getLocation();
        Vector toward = target.getLocation().toVector().subtract(mobLoc.toVector()).normalize();
        mob.getWorld().playSound(mobLoc, Sound.ENTITY_MAGMA_CUBE_SQUISH_SMALL, 2.0f, 0.35f);
        broadcast(mobLoc, 28, ChatColor.RED + "⚠ 岩漿浪潮！");

        new BukkitRunnable() {
            int wave = 0;
            @Override
            public void run() {
                if (wave >= 9 || mob.isDead()) { cancel(); return; }
                double dist = 2.5 + wave * 1.8;
                // 扇形粒子
                for (double a = -Math.PI / 3; a <= Math.PI / 3; a += 0.25) {
                    double sx = Math.cos(a) * toward.getX() - Math.sin(a) * toward.getZ();
                    double sz = Math.sin(a) * toward.getX() + Math.cos(a) * toward.getZ();
                    Location pl = mobLoc.clone().add(sx * dist, 0.5, sz * dist);
                    mobLoc.getWorld().spawnParticle(Particle.LAVA, pl, 2, 0.1, 0.2, 0.1, 0);
                    mobLoc.getWorld().spawnParticle(Particle.FLAME, pl, 1, 0, 0, 0, 0.04);
                }
                // 波浪中心傷害
                Location waveCenter = mobLoc.clone().add(toward.clone().multiply(dist)).add(0, 0.5, 0);
                for (Entity e : waveCenter.getWorld().getNearbyEntities(waveCenter, 3, 2, 3)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    p.setVelocity(toward.clone().multiply(1.5).setY(0.35));
                    p.setFireTicks(80);
                    p.damage(8.0, mob);
                    p.sendMessage(ChatColor.RED + " 岩漿浪潮衝擊！");
                }
                wave++;
            }
        }.runTaskTimer(plugin, 0L, 5L);
    }

    // ── 第三/四階段：火柱 ────────────────────────────────────
    private void spawnFirePillar(LivingEntity mob) {
        Player target = getNearestPlayer(mob, 28.0);
        if (target == null) return;
        Location pillarLoc = target.getLocation().clone().add(
            (random.nextDouble() - 0.5) * 8, 0, (random.nextDouble() - 0.5) * 8);
        pillarLoc.setY(pillarLoc.getWorld().getHighestBlockYAt(pillarLoc));
        final Location finalLoc = pillarLoc;

        // 0.5s 警告後火柱噴發
        new BukkitRunnable() {
            @Override
            public void run() {
                finalLoc.getWorld().spawnParticle(Particle.SMOKE, finalLoc.clone().add(0, 0.5, 0), 6, 0.3, 0, 0.3, 0.02);
            }
        }.runTaskTimer(plugin, 0L, 5L);

        new BukkitRunnable() {
            int ticks = 0;
            @Override
            public void run() {
                if (ticks >= 30 || mob.isDead()) { cancel(); return; }
                for (int h = 0; h <= 5; h++) {
                    finalLoc.getWorld().spawnParticle(Particle.FLAME, finalLoc.clone().add(0, h, 0), 4, 0.3, 0, 0.3, 0.06);
                    finalLoc.getWorld().spawnParticle(Particle.LAVA,  finalLoc.clone().add(0, h, 0), 1, 0.2, 0, 0.2, 0);
                }
                for (Entity e : finalLoc.getWorld().getNearbyEntities(finalLoc, 1.5, 6, 1.5)) {
                    if (!(e instanceof Player p) || p.getGameMode() == org.bukkit.GameMode.CREATIVE) continue;
                    p.setFireTicks(60);
                    p.damage(5.0, mob);
                }
                ticks += 5;
            }
        }.runTaskLater(plugin, 10L);
    }

    // ── 中型分裂體行為 ────────────────────────────────────────
    private void magmaMediumBehavior(LivingEntity mob) {
        if (mob instanceof MagmaCube cube && cube.getSize() < 3) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(3);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }
        mob.getWorld().spawnParticle(Particle.LAVA, mob.getLocation().add(0, 1, 0), 3, 0.5, 0.3, 0.5, 0);
        // 25% 機率朝最近玩家跳躍
        if (random.nextDouble() < 0.25) {
            Player t = getNearestPlayer(mob, 16.0);
            if (t != null) {
                Vector leap = t.getLocation().toVector().subtract(mob.getLocation().toVector())
                    .normalize().multiply(1.0).setY(0.9);
                mob.setVelocity(leap);
                mob.getWorld().playSound(mob.getLocation(), Sound.ENTITY_MAGMA_CUBE_JUMP, 1.0f, 0.7f);
            }
        }
    }

    // ── 小型碎體行為 ─────────────────────────────────────────
    private void magmaSmallBehavior(LivingEntity mob) {
        if (mob instanceof MagmaCube cube && cube.getSize() != 1) {
            double maxHp = mob.getMaxHealth();
            double curHp = mob.getHealth();
            cube.setSize(1);
            org.bukkit.attribute.AttributeInstance attr = mob.getAttribute(org.bukkit.attribute.Attribute.MAX_HEALTH);
            if (attr != null) attr.setBaseValue(maxHp);
            mob.setHealth(Math.min(curHp, maxHp));
        }
        if (!mob.hasPotionEffect(PotionEffectType.SPEED)) {
            mob.addPotionEffect(new PotionEffect(PotionEffectType.SPEED, 120, 3, false, false));
        }
        mob.getWorld().spawnParticle(Particle.FLAME, mob.getLocation().add(0, 0.3, 0), 2, 0.2, 0.2, 0.2, 0.02);
    }

    /** 向 Boss 周圍玩家廣播訊息 */
    private void broadcast(Location center, double radius, String msg) {
        for (Player p : center.getWorld().getPlayers()) {
            if (p.getLocation().distance(center) <= radius) {
                p.sendMessage(msg);
            }
        }
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.Particle;
import org.bukkit.Sound;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.scheduler.BukkitRunnable;

import java.util.*;
import java.util.concurrent.ConcurrentHashMap;

/**
 * FocusManager — 風獵者專注系統
 *
 * 管理：
 * 1. 專注值 (0-10)  → 狙擊者支線用
 * 2. 連擊數 (0-10)  → 遊俠支線用
 * 3. 靜止偵測       → 判斷玩家是否未移動
 * 4. 追蹤標記       → 標記特定目標增傷
 */
public class FocusManager {

    private final CustomRPG plugin;

    // 專注值 Map<PlayerUUID, focus>
    private final Map<UUID, Integer> focusMap = new ConcurrentHashMap<>();
    // 連擊數 Map<PlayerUUID, combo>
    private final Map<UUID, Integer> comboMap = new ConcurrentHashMap<>();
    // 上次獲得專注的時間（用於衰減延遲）
    private final Map<UUID, Long> lastFocusGainTime = new ConcurrentHashMap<>();
    // 上次命中時間（用於連擊衰減）
    private final Map<UUID, Long> lastComboTime = new ConcurrentHashMap<>();
    // 上次記錄位置（靜止偵測）
    private final Map<UUID, Location> lastPositions = new ConcurrentHashMap<>();
    // 標記目標 Map<PlayerUUID, TargetUUID>
    private final Map<UUID, UUID> markedTargets = new ConcurrentHashMap<>();
    // 標記到期時間 Map<PlayerUUID, expiryMs>
    private final Map<UUID, Long> markExpiries = new ConcurrentHashMap<>();

    public static final int MAX_FOCUS = 10;
    public static final int MAX_COMBO = 10;

    /** 專注衰減延遲（毫秒） */
    private static final long FOCUS_DECAY_DELAY_MS = 5000L;
    /** 連擊衰減延遲（毫秒） */
    private static final long COMBO_DECAY_DELAY_MS = 5000L;

    public FocusManager(CustomRPG plugin) {
        this.plugin = plugin;
        startDecayTask();
        startPositionSnapshotTask();
    }

    // ══════════════════════════════════════════
    //  專注值管理
    // ══════════════════════════════════════════

    /**
     * 增加玩家專注值
     */
    public void addFocus(Player player, int amount) {
        UUID pid = player.getUniqueId();
        int current = focusMap.getOrDefault(pid, 0);
        int newFocus = Math.min(MAX_FOCUS, current + amount);
        focusMap.put(pid, newFocus);
        lastFocusGainTime.put(pid, System.currentTimeMillis());

        showFocusBar(player, newFocus);

        if (newFocus == MAX_FOCUS && current < MAX_FOCUS) {
            player.sendMessage("§e§l[專注] §6MAX FOCUS！終極技能已解鎖！");
            player.playSound(player.getLocation(), Sound.ENTITY_EXPERIENCE_ORB_PICKUP, 1.0f, 1.6f);
            player.getWorld().spawnParticle(Particle.ENCHANT,
                    player.getLocation().add(0, 1.2, 0), 25, 0.4, 0.6, 0.4, 0.6);
        }
    }

    /** 消耗指定數量的專注 */
    public void consumeFocus(Player player, int amount) {
        UUID pid = player.getUniqueId();
        focusMap.put(pid, Math.max(0, focusMap.getOrDefault(pid, 0) - amount));
    }

    /** 消耗全部專注，回傳消耗前的數量 */
    public int consumeAllFocus(Player player) {
        UUID pid = player.getUniqueId();
        int before = focusMap.getOrDefault(pid, 0);
        focusMap.put(pid, 0);
        return before;
    }

    /** 取得玩家目前專注值 */
    public int getFocus(Player player) {
        return focusMap.getOrDefault(player.getUniqueId(), 0);
    }

    /** 直接重置專注 */
    public void resetFocus(Player player) {
        focusMap.put(player.getUniqueId(), 0);
    }

    // ══════════════════════════════════════════
    //  連擊管理
    // ══════════════════════════════════════════

    /** 增加一層連擊 */
    public void addCombo(Player player) {
        UUID pid = player.getUniqueId();
        int current = comboMap.getOrDefault(pid, 0);
        comboMap.put(pid, Math.min(MAX_COMBO, current + 1));
        lastComboTime.put(pid, System.currentTimeMillis());
    }

    /** 取得當前連擊數 */
    public int getCombo(Player player) {
        return comboMap.getOrDefault(player.getUniqueId(), 0);
    }

    /** 消耗全部連擊，回傳消耗前數量 */
    public int consumeAllCombo(Player player) {
        UUID pid = player.getUniqueId();
        int before = comboMap.getOrDefault(pid, 0);
        comboMap.put(pid, 0);
        return before;
    }

    /** 重置連擊 */
    public void resetCombo(Player player) {
        comboMap.put(player.getUniqueId(), 0);
    }

    // ══════════════════════════════════════════
    //  靜止偵測
    // ══════════════════════════════════════════

    /**
     * 判斷玩家是否在過去 0.5 秒內靜止不動（XZ 位移 < 0.15 格）
     */
    public boolean isStill(Player player) {
        Location last = lastPositions.get(player.getUniqueId());
        if (last == null) return false;
        Location cur = player.getLocation();
        double dx = cur.getX() - last.getX();
        double dz = cur.getZ() - last.getZ();
        return Math.sqrt(dx * dx + dz * dz) < 0.15;
    }

    // ══════════════════════════════════════════
    //  追蹤標記系統
    // ══════════════════════════════════════════

    /**
     * 標記目標
     * @param player 標記者
     * @param target 被標記實體
     * @param durationTicks 持續 tick 數
     */
    public void markTarget(Player player, LivingEntity target, int durationTicks) {
        UUID pid = player.getUniqueId();
        markedTargets.put(pid, target.getUniqueId());
        markExpiries.put(pid, System.currentTimeMillis() + durationTicks * 50L);

        target.setGlowing(true);
        Bukkit.getScheduler().runTaskLater(plugin, () -> {
            if (!isMarked(player, target)) {
                target.setGlowing(false);
            }
        }, durationTicks);
    }

    /**
     * 判斷指定實體是否被該玩家標記
     */
    public boolean isMarked(Player player, LivingEntity entity) {
        UUID pid = player.getUniqueId();
        UUID targetId = markedTargets.get(pid);
        if (targetId == null) return false;
        Long expiry = markExpiries.get(pid);
        if (expiry == null || System.currentTimeMillis() > expiry) {
            markedTargets.remove(pid);
            markExpiries.remove(pid);
            return false;
        }
        return targetId.equals(entity.getUniqueId());
    }

    // ══════════════════════════════════════════
    //  清理
    // ══════════════════════════════════════════

    /** 玩家下線時清理所有狀態 */
    public void cleanup(Player player) {
        UUID pid = player.getUniqueId();
        focusMap.remove(pid);
        comboMap.remove(pid);
        lastFocusGainTime.remove(pid);
        lastComboTime.remove(pid);
        lastPositions.remove(pid);
        markedTargets.remove(pid);
        markExpiries.remove(pid);
    }

    // ══════════════════════════════════════════
    //  內部工具
    // ══════════════════════════════════════════

    /** 在 ActionBar 顯示專注條 */
    public void showFocusBar(Player player, int focus) {
        StringBuilder bar = new StringBuilder("§e[專注] ");
        for (int i = 0; i < MAX_FOCUS; i++) {
            bar.append(i < focus ? "§6◆" : "§8◇");
        }
        bar.append("  §f").append(focus).append("/").append(MAX_FOCUS);
        player.sendActionBar(bar.toString());
    }

    /** 啟動專注 & 連擊衰減任務（每 40 ticks / 2 秒） */
    private void startDecayTask() {
        new BukkitRunnable() {
            @Override
            public void run() {
                long now = System.currentTimeMillis();

                // 專注衰減：每次掉 1 點，直到歸零
                for (Map.Entry<UUID, Integer> entry : focusMap.entrySet()) {
                    if (entry.getValue() <= 0) continue;
                    Long last = lastFocusGainTime.get(entry.getKey());
                    if (last == null || now - last > FOCUS_DECAY_DELAY_MS) {
                        entry.setValue(entry.getValue() - 1);
                        if (entry.getValue() > 0) {
                            // 每衰減一次，重新計時（保持每 2 秒衰減一點的速度）
                            lastFocusGainTime.put(entry.getKey(), now);
                        }
                        Player p = Bukkit.getPlayer(entry.getKey());
                        if (p != null && entry.getValue() > 0) {
                            showFocusBar(p, entry.getValue());
                        }
                    }
                }

                // 連擊衰減：超過延遲後直接清零
                for (Map.Entry<UUID, Integer> entry : comboMap.entrySet()) {
                    if (entry.getValue() <= 0) continue;
                    Long last = lastComboTime.get(entry.getKey());
                    if (last == null || now - last > COMBO_DECAY_DELAY_MS) {
                        entry.setValue(0);
                    }
                }
            }
        }.runTaskTimer(plugin, 40L, 40L);
    }

    /** 啟動位置快照任務（每 10 ticks 更新一次，用於靜止偵測） */
    private void startPositionSnapshotTask() {
        new BukkitRunnable() {
            @Override
            public void run() {
                for (Player p : Bukkit.getOnlinePlayers()) {
                    lastPositions.put(p.getUniqueId(), p.getLocation().clone());
                }
            }
        }.runTaskTimer(plugin, 10L, 10L);
    }
}

package com.customrpg.managers;

import com.customrpg.CustomRPG;
import org.bukkit.Location;
import org.bukkit.configuration.ConfigurationSection;
import org.bukkit.configuration.file.FileConfiguration;
import org.bukkit.configuration.file.YamlConfiguration;

import java.io.File;
import java.util.ArrayList;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

/**
 * SafeZoneManager - 管理圓形安全區域
 */
public class SafeZoneManager {

    private final CustomRPG plugin;
    private final File configFile;
    private final Map<String, SafeZone> safeZones = new LinkedHashMap<>();

    public SafeZoneManager(CustomRPG plugin) {
        this.plugin = plugin;
        this.configFile = new File(plugin.getDataFolder(), "config/safe_zones.yml");
        load();
    }

    public void reload() {
        load();
    }

    private void load() {
        safeZones.clear();

        if (!configFile.exists()) {
            plugin.saveResource("config/safe_zones.yml", false);
        }

        FileConfiguration config = YamlConfiguration.loadConfiguration(configFile);
        ConfigurationSection zonesSection = config.getConfigurationSection("zones");
        if (zonesSection == null) {
            plugin.getLogger().warning("[SafeZoneManager] No zones section found in config/safe_zones.yml");
            return;
        }

        for (String id : zonesSection.getKeys(false)) {
            ConfigurationSection section = zonesSection.getConfigurationSection(id);
            if (section == null) {
                continue;
            }

            String world = section.getString("world", "world");
            String name = section.getString("name", id);
            String type = section.getString("type", "SAFE_ZONE");
            double x = section.getDouble("center.x");
            double y = section.getDouble("center.y");
            double z = section.getDouble("center.z");
            double radius = Math.max(1.0, section.getDouble("radius", 200.0));

            safeZones.put(id.toLowerCase(), new SafeZone(id, name, type, world, x, y, z, radius));
        }

        plugin.getLogger().info("[SafeZoneManager] Loaded " + safeZones.size() + " safe zones");
    }

    public boolean isInSafeZone(Location location) {
        return getZoneAt(location) != null;
    }

    public SafeZone getZoneAt(Location location) {
        if (location == null || location.getWorld() == null) {
            return null;
        }

        String worldName = location.getWorld().getName();
        for (SafeZone zone : safeZones.values()) {
            if (zone.contains(worldName, location.getX(), location.getY(), location.getZ())) {
                return zone;
            }
        }
        return null;
    }

    public int getZoneCount() {
        return safeZones.size();
    }

    public Collection<SafeZone> getZones() {
        return new ArrayList<>(safeZones.values());
    }

    public static class SafeZone {
        private final String id;
        private final String name;
        private final String type;
        private final String world;
        private final double x;
        private final double y;
        private final double z;
        private final double radius;
        private final double radiusSquared;

        public SafeZone(String id, String name, String type, String world,
                        double x, double y, double z, double radius) {
            this.id = id;
            this.name = name;
            this.type = type;
            this.world = world;
            this.x = x;
            this.y = y;
            this.z = z;
            this.radius = radius;
            this.radiusSquared = radius * radius;
        }

        public boolean contains(String worldName, double targetX, double targetY, double targetZ) {
            if (!world.equalsIgnoreCase(worldName)) {
                return false;
            }
            double dx = targetX - x;
            double dy = targetY - y;
            double dz = targetZ - z;
            return (dx * dx) + (dy * dy) + (dz * dz) <= radiusSquared;
        }

        public String getId() {
            return id;
        }

        public String getName() {
            return name;
        }

        public String getType() {
            return type;
        }

        public String getWorld() {
            return world;
        }

        public double getX() {
            return x;
        }

        public double getY() {
            return y;
        }

        public double getZ() {
            return z;
        }

        public double getRadius() {
            return radius;
        }
    }
}
